-- Generated: 2026-08-20. Source: Cookie Run Kingdom Wiki

TRUNCATE cookies RESTART IDENTITY CASCADE;

INSERT INTO cookies (name, type, position, rarity, image_file, release_date,
                     elements, recommended_toppings, skill_name, skill_cooldown,
                     skill_description, quote, description, traits, voice_actor) VALUES
('GingerBrave', 'Charge', 'Front', 'Common', 'gingerbrave.png', '2021-01-21', '{}'::text[], ARRAY['raspberry', 'almond', 'chocolate']::text[], 'Brave Dash|Cooldown=8', '8', 'Dashes forward and deals area damage to all enemies in his way.', 'Ha ha! Adventures await!', 'GingerBrave was the first Cookie to escape from the Witch''s oven. It is unknown how this Cookie came to life, but rumor has it that the Witch accidentally used magic powder instead of ginger powder.', 'Brave, Venturous', 'Jeremy Shada'),
('Strawberry Cookie', 'Defense', 'Front', 'Common', 'strawberry-cookie.png', '2021-01-21', '{}'::text[], ARRAY['raspberry', 'almond']::text[], 'Don''t Come Near!|Cooldown=10|Description=Scared Strawberry Cookie spins with her lollipop, dealing damage to all enemies within range.', '10|Description=Scared Strawberry Cookie spins with her lollipop, dealing damage to all enemies within range.', 'Scared Strawberry Cookie spins with her lollipop, dealing damage to all enemies within range.', 'So you wanna be... um... my friend?', 'Shyness can be quite advantageous. Why? Strawberry Cookie contains no real strawberries, only the flavoring. Were she as active and energetic as other Cookies, her artificial strawberry fragrance would have worn off in no time! Strawberry Cookie feels so ashamed of her main ingredient, she''d never want the truth to come out. If only she understood that this yummy strawberry scent is one of the many reasons other Cookies love her!', 'Attentive, Thorough', 'Anairis Quiñones'),
('Ninja Cookie', 'Ambush', 'Middle', 'Common', 'ninja-cookie.png', '2021-01-21', '{}'::text[], ARRAY['raspberry']::text[], 'Swift Strike|Cooldown=11|Description=Jumps in the air, throwing shuriken twice and causing small-area damage.', '11|Description=Jumps in the air, throwing shuriken twice and causing small-area damage.', 'Jumps in the air, throwing shuriken twice and causing small-area damage.', 'Swift as the wind.', 'Just as making perfect dough demands diligent kneading, tireless training is of equal importance on the path of the ninja. The flavor and ingredients of the mysterious Ninja Cookie remain unknown. He is the only Cookie who can jump that many times. Some say he steps on the air itself, others claim he is using some sort of a shadow clone technique... And with training, he can jump even higher! Sky''s the limit, literally.', 'Agile, Sharp-eyed', 'Stephen Fu'),
('Angel Cookie', 'Healing', 'Rear', 'Common', 'angel-cookie.png', '2021-01-21', '{}'::text[], ARRAY['chocolate']::text[], 'Celestial Light|Cooldown=15', '15', 'Blessed be the Cookies! Flies up in the air, restoring HP of all party members.', 'Come fly with me...', 'Angel Cookie is trying to master the art of flying but can''t rise higher than a teeny tiny bit above the ground just yet! Angel Cookie''s favorite animals are penguins, ostriches, and baby chicks. Can you guess why? The Cookie''s shiny golden curls are truly special. Not only do they grant their owner healing powers, they are remarkably lovely to look at!', 'Flying, Independent', 'Erika Ishii'),
('Muscle Cookie', 'Charge', 'Front', 'Common', 'muscle-cookie.png', '2021-01-21', ARRAY['steel']::text[], ARRAY['almond']::text[], 'Muscle King Power|Cooldown = 10', '10', 'Throws a dumbbell with fearsome strength at the nearby enemies, when throwing and when the dumbbell falls.', 'Gosh, do you even lift?', 'Muscle Cookie''s recipe requires large quantities of protein powder and about three weeks of intensive kneading. Only after that, the taste of raw muscle power comes to life. Such a rigorous cooking process has made Muscle Cookie a bit short-tempered. He tends to throw exercise equipment when angry. But don''t be afraid: once he''s done dealing with Cake Monsters, he''s as cool as a cucumber.', 'Brawny, Serene', 'Jimmy Chau (Credited as: OJ)'),
('Wizard Cookie', 'Magic', 'Middle', 'Common', 'wizard-cookie.png', '2021-01-21', ARRAY['electricity']::text[], ARRAY['raspberry']::text[], 'Magic Storm|Cooldown=13', '13', 'Summons a magic lightning storm that moves forward, dealing periodic damage and inflicting Zap to all enemies within range.', 'Abra-Cookie-Cadabra!', 'Wizard Cookie came to possess the Witch''s Candy Wand by accident (or not?). Within it, he discovered unique magical powers. His popping candy ice cream cone hat is the finishing touch to his wizard look. Frequently used spells include the festive Hocus-Party-Pocus and Abra-Cookie-Cadabra, which brings unexpected luck and fun.', 'Analytical, Handy', 'Kyle McCarley'),
('Beet Cookie', 'Ranged', 'Rear', 'Common', 'beet-cookie.png', '2021-01-21', '{}'::text[], ARRAY['chocolate', 'raspberry']::text[], 'Hunter''s Sense', '12', 'Shoots several bolts in a row at a target with the lowest HP. The bolt also casts a debuff reducing Healing. Don''t mess with a hunter!', 'Day 1,000 at this current camp!', 'A strong, persistent, rocky-soil-enduring wild beet was used in the making of Beet Cookie. This Cookie not only inherited all these qualities of her mother ingredient but also went up a notch, becoming able to survive just about anywhere! Beet Cookie settled in the deep forest and has been protecting her territory with her trusty crossbow ever since. Storm, rain, blizzard, or vicious predators—no threat is too serious. There''s only one thing that can spring a surprise on this lonely ranger: unexpected Cookie visitors.', 'Thorough, Sharp-eyed', 'Elysia Rotaru'),
('Devil Cookie', 'Magic', 'Middle', 'Rare', 'devil-cookie.png', '2021-05-28', ARRAY['darkness']::text[], ARRAY['chocolate', 'raspberry']::text[], 'Devilish Rune|Cooldown=18', '18', 'Summons the Devilish Rune dealing damage over time to enemies standing on it and reducing their ATK SPD and MOV SPD.', 'Don''t worry, I won''t hurt you... or will I?', 'Devil Cookie is mysterious in many ways. This Cookie might look hot and spicy but tastes like fizzy cola. According to a trustworthy source, they are made of bat extract and a few drops of carbonated beverage. Little trickster''s ultrasonic powers allow them to see Cookie souls invisible to the others. Devil Cookie is also capable of summoning the horribly powerful and tremendously sugary Devilish Rune straight from the fiery lower trays of existence.', 'Flying, Analytical', 'Aleks Le'),
('Custard Cookie III', 'Healing', 'Rear', 'Rare', 'custard-cookie-iii.png', '2021-01-21', '{}'::text[], ARRAY['raspberry']::text[], 'King''s Favor|Cooldown=16', '16', 'Heals two Cookies with the lowest HP and also casts a short-living HP Shield. ''Cause that''s what kings do!', '1=Ah, another of my faithful servants! You may speak!', 'Even before the custard on his head started to take shape, this little Cookie dreamed of becoming a glorious king, worthy of the title borne by the greatest rulers of the past. Custard Cookie III, as he prefers to call himself, may not rule anything yet, but looking at how active he is at waving his scepter and giving orders, it is only a matter of time before he sits on a real throne. And his determination is remarkable! Made of simple colored paper, his royal regalia looked so realistic that even the notorious', 'Lucky, Curious', 'Jaimie Kelton'),
('Clover Cookie', 'Support', 'Rear', 'Rare', 'clover-cookie.png', '2021-01-21', '{}'::text[], ARRAY['chocolate']::text[], 'Bard''s Song|Cooldown = 17', '17', 'Tough times are when music is needed the most. The Cookie plays a soothing song, removing all debuffs from party members and applying a buff that slowly restores their HP.', 'May luck follow you in your adventures...', 'A brightly sunlit summer glade covered with soft clovers. A forest brook murmuring gently not afar. A delicate breeze whispering secrets to your ear. A joyful bustle of a Cookie crowd. Clover Cookie wanders the land in search of inspiration for his poetry of the everyday. Two crunchy feet and a long road ahead, the old grass-woven lute behind his back, and someone to sing a song to—what else is needed to be happy? Sing along, and Clover Cookie''s ballad will flow far away, over the forests and ridges of the Cookie World.', 'Handy, Venturous', 'Lucien Dodge'),
('Carrot Cookie', 'Support', 'Middle', 'Rare', 'carrot-cookie.png', '2021-01-21', ARRAY['grass']::text[], ARRAY['chocolate']::text[], 'Carrot Harvest|Cooldown=19|Description=Pulls the hardest carrots from the ground and shoots them at the enemy, causing area damage and increasing the party''s Defense. Carrots collected after an attack restore some HP.', '19|Description=Pulls the hardest carrots from the ground and shoots them at the enemy, causing area damage and increasing the party''s Defense. Carrots collected after an attack restore some HP.', 'Pulls the hardest carrots from the ground and shoots them at the enemy, causing area damage and increasing the party''s Defense. Carrots collected after an attack restore some HP.', 'Time to farm!', NULL, 'Brave, Nature-loving', 'Rosanna Pansino'),
('Avocado Cookie', 'Defense', 'Front', 'Rare', 'avocado-cookie.png', '2021-01-21', ARRAY['steel']::text[], ARRAY['almond']::text[], 'Battle Smithing|Cooldown = 12', '12', 'Strikes the ground with her hammer several times, dealing area damage. The clear sound of ringing metal raises the party''s Morale, increasing Attack Power of the Cookie with the highest Attack Power.', 'What do you call a fish with no eye? FSH! Haha!', 'Gather some avocados (the more, the better!) ripened under the hot sun (the more ripe, the better!), then mash, mash, MASH! That''s how you can make a healthy and nutritious Avocado Cookie! But you know what terribly lacked nutrients growing up? Her sense of humor! And you will soon know why. Avocado Cookie is a famous master smith. She spends days and nights at the smithy making this and that. It is said that Avocado Cookie can create just about anything! Except for a decent joke, ahem.', 'Handy, Brawny', 'Courtenay Taylor'),
('Pancake Cookie', 'Ambush', 'Rear', 'Rare', 'pancake-cookie.png', '2021-01-21', '{}'::text[], ARRAY['raspberry', 'chocolate']::text[], 'Take an Acorn!|Cooldown=15|Description=Flies forward, throwing acorns at the enemies causing wide area damage and increasing the party''s Attack Speed.', '15|Description=Flies forward, throwing acorns at the enemies causing wide area damage and increasing the party''s Attack Speed.', 'Flies forward, throwing acorns at the enemies causing wide area damage and increasing the party''s Attack Speed.', '1=Let''s play! Let''s fly!', NULL, 'Flying, Intuitive', 'Alexandra Teran (Credited as: InquisitorMaster)'),
('Onion Cookie', 'Support', 'Middle', 'Rare', 'onion-cookie.png', '2021-01-21', '{}'::text[], ARRAY['chocolate', 'caramel']::text[], 'Unstoppable Tears|Cooldown=19|Description=Doesn''t perform Regular Attacks frozen in fear. Use this skill to let out a deafening cry, causing wide area damage and lowering the enemy''s Attack Power. The higher the fear level, the more powerful the skill.', '19|Description=Doesn''t perform Regular Attacks frozen in fear. Use this skill to let out a deafening cry, causing wide area damage and lowering the enemy''s Attack Power. The higher the fear level, the more powerful the skill.', 'Doesn''t perform Regular Attacks frozen in fear. Use this skill to let out a deafening cry, causing wide area damage and lowering the enemy''s Attack Power. The higher the fear level, the more powerful the skill.', '1=There aren''t any ghosts here, are there?', NULL, 'Attentive, Thorough', 'Lily Ki (Credited as: LilyPichu)'),
('Gumball Cookie', 'Bomber', 'Rear', 'Rare', 'gumball-cookie.png', '2021-01-21', '{}'::text[], ARRAY['raspberry']::text[], 'Art-illery|Cooldown=13|Description=Boom-boom-boom! The Cookie shoots three bubble gum charges at the enemies, each causing area damage and decreasing the enemies'' Attacking Speed.', '13|Description=Boom-boom-boom! The Cookie shoots three bubble gum charges at the enemies, each causing area damage and decreasing the enemies'' Attacking Speed.', 'Boom-boom-boom! The Cookie shoots three bubble gum charges at the enemies, each causing area damage and decreasing the enemies'' Attacking Speed.', '1=Let''s add some color here! Woohoo!', NULL, 'Tenacious, Curious', 'Caylus Cunningham (Credited as: Caylus)'),
('Blackberry Cookie', 'Magic', 'Rear', 'Rare', 'blackberry-cookie.png', '2021-01-21', '{}'::text[], ARRAY['chocolate']::text[], 'Ghost Servants', '15', 'The ghosts rush through the enemy formation, striking them several times; increasing the party''s CRIT% and ATK SPD, and casting an HP Shield.', 'Is there anything I can do for you?', 'Blackberry Cookie always wears a reserved look, but it would be hard to find a more caring and devoted Cookie. She has been working at one prestigious household for a long time, and is praised for her miraculous ability to do a multitude of tasks in virtually no time! Despite Blackberry Cookie''s tightest schedule, she always finds the time to save the life of her . Perhaps, this is her main duty these days.', 'Attentive, Sharp-eyed', 'Michelle Phan'),
('Adventurer Cookie', 'Ambush', 'Middle', 'Rare', 'adventurer-cookie.png', '2021-01-21', '{}'::text[], ARRAY['raspberry']::text[], 'Rope Master|Cooldown = 12', '12', 'They''re not expecting it! Adventurer Cookie appears behind the rearmost enemy, attacks with a rope and incapacitates them.', 'A whole world to explore!', 'For a long time, there have been only rumors of Adventurer Cookie''s travels far and wide beyond the Witch''s island, but now he''s back and ready to guide the other Cookies into uncharted territories of a new exciting world. Adventurer Cookie has got quite a lot of stories to tell: about legendary dragons, kingdoms in ruins, but... So little time! His thirst for the unknown is unquenchable, and he will continue to roam the wide world as long as possible.', 'Agile, Lucky, Venturous', 'Chris Parson'),
('Alchemist Cookie', 'Bomber', 'Middle', 'Rare', 'alchemist-cookie.png', '2021-01-21', ARRAY['poison']::text[], ARRAY['chocolate']::text[], 'Unstable Formula|Cooldown=16', '16', 'Alchemist Cookie throws an explosive reagent, dealing DMG and applying Poison to targets. Alchemist Cookie will gain a random buff of either ATK increase, DEF increase, or CRIT% increase.', 'Just follow my instructions!', 'Made from the freshest of grapes, the fruit of the gods, this smart Cookie cares only about one thing: Research! She is always doing wild calculations, trying to figure out how to transform the elements. And she knows that being lazy or sitting idly by will achieve nothing. In order to acquire something of value, one must give something of value in return—that''s Alchemist Cookie''s theory, at least.', 'Analytical, Handy', 'Jeannie Tirado'),
('Cherry Cookie', 'Bomber', 'Rear', 'Rare', 'cherry-cookie.png', '2021-01-21', '{}'::text[], ARRAY['chocolate']::text[], 'Huge Cherry Bomb|Cooldown=16', '16', 'A giant cherry bomb causes area damage and stuns enemies.', '1=Here goes my Cherry Bomb! Boom! BOOM!', NULL, 'Tenacious, Independent', 'Kiera Brown (Credited as: Kiera Please)'),
('Knight Cookie', 'Defense', 'Front', 'Rare', 'knight-cookie.png', '2021-01-21', ARRAY['steel']::text[], ARRAY['almond']::text[], 'Cavalry Charge|Cooldown = 13', '13', 'Charges forward, applying an HP Shield, causing area damage, and forcing the enemies to attack himself.', 'I am here to protect {{Ch|princess|Her Highness', 'Knight Cookie, a noble warrior in shiny white chocolate armor decorated with milky foam. You can always count on this devoted Cookie, for he will never let you down. If only he could express his true feelings as freely as he wields his lance.', 'Agile, Tenacious', 'Daniel Amerman'),
('Princess Cookie', 'Charge', 'Front', 'Rare', 'princess-cookie.png', '2021-01-21', '{}'::text[], ARRAY['almond']::text[], 'Royal Swing|Cooldown=13|Description=The world is full of adventure! Princess Cookie swings her scepter with a noble smile, causing area damage and decreasing the enemies'' Defense.', '13|Description=The world is full of adventure! Princess Cookie swings her scepter with a noble smile, causing area damage and decreasing the enemies'' Defense.', 'The world is full of adventure! Princess Cookie swings her scepter with a noble smile, causing area damage and decreasing the enemies'' Defense.', 'And where shall I go today?', 'Don''t be fooled by her adorable smile and cute hairdo. She''s not the graceful and regal princess you''re looking for! Trouble follows the ever-curious Princess Cookie everywhere she goes, but somehow she manages to sort things out. After all, it''s hard not to fall for Her Majesty''s charm!', 'Brave, Lucky', 'Eden Riegel'),
('Zoey Cookie', 'Ranged', 'Rear', 'Special', 'zoey-cookie.png', '2026-04-08', '{}'::text[], ARRAY['raspberry', 'chocolate']::text[], 'Zoey Time!', '11', 'Grants Fans'' Cheers to HUNTR/X members before leaping into the air to throw the Shin-kal. Zoey Cookie then applies the CRIT% and ATK buffs to allies, with HUNTR/X members receiving additional bonuses based on Fans'' Cheers stacks. The Shin-kal deals damage to enemies and grants ATK buffs to HUNTR/X members for each target hit. Maximum stacks are applied when hitting demon targets. At the start of battle, if all HUNTR/X members are in the team, gains Fans'' Cheers and applies the CRIT% buff to her members. Additionally, Rumi Cookie and Mira Cookie''s remaining Cooldown decreases when Zoey Cookie uses her skill.', 'I was born for this!', 'Don''t look down on HUNTR/X''s maknae—it''s for your own good! When she raps, she goes HARD-taking no prisoners from haters. On stage, Zoey Cookie''s charisma never ceases to make fans happy or pierce demons like a sharp blade. In the past, she used to think the ideas in her head were useless and weird, but thanks to her friends, she found her meaning. Zoey Cookie never stops jotting down new song ideas—not when she''s singing with HUNTR/X, not when she''s slaying demons, because this is where she is meant to be!', NULL, 'Victoria Grace'),
('Mira Cookie', 'Charge', 'Front', 'Special', 'mira-cookie.png', '2026-04-08', '{}'::text[], ARRAY['raspberry', 'chocolate']::text[], 'Unchained Hunter', '16', 'Mira Cookie wields the Gok-do, dealing DMG to nearby enemies and releasing a powerful shockwave that leaves them Stunned. Her skill deals extra damage on critical hits. Additionally, Mira Cookie grants HUNTR/X members Fans'' Cheers, CRIT DMG, DMG Resist buffs, and HP Shield. As an expert wielder of the Gok-do, Mira Cookie deals additional damage to regular enemies with both regular and skill attacks. When attacking demons with regular attack, the remaining Cooldown decreases. If a demon is defeated by Mira Cookie''s skill, Cooldown decreases even more. At the start of battle, if all HUNTR/X members are in the team, she gains Fans'' Cheers, CRIT%, and Max HP buffs.', 'Me, a problem child? That’s how I’m gettin’ paid!', 'The fashion icon who sported a jet-black sleeping bag to the Cookie Gala, Mira Cookie! Once a black sheep of her family, now Mira Cookie is the lead dancer of HUNTR/X. She might call herself a difficult Cookie—overly-blunt and short-fused, but her friends know: her powerful dancing can tear down walls between Cookies and bring color back to life. A pop superstar by day, a demon hunter by night, she always looks after her fellow HUNTR/X members and her fans—with a mighty glaive in her hand. Make it hotter!', NULL, 'Josephine Chang'),
('Rumi Cookie', 'Ambush', 'Front', 'Special', 'rumi-cookie.png', '2026-04-08', '{}'::text[], ARRAY['raspberry', 'chocolate']::text[], 'Demon Slayage!', '16', 'Rumi Cookie grants Fans'' Cheers to HUNTR/X members, then charges towards the farthest enemy. Afterwards, she performs several slashes with her Sain-geom before slamming the ground hard to deal Downslash damage. If the target is single, Sain-geom Slash deals guaranteed critical hits. If all slashes land as critical hits, the target receives the Heavy Downslash damage. For demons, all attacks deal extra CRIT DMG. At the start of battle, if all HUNTR/X members are in the team, gains Fans'' Cheers and ATK buffs.', 'Slaying demons with our song!', 'Giant concert halls explode when HUNTR/X enter the stage, but when the spotlights go out, the pop superstars begin their hunt to protect their fans from demons. Such a double life is full of dangers, but thanks to Rumi Cookie''s leadership, HUNTR/X'' s voices are as strong as ever. Her divine singing can make anyone shed a tear or two, while a single swing of her blade can vanquish even the strongest of demons. Yet... not even the other members of HUNTR/X know about her well-guarded secret—why she sings with such passion and why she stepped on the path of a demon hunter. Today, Rumi Cookie''s song echoes to drive off demons, protect the Honmoon, and set her free from the mystery etched into her dough.', NULL, 'Greta Jung'),
('Marshmallow Bunny Cookie', 'Support', 'Rear', 'Special', 'marshmallow-bunny-cookie.png', '2025-07-02', '{}'::text[], ARRAY['candy', 'chocolate', 'applejelly']::text[], 'Let''s Go, Bunny Tunnel!', '17', 'Let''s go, Bunny Tunnel! Marshmallow Bunny Cookie, who teleports through tunnels, is Safeguarded and invulnerable to enemy attacks. Upon using her skill, Marshmallow Bunny Cookie opens a Bunny Tunnel and hands out Marshmallows and various Egg Bunnies to allies. The greater her Amplify Buff stat is, the more Egg Bunnies she will create. Marshmallow Bunny Cookie''s stats also increase depending on her Amplify Buff.', 'Take my hand and we''ll hop right in!', 'This rabbit is always full of bubbly curiosity! Hopping in and out of her Bunny Tunnel, Marshmallow Bunny Cookie always goes wherever the fun is. Nothing is more exciting than jumping into the great unknown: that''s how one learns new stories—the greatest treasure there is!', 'Intuitive, Venturous', 'Deneen Melody'),
('Cream Ferret Cookie', 'Support', 'Rear', 'Special', 'cream-ferret-cookie.png', '2024-07-17', '{}'::text[], ARRAY['chocolate', 'raspberry', 'applejelly']::text[], 'Snuggly Ferret|Cooldown = 18', '18', 'Transforms into their animal form, healing allies and granting DMG Resist, CRIT%, and CRIT DMG buffs. Cream Ferret Cookie hops on to the Cookie with the highest ATK (excluding Safeguarded Cookies), granting them the Fuzzy Scarf buff; then returns to their Cookie form and grants themselves a Debuff Resist buff. The friendly critter scurries to a Cookie whose HP is below a certain point and grants them the Precious Friend buff and Fuzzy Scarf buff. They cannot use their skill temporarily while scurrying to a Cookie. Cream Ferret Cookie is immune to damage while in their animal form.', 'My hugs are warm and fluffy!', '"Hush now, wipe those tears, ! I''ve got you!" At the very moment the fluffy, twinkle-eyed Cream Ferret met the baby dough, for the first time ever they were able to transform into a Cookie and give a big fuzzy-wuzzy hug! Cream Ferret Cookie was something of a late bloomer for a Cream Critter: finding a way to unlock their Creamcraft wasn''t easy at all... But no worries: now that they have finally met their very special friend, everything is a-okay. It may be Cream Ferret Cookie''s first time babysitting, but they know that no matter what happens, the magic of friendship can overcome everything and all!', 'Intuitive, Friendly', 'Kaitlyn Robrock'),
('Icicle Yeti Cookie', 'Healing', 'Front', 'Special', 'icicle-yeti-cookie.png', '2023-11-22', ARRAY['ice']::text[], ARRAY['chocolate', 'raspberry']::text[], 'Let''s Be Friends!|Cooldown=12', '12', 'Icicle Yeti Cookie buffs the allies and periodically restores their HP. They will assume the yeti form, jump towards the nearest enemy, and create a Shield of Ice to protect them. The Shield of Ice will absorb a portion of all incoming direct non-periodic damage and make the team resistant to Freezing. Then, Icicle Yeti Cookie will return to their position and deal a portion of the damage received in the yeti form with an icicle attack.', 'Will you be my friend?', 'Is there a friend this Yeti can share this perfect morning with? Icicle Yeti''s song echoes and breaks the chilly dawn, signaling the start of another day. This adorable Yeti used to be an icicle in a cave, but one day, was born... And along with them, this creature too was imbued with life! In legends, Yetis are depicted as ferocious and dangerous, but this particular one only wanted a friend to call their own. Melting and softening their spikes here and there turned them into an adorable Cookie! Small yet mighty—Icicle Yeti Cookie can pick up a Cookie like they weigh nothing, and fight off enemies with one hand! What excites this Cookie the most is making snowmen and having snowball fights with their new buddy! Cold to the touch, but warm at heart—this friendly Cookie is always ready to make new friends!', 'Cold-proof, Nature-loving', 'Greg Vinciguerra'),
('Snapdragon Cookie', 'Support', 'Rear', 'Special', 'snapdragon-cookie.png', '2023-06-08', '{}'::text[], ARRAY['chocolate', 'raspberry', 'applejelly']::text[], 'Arcane Blossom', '17', 'As an ancient entity, Snapdragon Cookie is safeguarded and invulnerable to enemy attacks. The elder magic of their skill will bloom snapdragons, periodically healing the team''s HP and granting a buff providing Stun resist, increased Debuff Resist, increased ATK, increased DMG Resist, and an HP Shield. Elder magic grants Dragon Cookies Draconic Lifeforce, increasing the Max HP of Dragon Cookies.', 'Buu ba ba!!!', 'Dragon City, once a dwelling place for ancient draconic power, has a particular legend passed down from generation to generation. "On the day the world is engulfed in a sea of fire, a dragon that will plunge the world into chaos shall awaken." After a horrendous night when the Red Dragon from the Dragon''s Valley burned the city to a crisp, a creature opened its eyes for the first time in the Dragon City Square... A baby with flowers for a tail, Snapdragon! Could this playful hatchling with eyes full of curiosity be the dragon from the legend? No one can be sure just yet, but the way the little creature imitates speaking Dragontongue or transforms into their Cookie form at will show that they''re no regular dragon. Abwubu! Abwaba! The small and cute baby dragon babbles on endlessly, excited to explore its new surroundings. But... who knows what kind of creature Snapdragon Cookie will grow to be?!', 'Brave, Nature-loving', 'Lana McKissack'),
('Jung Kook Cookie', 'BTS', 'Rear', 'Special', 'jung-kook-cookie.png', '2022-10-13', '{}'::text[], ARRAY['chocolate']::text[], 'ARMY''s Wishes', '19', 'Thanks to ARMY''s sincerest wishes, the BTS Cookies are Safeguarded and invulnerable to enemy attacks. Use the skill for periodic healing and a buff providing immunity to Stun and increased Debuff Resist for the entire team. If a member of the team is suffering from a certain number of debuffs, the entire team will additionally receive an HP Shield and a DMG Resist buff.', 'I''ll sing my heart out!', 'Meet BTS''s Golden Maknae, Jung Kook Cookie! True to this nickname, he excels at everything. The broad spectrum of his musical abilities spans genres and styles, and his voice—mesmerizing and sweet—serves as the song''s core! But music is not everything Jung Kook Cookie loves: an avid sports lover, he is very into boxing these days. You will be surprised to see what his muscles are capable of! Jung Kook Cookie''s greatest dream is to keep on singing until the end of time, and he is genuinely happy to sing in front of the Cookies this time.', NULL, NULL),
('V Cookie', 'BTS', 'Rear', 'Special', 'v-cookie.png', '2022-10-13', '{}'::text[], ARRAY['chocolate']::text[], 'ARMY''s Wishes', '19', 'Thanks to ARMY''s sincerest wishes, the BTS Cookies are Safeguarded and invulnerable to enemy attacks. Use the skill for periodic healing and a buff providing immunity to Stun and increased Debuff Resist for the entire team. If a member of the team is suffering from a certain number of debuffs, the entire team will additionally receive an HP Shield and a DMG Resist buff.', 'You can''t spell love without V!', 'Meet the romantic V Cookie, who loves feeding birds on the streets and looking at flowers. And if that is not enough to fall in love, his charming eyelashes will convince you. V Cookie''s melodic voice punctuates the performance, making every single one of them unique in its own way. This Cookie is never the same on stage, giving his fans a hard time deciding which animal he looks like more: a tiger or a teddy bear. V Cookie cannot wait to make friends with everyone in the Cookie Kingdom—let''s help him have a truly magical time!', NULL, NULL),
('Jimin Cookie', 'BTS', 'Rear', 'Special', 'jimin-cookie.png', '2022-10-13', '{}'::text[], ARRAY['chocolate']::text[], 'ARMY''s Wishes', '19', 'Thanks to ARMY''s sincerest wishes, the BTS Cookies are Safeguarded and invulnerable to enemy attacks. Use the skill for periodic healing and a buff providing immunity to Stun and increased Debuff Resist for the entire team. If a member of the team is suffering from a certain number of debuffs, the entire team will additionally receive an HP Shield and a DMG Resist buff.', 'I love you all and I always will!', 'Meet everyone''s darling, Jimin Cookie! As though sprinkled with shiny stardust, Jimin Cookie''s voice will mesmerize your ears, and his fluid, swift dancing moves will captivate your eyes! But natural talent can only take one so far: this Cookie is never tired of giving his all for an impeccable performance. Jimin Cookie is always happy to make you smile with his childish mannerisms and charming personality. He will always be there to comfort you when you feel down, too. Whether you feel cheerful or sad, Jimin Cookie will appear to make your day special!', NULL, NULL),
('J-hope Cookie', 'BTS', 'Rear', 'Special', 'j-hope-cookie.png', '2022-10-13', '{}'::text[], ARRAY['chocolate']::text[], 'ARMY''s Wishes', '19', 'Thanks to ARMY''s sincerest wishes, the BTS Cookies are Safeguarded and invulnerable to enemy attacks. Use the skill for periodic healing and a buff providing immunity to Stun and increased Debuff Resist for the entire team. If a member of the team is suffering from a certain number of debuffs, the entire team will additionally receive an HP Shield and a DMG Resist buff.', 'I''m your hope, you''re my hope! I''m j-hope!', 'Meet j-hope Cookie, who started as a street dancer and has been perfecting his skills ever since! Famous for his contagious laughter, this energetic Cookie is talented in many ways, providing a valuable opinion on each album''s concept, composition, and visuals. j-hope Cookie gladly acknowledges the talents of others and is always generous with praise and support. Although he always keeps it casual and fun during choreography practice, make no mistake: this Cookie is a true professional. It feels like every day is filled with laughter and joy with j-hope Cookie by your side!', NULL, NULL),
('SUGA Cookie', 'BTS', 'Rear', 'Special', 'suga-cookie.png', '2022-10-13', '{}'::text[], ARRAY['chocolate']::text[], 'ARMY''s Wishes', '19', 'Thanks to ARMY''s sincerest wishes, the BTS Cookies are Safeguarded and invulnerable to enemy attacks. Use the skill for periodic healing and a buff providing immunity to Stun and increased Debuff Resist for the entire team. If a member of the team is suffering from a certain number of debuffs, the entire team will additionally receive an HP Shield and a DMG Resist buff.', 'Aww, I''ve missed you!', 'Meet SUGA Cookie, the mastermind behind countless BTS tracks. This Cookie is in charge of expanding the group''s musical horizons. His potential seems limitless, be it composing, writing lyrics, producing, or collaborating with other artists. Songs by SUGA Cookie come out crisp yet sweet, realistic yet hopeful. Famous for being able to work anywhere and anytime, this prolific creator is looking to open a studio in the very Cookie Kingdom! Although the cat-like SUGA Cookie might not be exceedingly expressive on the outside, make no mistake: he cares deeply about his fellow group members, and even his most unexpected remarks are filled with genuine care.', NULL, NULL),
('Jin Cookie', 'BTS', 'Rear', 'Special', 'jin-cookie.png', '2022-10-13', '{}'::text[], ARRAY['chocolate']::text[], 'ARMY''s Wishes', '19', 'Thanks to ARMY''s sincerest wishes, the BTS Cookies are Safeguarded and invulnerable to enemy attacks. Use the skill for periodic healing and a buff providing immunity to Stun and increased Debuff Resist for the entire team. If a member of the team is suffering from a certain number of debuffs, the entire team will additionally receive an HP Shield and a DMG Resist buff.', 'Let''s put on a fantastic show!', 'Meet Jin Cookie, the Worldwide Handsome! His beautiful appearance is rivaled only by his crystal-clear voice and captivating artistry on stage. Although the oldest among the BTS members, Jin Cookie never plays the "hyung" card, treating everyone with equal kindness. This Cookie is known for his culinary skills—the BTS Cookies just cannot get enough of his tasty meals. Funny and charismatic, Jin always knows how to make everyone feel joyful and comfortable. Wherever he goes, fun and excitement follow—now it''s time to make new friends in the Cookie Kingdom.', NULL, NULL),
('RM Cookie', 'BTS', 'Rear', 'Special', 'rm-cookie.png', '2022-10-13', '{}'::text[], ARRAY['chocolate']::text[], 'ARMY''s Wishes', '19', 'Thanks to ARMY''s sincerest wishes, the BTS Cookies are Safeguarded and invulnerable to enemy attacks. Use the skill for periodic healing and a buff providing immunity to Stun and increased Debuff Resist for the entire team. If a member of the team is suffering from a certain number of debuffs, the entire team will additionally receive an HP Shield and a DMG Resist buff.', 'We are all connected!', 'Meet RM Cookie, the leader and the spirit of the BTS Cookies! Not only his fellow group members but also the ARMYs follow his leadership: after all, RM Cookie''s kind and comforting words can inspire and encourage anyone. This talented artist draws inspiration for his honest and resonant tracks from all genres and styles of music. However intelligent and charismatic, RM Cookie has a rather unexpected side: a talent to crush and destroy things. It is time to begin the fantastic show in the Cookie Kingdom. What will RM Cookie say to mesmerize his fans this time?', NULL, NULL),
('Tails Cookie', 'Ambush', 'Middle', 'Special', 'tails-cookie.png', '2021-09-17', '{}'::text[], ARRAY['chocolate']::text[], 'Tails'' Spin Dash|Cooldown = 17', '17', 'Curls up into a ball and dashes towards his enemies, dealing DMG to each enemy hit in succession. Upon landing, increases DEF of all allies.', 'I''ll take care of this one!', 'Tails is a very special fox. Why? Because he can fly thanks to his two tails! Tails wasn''t always happy about being different, but with Sonic''s help, he has gained the courage to accept himself. Of course, now the two are the best friends in the world! Tails knows his way around tools, mechanisms, and robots—that''s for sure. This little genius is always working hard, tinkering on new inventions to help save the world!', NULL, 'Colleen O''Shaughnessey and Kate Higgins'),
('Sonic Cookie', 'Ambush', 'Middle', 'Special', 'sonic-cookie.png', '2021-09-17', '{}'::text[], ARRAY['raspberry']::text[], 'Sonic''s Spin Dash|Cooldown = 16', '16', 'Curls up into a ball, spinning rapidly and bursting forward at super speed, dealing DMG to each enemy hit in succession. Increases ATK SPD of all allies.', 'Okay! Let''s race!', 'Green hills, labyrinths of mystic caves, or risky loop-de-loops-nothing can stop Sonic, for he is the fastest hedgehog EVER! Amazing, huh? While Sonic might not care much about rules and all, he will stop at nothing to help a friend in need. Time to meet Sonic the Hedgehog, a hero running at super speeds to save the world! In his own way.', NULL, 'Roger Craig Smith'),
('Litmus Cookie', 'Healing', 'Rear', 'Epic', 'litmus-cookie.png', '2026-06-18', '{}'::text[], '{}'::text[], 'Data Analysis', '14', 'Sends her Litmus Wings to deal damage and applies Weakness Analysis. Heals the team, applying ATK and CRIT DMG buffs. Several Litmus Wings will remain to keep analyzing the area. They will deal damage to enemies within this area and grant Data Samples to the team according to the number of enemy units that took damage. Allies with Data Samples will deal additional damage to enemies with the Weakness Analyzed status at the expense of one stack of Data Samples. When using her skill, Litmus Cookie can grant HP Shield (Red Result) or Healing (Blue Result) depending on the Data Analysis outcome.', 'Data, data, data . . . . . . Huh, you wanted something?', 'Litmus Cookie was scouted to SCOOP''s Senior Researcher position before her dough even set-a prodigy among prodigies. Recite any anomaly designation, and within a tenth of a second, she will rattle off containment protocols and compositional breakdowns without missing a beat: a living anomaly encyclopedia. Yet this same Cookie somehow fails to notice mismatched slippers. Fortunately, Litmungus, her anomaly-analyzing robot built as a pet project, is always here to manage this endearing contradiction. Years of hazardous fieldwork have left Litmus Cookie''s once-pristine white haircing stained and splotched beyond recognition. Today, like every day, Litmus Cookie hunkers down amid a mountain of reports, clutching a beaker of bitter black coffee, counting the hours until clock-out-though the memory of actually lying down at home has long since faded into myth...', 'Curious, Independent', 'Kendell Byrd'),
('Croissant Cookie', 'Support', 'Rear', 'Epic', 'croissant-cookie.png', '2026-05-21', ARRAY['light']::text[], '{}'::text[], 'Time Portal Removal', '15', 'A Time Portal appears, disrupting the Timeline! Time Portal deals DMG to enemies and applies Time Warp. Croissant Cookie appears aboard the Timecraft and fires an Energy Ball that absorbs the Time Portal: surrounding space-time contracts, pulling enemies in. After removing the Portal, grants Portal Removal Complete to all allies. When placed in Production buildings, production time is accelerated by 5%.', 'Hello there! Need a hand?', 'The Time Balance Department (TBD) constantly monitors the world with chronographs to check if the timelines are intact. This mysterious organization of elite agents has never outsourced tasks or scouted for new talent... until now. Hushed rumors of awe claim that Croissant Cookie restored a derelict rust bucket and tinkered around with it until it became a fully functioning, flying Timecraft! Croissant Cookie''s pastry dough was rolled and folded, rolled and folded many times over to create intricate layers. Perhaps this is why she understands complex mechanics and can fix them in a cinch. Her goggles, a self invention, display her destination''s exact coordinates and vector without fail. Pulling an all-nighter isn''t a problem for this Cookie, especially if it means her fellow agents can patrol the timelines without a hitch. With each new day, she raises her trusty spanner into the air and exclaims, "Time travel! WOOT!"', 'Tenacious, Handy', 'Suzie Yeung'),
('Ash Salt Cookie', 'Ambush', 'Front', 'Epic', 'ash-salt-cookie.png', '2026-05-07', ARRAY['darkness']::text[], '{}'::text[], 'Ashen Assasin', '14', 'Ash Salt Cookie assumes Shadow Form and infiltrates enemy lines, striking with her fork spear. In Shadow Form, Regular Attacks change and deliver a Final Hit when the effect ends. Skill and Regular Attacks in Shadow Form apply Ashen Salt on hit. Ashen Salt deals periodic damage, and when affected targets are defeated, Ash Salt Cookie gains Salt Crystals. Salt Crystals reduce remaining Cooldown at the end of Shadow Form.', 'I simply follow... commands.', 'On the fateful night, when the monstrous roar swallowed the world, heralding the awakening of the Beasts, Silent Salt Cookie''s faithful Knights of Kala Namak made their final stand. They gathered what remained of their Solidarity and kindled one last flame. From ash and salt was born a new being: Ash Salt Cookie. However, the knightly pride she was promised was supplanted by Shadow Milk Cookie''s deceiving whispers. Ash Salt Cookie now moves as a silent blade slipping through timelines, loyal only to the sinister will imprinted upon her dough.', 'Venturous, Independent', 'Katiana Sarkissian'),
('Pom-Pom Dough Cookie', 'Support', 'Middle', 'Epic', 'pom-pom-dough-cookie.png', '2026-02-11', '{}'::text[], '{}'::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('Mold Dough Cookie', 'Charge', 'Front', 'Epic', 'mold-dough-cookie.png', '2026-01-14', ARRAY['chaos']::text[], ARRAY['raspberry', 'almond', 'peanut']::text[], 'Order: Eliminate', '10', 'Mold Dough Cookie charges forward, dealing damage and pushing back his enemies. At the end of his charge attack, he deals area damage. Under certain conditions, Mold Dough Cookie enters Gem Frenzy, gaining injury. In this state, he cannot use his skill, but his regular attacks become enhanced at the expense of his HP being drained with each hit. If Mold Dough Cookie is defeated during his Gem Frenzy, he will become Invulnerable once per battle. When Gem Frenzy ends, Mold Dough Cookie becomes Exhausted, Stunned, and gains a MOV SPD debuff. During exhaustion, Mold Dough Cookie cannot enter Gem Frenzy, and will increase the team''s DMG Resist when the Gem Frenzy conditions are reached instead. At certain intervals, Mold Dough Cookie will gain Dragontongue Brand. If Mold Dough Cookie enters the battle together with Dark Enchantress Cookie, Dragontongue Brand will increase Chaos-type DMG for him and Dark Enchantress Cookie.', 'Command me.', 'Powerful Dough Cookies emerge from the depths of the Laboratorium! The roughest and toughest among them is Mold Dough Cookie, engineered with regenerative powers capable of mending even the most severe crumblage. This Cookie, whose chest is branded with mysterious symbols, offers faint smiles and scarce words only to Cookies sharing the same origin. Within the facility, researchers whisper that Mold Dough Cookie may harbor a dangerous, hidden power. Whatever the truth, he stands firm as the impenetrable shield to Dark Enchantress Cookie''s forces, carrying out her orders in sinister silence. Is his unwavering obedience born of loyalty... or something far more unsettling?', 'Brawny, Serene', 'George C. Owens'),
('Chess Choco Cookie', 'Bomber', 'Middle', 'Epic', 'chess-choco-cookie.png', '2025-11-19', ARRAY['chaos']::text[], ARRAY['chocolate']::text[], 'Chess Time!|Cooldown = 14', '14', 'The battlefield turns into a chessboard, and Pawn White Cookie and Pawn Black Cookie take turns to summon chess pieces. The twins open with dealing damage to all enemies, and Pawn White Cookie''s White Rook Pushes enemies back while Pawn Black Cookie''s Black Bishop sends them Flying. The White Rook buffs the team with Rook''s Blessing while the Black Bishop inflicts Bishop''s Judgment upon all enemies. After the game of chess is over, the chessboard shatters, dealing additional damage to all enemies, and Pawn White Cookie inflicts the White Rook debuff upon the enemy with the highest ATK while Pawn Black Cookie inflicts the Black Bishop debuff. If the two debuffs are applied simultaneously, they will trigger Checkmate. If you manage to protect the queen and reach the other end of the board... perhaps, the pawn may be promoted?', 'Want to play chess? Play chess with us.', '"Checkmate!" Two voices ring as one. Against them, no one stands a chance in a battle of wits upon the chessboard. Bars of dark and white chocolate were broken in half and whittled into the shape of Pawns. Once they were finished and set on the board, the twins began playing chess on their own! Come rain or shine, the two love to play on the chessboard. These siblings are inseparable, always hand in hand and walking together. When Pawn White Cookie opens the chess board, Pawn Black Cookie opens the chessboard, Pawn Black Cookie entices other Cookies to join a match. Playing a round each, the prodigies engage their opponents. Twins they may be, but their tactics and maneuvers are as distinct as day and night. Pawn Black Cookie favors a cautious strategy utilizing the King and Rook, Pawn White Cookie charges forward with an opening gambit to quickly promote Pawns into Queens. They have recently been singing about playing a new game, far more challenging and lucrative than chess. What exactly are they plotting other than chess openers?', 'Lucky, Mysterious', 'Brittany Cox'),
('Salt Cellar Cookie', 'Defense', 'Front', 'Epic', 'salt-cellar-cookie.png', '2025-10-22', ARRAY['steel']::text[], ARRAY['walnut', 'kiwi', 'chocolate']::text[], 'Knight of Solidarity|Cooldown = 14', '14', 'Salt Cellar Cookie''s indomitable will fills the space, dealing damage and summoning 4 Kala Namak Knights. She will grant HP Shields and the Proven Worth buff to the team. The latter will remove Mark of Kala Namak from the targets, make them immune to this effect, and increase their DMG Resist. The summoned knights cause shockwaves, dealing damage and pushing back the nearby targets. The knights'' ATK SPD can increase depending on Salt Cellar Cookie''s DEF and ATK SPD. They will also gain HP Shields. After receiving a certain number of hits, the knights will deal Strike of Solidarity, Stunning their targets and dealing extra damage. If Silent Salt Cookie is on the team, it will trigger Remembrance of Solidarity, which will enhance Salt Cellar Cookie''s skill and provide additional buffs for Salt Cellar Cookie and Silent Salt Cookie. Salt Cellar Cookie gains additional DMG Resist in proportion to her DEF stat, increased with the Beascuit.', 'Not another step.', 'The lone guardian of the Catacombs, silent even as she swings her weapon, clad head to toe in heavy armor. Ages ago, this Cookie belonged to the knightly order of Kala Namak, messengers of Solidarity. At the time, none of the knights possessed a keener understanding of this Virtue than Salt Cellar Cookie. recognition led to her appointment as Master of the Trials—for only those who could overcome her challenges might earn the title of true knight. Yet even Salt Cellar Cookie could not escape tragedy. Once hailed as "the Order''s Bastion," she remained in the depths of the Catacombs as her gleaming armor dulled with time. Though her spirit may have withered in the endless dark, her faith has never faltered. There, where even echoes fail to return, Salt Cellar Cookie whispers softly: "Embrace the downtrodden. Remember the tormented."', 'Analytical, Mysterious', 'Abby Trott'),
('Charcoal Cookie', 'Magic', 'Rear', 'Epic', 'charcoal-cookie.png', '2025-09-24', ARRAY['darkness']::text[], ARRAY['chocolate', 'raspberry', 'kiwi']::text[], 'Tombkeeper''s Rite', '12', 'Charcoal Cookie summons tombstones and unleashes vile spirits. The spirits cause a commotion in the enemy ranks and Shackles for some time. Whenever the spirits cause a commotion, Charcoal Cookie''s lantern consumes their power. If becomes defeated as a result, Charcoal Cookie''s lantern will consume even greater power. If the lantern is full at the end of the skill duration, it will release Cleansing Light. If Charcoal Cookie joins the battle together with Silent Salt Cookie, his vile spirits become stronger and cast a debuff, increasing damage taken by regular enemies. Charcoal Cookie''s Cleansing Light will grant Silent Salt Cookie buffs, increasing his Darkness-type and Steel-type CRIT DMG.', 'Ashes to ashes, crumbs to crumbs...', 'In the Land of Silence, where few Cookies dare set foot, where only the cries of vengeful spirits cut through the veil of lingering stillness, slumbers an ancient tomb. Charcoal Cookie, its solitary custodian, has taken care of this place for many years. But what made him carry on for so long? "I''m merely paying back me and me ancestors'' dues," he mutters back. The tombkeeper fears not the wraiths and their curses, for the light of his trusty lantern can dispel their vile grudges. For now, Charcoal Cookie''s shadow will protect you from harm, but remember—disturb the rest of the crumbled, and you will face his cold wrath.', 'Brawny, Venturous', 'Jon Bailey'),
('Menthol Cookie', 'Bomber', 'Rear', 'Epic', 'menthol-cookie.png', '2025-08-27', ARRAY['water']::text[], ARRAY['raspberry', 'chocolate']::text[], 'Menthol Censer|Cooldown = 15', '15', 'Menthol Gas leaks out from the censor and deals damage to enemies. If the target is inflicted with Endless Flow, it deals additional damage and for each target hit. Afterwards, Menthol Gas explodes and deals damage. The amount of DMG increases proportionally to the number of enemies affected by Menthol Gas. If a target has the Stinging Fizz debuff and takes damage from Menthol Gas Explosion, it causes Fizz Bubble Explosion, which deals Area damage. The number of targets affected by Stinging Fizz determines the number of Fizz Bubble Explosions.', 'Facts and evidence strengthen the faith.', 'Walking down the hallways of the St. Pastry Order''s cathedral, you might catch a waft of a refreshing scent, which means that Menthol Cookie is performing a ritual nearby. Armed with rationality and logic, Menthol Cookie challenges the notion of blind faith. Other Cookies of the cloth joke that his presence alone can lower the temperature in the room. In reality, the coldness of his rational mind hides the fiery yearning for divine truth... Such fervor has earned him deep admiration from , yet Menthol Cookie himself remains none the wiser—a more pressing question has been bothering the priest as of late. The word of the Godly Creators could not be more different from the truth unfolding right in front of his eyes. Is there truly salvation for Cookiekind? Armed with rationality and logic, Menthol Cookie is prepared to put his faith to the test!', 'Curious, Heat-proof', 'Mark Whitten'),
('Seltzer Cookie', 'Support', 'Rear', 'Epic', 'seltzer-cookie.png', '2025-08-27', ARRAY['water']::text[], ARRAY['chocolate', 'raspberry']::text[], 'Bubble Rain|Cooldown = 12', '12', 'Seltzer Cookie''s earnest prayers create a field of Carbonated Energy, which then disperses as Bubble Rain. Carbonated Energy draws enemies to its center and deals damage. Afterwards, Bubble Rain deals damage to enemies, Heals allies for a certain period of time, and grants them the Bubble Up buff. Additionally, Seltzer Cookie grants the CRIT DMG buff to Water-type Cookies for a certain period of time. If Menthol Cookie is on the team, she will inflict enemies and bosses with the Stinging Fizz debuff.', 'I thank the Godly Creators for the gift of life!', 'Seltzer Cookie, bright and bubbly like sparkling soda, is always cheerful and full of life! This Cookie''s smile always seems to shine and sparkle-perhaps because carbonated water was used instead of regular water in her dough. There was a time when Seltzer Cookie felt lost, thinking she had no special flavor or aroma of her own. But after encountering the teachings of the St. Pastry Order, she realized the purpose for which she was baked, and her heart swelled with joy like rising fizz! Seltzer Cookie guides believers along the path of faith and blesses those who answer the Call of Paradise, always striving to maintain a sense of composure. Yet, her heart bursts with excitement in front of a certain ! Will Seltzer Cookie''s pure, sparkling faith continue to shine brightly, even in the face of the destiny that lies ahead?', 'Attentive, Thorough', 'Brianna Knickerbocker'),
('Grapefruit Cookie', 'Charge', 'Front', 'Epic', 'grapefruit-cookie.png', '2025-08-13', ARRAY['electricity']::text[], ARRAY['chocolate', 'almond', 'caramel']::text[], 'Catch Me If You Can!|Cooldown = 13', '13', 'Dashes forward on her roller skates, sending the enemies into a daze and reducing ATK and DEF for the affected enemies. Grapefruit Cookie will grant an HP Shield to herself and Taunt enemies when her skill ends. Additionally, her DMG Resist will increase while her HP Shield is active. The Citrus Party effect is amplified with more Citrus Squad Cookies in the team. The Citrus Squad will make unforgettable summer memories when they''re all together! Grapefruit Cookie''s DMG Resist increases for each Citrus Squad Cookie on the team.', 'Guess I can hang out for a bit.', 'Always on her candy roller skates, Grapefruit Cookie seems to have an unlimited supply of energy! Shiny neon tights? Check! Quirky grapefruit helmet? Check! Is there anyone more stylish at the roller rink? No! 3, 2, 1, GO! Grapefruit Cookie skates with tremendous passion, and finds pleasure in greeting the others at the finish line with triumphant, "Haha! Too slow!" That might seem mean, but let''s admit it—she has some skill! Fun fact: Grapefruit Cookie hates ball games. After all, why should she like them?', 'Agile, Tenacious', 'Chelsea Krause'),
('Lime Cookie', 'Support', 'Rear', 'Epic', 'lime-cookie.png', '2025-07-30', '{}'::text[], ARRAY['chocolate', 'raspberry', 'almond']::text[], 'Beach Ball Surprise|Cooldown = 15', '15', 'Blows up a beach ball to grant HP Shields to ally Cookies and Heal them. When entering a battle with the Citrus Squad, Lime Cookie will prepare a surprise gift and add buffs depending on the Citrus Squad Cookies in battle. Additionally, entering a battle with all four of the Citrus Squad Cookies will apply extra buffs. The Citrus Party effect is amplified with more Citrus Squad Cookies in the team. The Citrus Squad will make unforgettable summer memories when they''re all together!', 'Vitamin... SPIKE!', 'When baking this Cookie, large amounts of bitter lime peel were used. Perhaps that''s why Lime Cookie is so feisty. Her trademark bangs were made with sweet, sweet jelly, and stay perfectly styled no matter how fast or wildly she runs. Don''t let her appearance fool you, she is known to be not the friendliest type! There is only that she has a weak spot for. She follows that Cookie around and looks up to them. Sometimes Lime Cookie can get pretty jealous and cause a rather uncomfortable situation. It is said that she learned her SMASH! skills from that Cookie...', 'Thorough, Sharp-eyed', 'Cat Protano'),
('Manju Cookie', 'Ambush', 'Rear', 'Epic', 'manju-cookie.png', '2025-07-30', ARRAY['water']::text[], ARRAY['raspberry', 'applejelly']::text[], 'Flash Strike', '17', 'When you notice Manju Cookie''s lightning-fast strikes, it''s already too late! Manju Cookie attacks enemies and delivers his final blow in a straight line. After that, he restores his own HP equal to a portion of the damage he dealt. If Manju Cookie and Jagae Cookie join the battle together, it will trigger the Temporary Alliance effect, making their skills more powerful. Whenever Jagae Cookie uses her skill, she will dispel any incapacitating effects on Manju Cookie and reset his Cooldown, allowing him to use his skill immediately.', 'Ahh, a discerning customer!', 'Guildmaster Manju Cookie welcomes every customer with a smile sweeter than red bean paste. His soft-spoken voice and eloquence only add to his charm. Perhaps that is why Cookies who visit his shop never leave empty-handed—as if they''ve been enchanted by a Buttershell Fox! But what truly sets the Manju Guild apart is his work philosophy. No matter how dangerous or obscure the request, the guildmaster always manages to deliver... Whispers of awe follow his name. And when someone starts questioning... the ethical side of Manju Cookie''s business, the courteous guildmaster merely offers a curious smile and replies, "How one uses the item in question is entirely up to the customer. I am but a humble merchant."', 'Venturous, Independent', 'Yung-i Chang'),
('Jagae Cookie', 'Support', 'Front', 'Epic', 'jagae-cookie.png', '2025-07-30', ARRAY['water']::text[], ARRAY['chocolate', 'almond', 'raspberry']::text[], 'Iridescent Storm', '13', 'Jagae Cookie waves her fan, causing an Iridescent Storm, dealing damage and dragging enemies into its center. The enemies who took damage gain the Pearl Shard debuff. Jagae Cookie grants her allies HP Shields and increases their . If Jagae Cookie and Manju Cookie join the battle together, it will trigger the Temporary Alliance effect, making their skills more powerful and reducing Jagae Cookie''s Cooldown. Whenever Jagae Cookie uses her skill, she will dispel incapacitating effects on Manju Cookie and reset his Cooldown, allowing him to use his skill immediately.', 'Looking to strike a deal? You came to the right Cookie!', '"Steady but surely!" Guildmaster Jagae Cookie bellows as she hoists the colors of her trade ship, shouting her guild''s motto. Rising to the rank of Guildmaster at a young age, she earned the trust and admiration of everyone in just three days—with grit, good taste, and an unwavering sense of responsibility. Goods that don''t meet her strict standards never find their way into her ship''s hold, and she honors every promise she makes, no matter the cost. Maybe it''s the harsh seas that toughened her up—or maybe she simply refuses to be seen as a soft bread. Her gruff sailor''s talk might intimidate some, but behind that hardened shell is a Cookie who always puts her customers first. Some merchants say she''s like a pearl hidden inside a tough shell... but best not tell her that!', 'Brave, Curious', 'Miya Kodama'),
('Orange Cookie', 'Magic', 'Rear', 'Epic', 'orange-cookie.png', '2025-07-16', ARRAY['electricity']::text[], ARRAY['applejelly', 'raspberry']::text[], 'Juicy Serve!', '12', 'Hits three tennis balls with a zesty smash! The balls explode and deal damage. The first explosion applies Zesty Juice, increases CRIT DMG taken, and inflicts Zap. The second and third explosions apply extra damage to targets with Zap. Zesty Juice stacks increase depending on the number of Citrus Squad Cookies. When an ally Cookie other than Orange Cookie deals CRIT DMG to an enemy inflicted with Zesty Juice, the effect will trigger, dealing extra Electricity-type DMG, then disappear, increasing Electricity-type DMG taken by the target. The Citrus Party effect is amplified with more Citrus Squad Cookies in the team. The Citrus Squad will make unforgettable summer memories when they''re all together!', 'Another vitamin-packed day ahead!', 'You can''t find another Cookie as zesty as Orange Cookie. She enjoys all outdoor activities, especially on a sunny day. The sun-cream mixed into her dough is the secret to her perfect tan. She is always full of positive energy and just being with her makes others happy. Her smashes are getting stronger every time... perhaps it is because of her ...?', 'Agile, Friendly', 'Madeleine Curry'),
('Lemon Cookie', 'Ambush', 'Middle', 'Epic', 'lemon-cookie.png', '2025-07-02', ARRAY['electricity']::text[], ARRAY['applejelly']::text[], 'Lightning Dash|Cooldown = 12', '12', 'Moves with lightning speed to deal damage to enemies. Lemon Cookie dashes forward and places an electric cube, which explodes once the Cookie returns to his original position, and deals extra damage to targets inflicted with Zap. Lemon Cookie deals additional damage if he delivers a CRIT with his skill. The Citrus Party effect amplifies with more Citrus Squad Cookies in the team. Additionally, Lemon Cookie''s CRIT% increases the more Citrus Squad Cookies are on the team. The Citrus Squad will make unforgettable summer memories when they''re all together!', 'Mess with me and get electrified.', 'Lemon Cookie was born not inside the hot Oven, but in a cold, neon-lit laboratory during an experiment with electricity. A giant, highly acidic lemon was used in the making of this Cookie, hence he courses with electricity. The cube that Lemon Cookie always carries with him controls the electric currents in his body. In his childhood, Lemon Cookie had only', 'Handy, Sharp-eyed', 'Brandon Jay'),
('Cream Soda Cookie', 'Charge', 'Front', 'Epic', 'cream-soda-cookie.png', '2025-06-25', ARRAY['water']::text[], ARRAY['raspberry', 'chocolate']::text[], 'Cream Soda Blade|Cooldown = 14', '14', 'Slashes enemies three times with the power of cream soda. The final strike increases the Water-type DMG received by enemies, , and deals additional DMG to enemies in PvE. Cream Soda Cookie gains the After School Training buff and increases own ATK SPD. She also increases the CRIT% and Water-type ATK DMG dealt by Water-type Cookies upon using her skill.', 'See something sparkling? That''s my blade!', 'The large gates open, and to the cheers of the onlooking students enters Cream Soda Cookie! In addition to a bubbly, honest personality and perfect grades, this Cookie prefers to lead by example as the president of the student council! Her soft yet sparkling demeanor has led to her becoming an idol in the eyes of the other students. But none of this would have been possible if it weren''t for Cream Soda Cookie''s endless efforts. When exams are coming up the Cookie either locks herself in her room and stays completely focused in her studies until the fizzy bubbles start to burst, or spends countless hours practicing swordsmanship in the empty training halls of the academy... But even though missing first place makes the tears well up, she just cries all her feelings out and keeps on working as hard as always!', 'Lucky, Curious', 'Sabrina Fest'),
('Sugarfly Cookie', 'Support', 'Rear', 'Epic', 'sugarfly-cookie.png', '2025-06-04', '{}'::text[], ARRAY['chocolate', 'raspberry', 'applejelly']::text[], 'Butterfly''s Whisper|Cooldown = 6', '6', 'Sugarfly Cookie flies up and Heals allies periodically. Afterwards, she will unfurl her wings and scatter Sugar Dust over the battlefield, increasing CRIT% and CRIT DMG for all allies and reducing the effect of Dream.', NULL, 'Everyone is welcome in the Garden of Delights. Among those who sought happiness in this paradise on Earthbread is a Cookie who smiles, looking at her wings that glisten brightly in the rays of the never-setting sun. Hailing from a land beyond the veil of fog, Sugarfly Cookie, too, found her Joy in this place. Since then, she has dedicated herself to delivering Happiness to all beings less fortunate, comforting the sorrowful and healing the pained with a word and a touch as delicate as her beauty. But why does she work so hard in a place without hardship? Sugarfly Cookie answers gently, "There is nothing I wouldn''t do to repay boundless kindness."', 'Flying, Nature-loving', 'Merit Leighton'),
('Pavlova Cookie', 'Ranged', 'Rear', 'Epic', 'pavlova-cookie.png', '2025-05-07', '{}'::text[], ARRAY['chocolate', 'raspberry', 'applejelly']::text[], 'Heart-Piercing Arrow|Cooldown = 6', '6', 'Shoots an arrow into the sky, summoning a rain of arrows falling onto the enemies, dealing damage and applying the Red Thread debuff. The more targets receive damage, the more stacks of Red Thread are applied (summoned creatures are excluded). Additionally, Pavlova Cookie will increase the teams''s CRIT% and CRIT DMG. Targets who reach the maximum stacks of Red Thread become Charmed when Pavlova Cookie uses his skill.', 'May your love stay true for all eternity!', 'Did someone say "LOVE"?! Pavlova Cookie, with his airy meringue wings and tart halo, will pop out of nowhere to give his absolutely uncalled-for love diagnosis. Nothing else in the world interests this Cookie more than love: unrequited, desperate, romantic—you name it! And no, you can''t hide from this herald of love''s sweet and sour arrow: he will look straight into your heart to dig up your most well-kept secrets and sing of Happiness eternal. But what''s this? Pavlova Cookie may seem insufferable at the first glance, but a careful look past his antics will reveal berries of desperation beneath the sugary crust...', 'Lucky, Friendly', 'Anna Brisbin'),
('Agar Agar Cookie', 'Ambush', 'Middle', 'Epic', 'agar-agar-cookie.png', '2025-04-09', ARRAY['fire', 'electricity', 'water', 'wind', 'ice']::text[], ARRAY['chocolate', 'raspberry']::text[], 'Ravenous Mirror', '15', 'Agar Agar Cookie mimics the skills of Legendary Guardians of Nature Cookies (Fire Spirit Cookie, Stormbringer Cookie, Sea Fairy Cookie, Wind Archer Cookie, Frost Queen Cookie). If she enters a battle with one of the Cookies on the team, she will mimic their skill. If there are none, she will use a skill randomly. Using a skill applies Immunity to Shackles on self, and a debuff that reduces ATK SPD and MOV SPD on enemies.', 'Sweet yummies... He he heh...', 'If you hear a faint, eerie laughter and experience an unusual lack of energy... It means that Agar Agar Cookie is lurking nearby! This Cookie, beset with an ever-present magical hunger, might appear sluggish, but make no mistake: slowly but inevitably, she will move towards a new source of Life Energy to sustain herself. Little is known about this mystical creature who spent a long time dwelling at the bottom of a forgotten well dripping with briny seawater—formless, shadow-like. Agar Agar Cookie''s fate took a new turn when the lid of her well was opened by a . Having gained a purpose from this unexpected visitor, Agar Agar Cookie took on an appearance reminiscent of her new ally. One thing is for certain: if you ever see a shadow, gazing at you with crimson eyes, start praying. For there is little you can do...', 'None', 'Erin Yvette'),
('Wedding Cake Cookie', 'Magic', 'Middle', 'Epic', 'wedding-cake-cookie.png', '2025-03-12', '{}'::text[], ARRAY['chocolate', 'applejelly']::text[], 'Anything for the Bride!|Cooldown = 15', '15', 'Turns the battlefield into a luxurious Wedding Aisle. The guests—your team—receive while the enemies sustain Periodic Damage. Summoned Creatures become Stunned. Additionally, Wedding Cake Cookie will increase the team''s ATK and CRIT DMG. Wedding Fireworks deal Additional DMG to enemies and Stun Summoned Creatures. If Black Forest Cookie is on the team, she will gain the Star of the Hour buff.', 'Nothing makes me happier than seeing brides smile!', 'Amidst sweet cream and elegant floral decorations, guests clap and cheer as a radiant smile shines on the bride''s face. And who made this dream wedding a reality? None other than Wedding Cake Cookie! Ever since witnessing a breathtaking ceremony as a child, she aspired to become the greatest wedding planner. Now, she works tirelessly, day and night, to ensure every bride''s big day is as magical as can be! From grand ballroom receptions under a chandelier of a thousand candles to enchanting ceremonies on open waters—even a fairytale wedding beneath a starlit sky—Wedding Cake Cookie can make any dream come true. Her clients'' wishes are her command, and her creativity knows no bounds! Want her to plan your perfect wedding? Visit her salon, Grand Mariage, and book an appointment today!', 'Handy, Friendly', 'Allegra Clark'),
('Black Forest Cookie', 'Charge', 'Front', 'Epic', 'black-forest-cookie.png', '2025-03-12', '{}'::text[], ARRAY['applejelly', 'raspberry', 'caramel']::text[], 'For the Creators!', '8', 'Black Forest Cookie uses the power granted by the Witches to Transform. In this form, Black Forest Cookie gains increased ATK SPD and DMG Resist, and . Also, she will deal Area Damage with her Regular Attacks. If the target is a Summoned Creature, Black Forest Cookie will deal Additional Damage and Stun them with a certain chance. At the end of her transformation, she will summon Thorns to deal wide-range Area Damage and Stun her enemies. If Wedding Cake Cookie is on the team, she will gain the Star of the Hour buff.', 'I... shall become Their bride!', 'With eyes as dark as bitter chocolate, Black Forest Cookie longs to be closer to the Godly Creators. As her faith deepened, so too did her thirst for Them,The pronoun used in all of Black Forest Cookie''s Korean dialogue when referring to her beloved is [https://korean.dict.naver.com/koendict/#/entry/koen/a6d89cb7ef534acd870c683903c33ad9 그분] (', 'Brave, Mysterious', 'Chelsea Rebecca'),
('Black Sapphire Cookie', 'Support', 'Middle', 'Epic', 'black-sapphire-cookie.png', '2025-02-12', ARRAY['poison']::text[], ARRAY['applejelly', 'raspberry', 'chocolate']::text[], 'It''s Showtime!|Cooldown = 15', '15', 'Black Sapphire Gems appear on the battlefield and explode after a certain period of time, inflicting Poison, amplifying debuffs and Poison-type damage. Additionally, the gems decrease enemies'' DEF depending on the number of Poison-type Cookies on the team, including Black Sapphire Cookie. The gems will also heal all Poison-type Cookies and increase their DMG Resist. Black Sapphire Cookie amplifies Poison-type DMG as long as he is present on the battlefield. The Deceitful Trio buff will activate partially when entering a battle with Candy Apple Cookie, and the buff will activate fully when entering with Shadow Milk Cookie.', 'It''s time to forget all your pains and worries!', 'What could be more delectable than fresh, juicy gossip?! Well, rumor has it there is a Cookie who has made the art of spreading rumors his profession! From harmless nonsense to large-scale propaganda—this charming fellow has mastered it all. Armed with his treasured eye-shaped microphone—a gift from the , no less—Black Sapphire Cookie works tirelessly to spread his master''s teachings around the world on the wings of rumor. Try not to fall for his artisanal falsehoods. Who knows: Black Sapphire Cookie might be on the other side of the screen right now!', 'Agile, Thorough', 'Barrett Leddy'),
('Candy Apple Cookie', 'Bomber', 'Middle', 'Epic', 'candy-apple-cookie.png', '2025-01-15', '{}'::text[], ARRAY['chocolate', 'almond', 'caramel']::text[], 'Apple of My Eye!|Cooldown = 12', '12', 'Candy Apple Cookie slams down a giant lollipop with a heave. Enemies hit will receive the ATK Reduction and DMG Amplification debuffs. The lollipop will shatter, granting HP Shields for all allies, and candy fragments will deal DMG to enemies and inflict the DMG Amplification debuff.', 'Kya ha ha! One bite will leave you wanting MORE!', 'What was the first lie ever told? No one knows for sure, but one Cookie claims to have been born from it—Candy Apple Cookie! Her syrup is so sticky it can seal lips shut and so glossy it leaves everyone staring in awe. Candy Apple Cookie believes she was crafted by the Master of Deceit himself, . From the moment she opened her eyes, her loyalty has been unwavering, dedicating herself to earning his love and trust. Though indifferent to most things, Candy Apple Cookie has a flair for mischief and a passion for dressing up. She delights in tricking other Cookies, giggling with sinister glee as they fall for her schemes, only to dash off in search of Shadow Milk Cookie''s approval. Beware—the first bite of the apple of lies is always the sweetest!', 'Serene, Curious', 'Kimoy Lee'),
('Okchun Cookie', 'Healing', 'Middle', 'Epic', 'okchun-cookie.png', '2024-12-31', '{}'::text[], ARRAY['chocolate']::text[], 'Okchun Pouch', '15', 'Okchun Cookie rides a giant okchun pouch and heals allies every time she jumps. Her third jump will heal allies more than the first and second jumps, and grants the CRIT% and CRIT DMG buffs to allies. She also applies the Okchun Candy buff, which disappears after healing targets with Max HP lower than 50%. Okchun Cookie applies the Okchun Gift buff to allies when entering battle. Okchun Cookie creates speech bubbles every three days in the kingdom, and rewards can be claimed by tapping on them. The higher the level, the better the rewards.', 'Pleased to meet you. I am Okchun Cookie.', 'Crafted from freshly harvested rice, infused with colorful syrups, and rolled into a delicately round shape, Okchun Cookie was adorned with a beautiful daenggi hairstyle. Among the esteemed Okchun family, known for being intelligent and wise, this Cookie is the brightest of them all. Perhaps it is due to the sturdy yeot filling in her dough! She stands up for what she believes in and is able to be vocal when she witnesses any acts of injustice. Okchun Cookie gladly takes on responsibilities both big and small within the office walls and handles them with elegance and ease. There are times when she ventures out to the market to explore the lives of the village Cookies and even resolves disputes between merchants. She also never forgets to share delicious candies with the less fortunate. There is not one Cookie in the village who does not appreciate her kindhearted nature!', 'Thorough, Friendly', 'Judy Alice Lee'),
('Green Tea Mousse Cookie', 'Defense', 'Front', 'Epic', 'green-tea-mousse-cookie.png', '2024-12-18', ARRAY['wind', 'grass']::text[], ARRAY['almond', 'chocolate', 'peanut']::text[], 'Mousse Shield|Cooldown = 11', '11', 'Green Tea Mousse Cookie Taunts enemies and combines her shields into one. Her regular ATK SPD decreases, but she becomes able to attack all nearby enemies, Push them back, and then Stun with a certain probability. After that, Green Tea Mousse Cookie will apply a DMG Resist buff to her allies and gain the Mousse Shield buff and an HP Shield. If she receives a certain number of hits while her Mousse Shield is active, Green Tea Mousse Cookie will heal the team in proportion to DEF. This effect will activate once over a certain period of time. The Team Drizzle effect will activate when entering battle with Choco Drizzle Cookie and Pudding à la Mode Cookie.', 'Job didn''t work out? Stuff happens.', '"What is soft, is strong." This phrase seems to have been coined for Green Tea Mousse Cookie, who stands tall and confident wielding her Green Tea Mousse shields—soft yet unyielding. This Cookie is known as the strongest of her sisters, and yet, many will fall for her unexpectedly gentle demeanor. Beneath her exterior, however, lies an insatiable greed for riches. Even when on a mission from the Master, she won''t hesitate to snatch up trinkets—often earning a disapproving glare from her . She will go as far as asking skilled Cookies who could prove useful to the Master, "You wanna be mine?"—of course, as a joke... or maybe not!', 'Attentive, Venturous', 'Debi Derryberry'),
('Pudding à la Mode Cookie', 'Bomber', 'Rear', 'Epic', 'pudding-a-la-mode-cookie.png', '2024-12-04', ARRAY['electricity']::text[], ARRAY['caramel', 'applejelly']::text[], 'Plasma Cannon|Cooldown = 11', '11', 'Pudding à la Mode Cookie’s arms transform into plasma cannons and emit powerful plasma beams towards enemies. Next, the Cookie will call upon her drones, which attack the same targets during her regular attacks. Drone attacks are regarded as Pudding à la Mode Cookie’s regular attacks. Drones will prioritize targets with a Penumbral Mark.', 'Ha ha! Being sweet is the BEST!', 'Pudding à la Mode Cookie makes her opinion clear: being sweet is the BEST! Winning is the BEST! And that means, SWEETNESS WINS! She was sent to Crispia with her sisters on the Master''s orders, but her mind blanks out in front of sweet treats. As the youngest of the three, Pudding à la Mode Cookie has always been the center of attention, growing up a little spoiled. But don''t be fooled by her cute, innocent smile—she''s ready to blast anyone who crosses her or snatch whatever she wants with a giggle. Many have learned the hard way that her weaponry is anything but sweet...', 'Independent, Friendly', 'Kitana Turnbull'),
('Choco Drizzle Cookie', 'Ambush', 'Middle', 'Epic', 'choco-drizzle-cookie.png', '2024-12-04', ARRAY['darkness']::text[], ARRAY['raspberry', 'chocolate']::text[], 'Choco Penumbra|Cooldown = 12', '12', 'Choco Drizzle Cookie hides amidst the shadows and applies a Penumbral Mark and Consuming Darkness upon the farthest enemy (targets Cookies first), then deals a series of 8 hits to the target and nearby enemies. If the target has a Penumbral Mark, it will trigger Drizzle Strike, dealing additional damage. If the Penumbral Mark is on a Cookie, it will carry over to the nearest Cookie after the original target is eliminated, decreasing Choco Drizzle Cookie''s remaining Cooldown. The Cooldown decrease can trigger up to 3 times per battle. If the Penumbral Mark is on a non-Cookie target, the carry-over effect and a decrease in Cooldown will not be triggered. If an enemy''s HP falls below a certain level, Choco Drizzle Cookie will identify their weakness and perform Drizzle Strike immediately, dealing greater damage. This effect can trigger only once for each enemy. Upon using her skill, Choco Drizzle Cookie will prioritize targets with a Penumbral Mark, ignoring any taunt effects. The Team Drizzle effect will activate when entering battle with Green Tea Mousse Cookie and Pudding à la Mode Cookie.', 'Don''t dare look into the darkness.', 'In the dead of night, when the entire world is asleep, a shadow glides through the darkness... Choco Drizzle Cookie. Once her eyes lock onto a target, she becomes relentless—almost viscous, like sticky chocolate syrup. Perhaps it''s because her dough is infused with the most bitter cocoa powder, but Choco Drizzle Cookie carries out her missions with extreme precision and ruthless efficiency. This is why she is the Master''s most trusted, leaving even her other sisters behind. No one knows the true reason behind their rigorous upbringing, or why they were sent to Crispia... but one thing is certain: no Cookie can escape her blade in the dark.', 'Handy, Sharp-eyed', 'Laci Morgan'),
('Red Osmanthus Cookie', 'Ranged', 'Middle', 'Epic', 'red-osmanthus-cookie.png', '2024-11-20', ARRAY['grass']::text[], ARRAY['raspberry', 'applejelly', 'caramel']::text[], 'The Pipa''s Song|Cooldown = 10', '10', 'Red Osmanthus Cookie plays the pipa and sends a gust of petals, dealing damage and decreasing enemies'' ATK. While using her skill, Red Osmanthus Cookie will increase CRIT DMG and deal additional damage with each CRIT hit. DMG proportional to Max HP is capped at 300,000.', 'Ooh, what a lovely melody!', 'At the highest point of Osmanthus Academy, a lone Cookie strums the delicate strings of her pipa—the enchanting Red Osmanthus Cookie. With each breath of the wind, the melody drifts through the air, captivating passing Cookies with her elegance and grace. This Cookie was trained from a young age in poise and high-class etiquette, though many remember her only for her breathtaking beauty. No matter how many Cookies try to befriend her, she turns away, her gaze distant, her heart longing for the attention of Until that day comes, Red Osmanthus Cookie will continue to play this melancholy melody.', 'Musical, Handy', 'Rebecca Wang'),
('Golden Osmanthus Cookie', 'Bomber', 'Middle', 'Epic', 'golden-osmanthus-cookie.png', '2024-11-20', ARRAY['grass']::text[], ARRAY['chocolate', 'raspberry']::text[], 'Incense of Love|Cooldown = 13', '13', 'Golden Osmanthus Cookie creates an incense sachet, healing allies and covering them with an HP Shield. The incense burner floats towards enemies and then bursts with flower petals, dealing damage. Additionally, enemies become Charmed by the mesmerizing scent.', 'Such a delightful scent!', 'At last, the wind blows away the heat, filling the air with the scent of osmanthus. This scent is sought after by many Cookies these days, for it is the latest fragrance crafted by the perfume master herself, Golden Osmanthus Cookie. A daughter of an illustrious family, she earned renown for her unique ability to concoct aromas that can make your dreams come alive, if only for a fleeting moment. Behind Golden Osmanthus Cookie''s serene eyes hides a great passion for her craft. This is why her lights remain aglow even when the entire Flower City falls asleep. On a moonlit night, any guest to her perfumery will sense more than her perfumes—they will sense the fragrance of her heart.', 'Attentive, Nature-loving', 'Courtney Chu'),
('Smoked Cheese Cookie', 'Magic', 'Rear', 'Epic', 'smoked-cheese-cookie.png', '2024-10-30', ARRAY['earth']::text[], ARRAY['raspberry', 'chocolate']::text[], 'Get Smoked!|Cooldown = 15', '15', 'Smoked Cheese Cookie uses his smoke to Charm enemies, amplifying the damage received and dealing multiple damage to enemies within the smoke. Then, with an explosion, he deals more damage and extra damage to enemies in PvE. Upon using his skill, he applies the Guardian''s Return buff to an ally with the highest ATK. If Golden Cheese Cookie is in the team, he will prioritize her instead. The Protector of the Golden City buff will activate when entering a battle together with Golden Cheese Cookie. This effect is applied to Golden Cheese Cookie, Burnt Cheese Cookie, and Smoked Cheese Cookie.', 'Never let your guard down.', 'Oh cheeses! A monster has infiltrated the Golden City?! Don''t worry, it''s under Smoked Cheese Cookie''s control! As the General of the Golden Cheese Kingdom, he has kept the kingdom safe for years, taming monsters with his smoky powers to protect the city walls. But after the Dark Flour War, something changed within him. He began planning something that, if revealed, would surely get him to the Colosseum until one day... he finally crossed the line. Now, the Golden Cheese Kingdom is in peril once again, and Smoked Cheese Cookie has got a chance to redeem himself. He stands, facing his past mistakes, his queen, and his former allies. The question is: which way will he point his staff this time?', 'Tenacious, Sharp-eyed', 'Alejandro Saab'),
('Nutmeg Tiger Cookie', 'Support', 'Rear', 'Epic', 'nutmeg-tiger-cookie.png', '2024-10-02', ARRAY['fire']::text[], ARRAY['chocolate', 'raspberry', 'almond']::text[], 'The Great General|Cooldown = 12', '12', 'Nutmeg Tiger Cookie orders her Elite Guard to charge forward. The Elite Guard deals Fire damage, causing Burn, heals the allies for a portion of the damage dealt, increasing their , and applying the Great General buff to all Fire-type Cookies and summoned creatures. The Elite Guard consists of a Rider and Fighters. The Rider will cause area damage with their regular attacks and heal your team for a portion of the damage dealt. The Fighters will taunt enemies upon summoning, protect themselves with an HP Shield, and gain a DMG Resist buff. After summoning the Elite Guard, Nutmeg Tiger Cookie will attack up to 5 enemies with each regular attack and gain an ATK SPD buff. If Burning Spice Cookie is in the team, he will absorb the dust of the fallen Elite Guards and gain the Burning Nutmeg buff.', 'Swarm! Prepare to attack!', 'In the Spice Storm-ridden wastelands, a fierce Cookie commands her troops with an iron fist. She is none other than the legendary general of the Spice Swarm, Nutmeg Tiger Cookie! Half Wild Spice, half Cookie—if the rumors are to be believed—her superior strength has been proven in countless battles. In the past, she rose to power as a great warrior who claimed victory over all the Spice Tribes. Never known weakness, she does not understand the weak. Defeat is an unfamiliar concept to her, for in her world, strength is the only way. It''s no wonder she swore allegiance to the mighty upon his return. But will her loyalty be acknowledged in time? Only fate can tell.', 'Intuitive, Heat-proof', 'Shara Kirby'),
('Star Coral Cookie', 'Support', 'Rear', 'Epic', 'star-coral-cookie.png', '2024-08-14', '{}'::text[], ARRAY['chocolate', 'applejelly', 'raspberry']::text[], 'Twinkling Coral|Cooldown = 14', '14', 'Summons a twinkling coral to heal her allies, provide an HP Shield, and increase their CRIT%, ATK SPD, and Amplify Buff. The Cookie''s lantern will shine towards the enemies, dealing periodic damage. Star Coral Cookie''s Lunar Lantern makes her immune to Sleep and Drowsy, and will periodically restore the allies'' HP instead.', '... The song of the stars! I can hear it!', 'A lone lighthouse on a secluded island shines its guiding light across the Silent Ocean. Star Coral Cookie, the dedicated lighthouse keeper, warmly greets sailors from far and wide. Her shadow, cast upon the lighthouse stairs, resembles a coral emerging from the waves. It is said that the light in the lighthouse is special, taken from the legendary Giant’s Great Ocean, as told in the stories of the stars. But could that be true? Star Coral Cookie sings the star''s story with conviction in her eyes, claiming she sailed across the Garden of the Queen, navigated through the Swirl guarded by the Four-legged Beast, and finally reached a library containing all knowledge. Although no Cookie believes her fantastical tale, it’s enough for her that the stars above know the truth.', 'Attentive, Underwater', 'Miranda Parkin'),
('Peach Blossom Cookie', 'Support', 'Middle', 'Epic', 'peach-blossom-cookie.png', '2024-06-28', '{}'::text[], ARRAY['chocolate', 'raspberry', 'almond']::text[], 'Heavenly Fruit|Cooldown = 12', '12', 'With a gentle flick of a peach tree branch, Peach Blossom Cookie summons a Peach Tree that will periodically heal the team and bear Peach Bao fruits. The ally with the lowest Current HP will receive additional Healing. Peach Blossom Cookie will give Heavenly Fruits to the allies to increase their DMG Resist and Debuff Resist. The fruit will also grant resistance to Apathy, and ATK and DMG Resist buffs when affected by Apathy. Enemies will receive Unripe Peach Baos, inflicting DMG, reducing their ATK SPD and MOV SPD. Peach Fragrance will protect Peach Blossom Cookie, making him immune to Apathy.', 'Sate your hunger in my garden.', 'Cotton candy clouds gently caress the soft ridges of the mountains. A delicate breeze carries the saccharine scent of peaches, while heavenly flower petals float down three times a day. In this Realm of the Immortals, Peach Blossom Cookie tends to a small yet lush peach garden. Here, Peach Baos blossom—juicy and succulent, nurtured by the warm sunlight, pristine air, and pure water. If a stray traveler stumbles upon this garden, Peach Blossom Cookie will greet them with a soft smile and a Peach Bao in hand. They say Peach Baos blossom once every three thousand years. Then how old does that make this Cookie...? He gazes down beneath the clouds with a gentle look, eyes wise beyond their years.', 'Attentive, Mysterious', 'Charlie Thurston'),
('Cloud Haetae Cookie', 'Defense', 'Front', 'Epic', 'cloud-haetae-cookie.png', '2024-05-22', '{}'::text[], ARRAY['almond', 'chocolate']::text[], 'Haetae Charge|Cooldown = 11', '11', 'Takes the form of a Cloud Haetae. After transforming, gains an increased DEF and DMG Resist and grants HP Shields for the entire team. With their regular attacks, Cloud Haetae Cookie charges at the enemies, dealing area damage. Cloud Haetae Cookie will also heal the ally with the lowest HP with Cloud Rolls (except Cloud Haetae Cookie themselves). When the transformation is over, Cloud Haetae Cookie will perform a last forceful charge to deal greater damage and Stun the enemies. While in the Cloud Haetae form, the Cookie will disable Debuff Immunity applied on enemy Cookies. Belonging to the Realm of Apathy, Cloud Haetae Cookie can briefly disrupt the Power of Apathy effect when using their skill and grant the Visions of Apathy buff to the team. When in the same team with Mystic Flour Cookie, Cloud Haetae Cookie will gain the Haetae''s Loyalty buff. Cloud Haetae Cookie will regain HP with each 3 regular attacks in the Cookie form.', 'It is I, Cloud Haetae Cookie, guardian of the Ivory Pagoda!', 'Let''s see... This creature looks like a puppy and barks like a puppy, AND is known to ward off bad luck and fires! Must be none other than Cloud Haetae Cookie from legends! The stalwart guardian of', 'Intuitive, Curious', 'Rachelle Heger'),
('Street Urchin Cookie', 'Bomber', 'Middle', 'Epic', 'street-urchin-cookie.png', '2024-04-09', ARRAY['fire']::text[], ARRAY['chocolate', 'raspberry']::text[], 'Ride or Crumble|Cooldown = 12', '12', 'Street Urchin Cookie rides her motorbike into her enemies, dealing DMG, inflicting Stun, and causing additional explosion DMG if the target is affected by Burn. Her CRIT% increases and inflicts Burn and Fire-type DMG amplification debuff to enemies. If Street Urchin Cookie or her allies , her Fire-type ATK DMG increases. While Street Urchin Cookie is using her skill, she will briefly become resistant to interrupting effects.', 'I don''t ride the wind, I cut right through it!', 'VROOOOOM! The powerful purr of a motor announces the arrival of the Spiky Tornado of the Town Square, Street Urchin Cookie! When this biker Cookie hops on her Black Tiger Bike and yells, "Get out of the way!" visitors quickly scramble to clear the path. When she''s not riding her bike, she''ll lean against the alley wall, radiating an unapproachable aura. Yet, perhaps it''s not just her spiky nature that keeps Cookies away... Among the Town Square Cookies, Street Urchin Cookie remains a mystery, emerging one moonlit night, lonely and injured. Her background story and what led her here remain shrouded in rumors. Regardless of what others say, Street Urchin Cookies rides the streets of the Town Square, popping her bubblegum. But what keeps her anchored here in this place?', 'Agile, Independent', 'Heather Gonzalez'),
('Caramel Choux Cookie', 'Support', 'Rear', 'Epic', 'caramel-choux-cookie.png', '2024-03-27', '{}'::text[], ARRAY['chocolate', 'almond', 'raspberry']::text[], 'I''ve Got Choux|Cooldown=15', '15', 'Caramel Choux Cookie uses I''ve Got Choux to heal allies. She applies DMG Resist, Amplify Buff to targets receiving healing, and applies an HP Shield to an ally Cookie with the lowest Max HP. As the Town Square supervisor, Caramel Choux Cookie applies the Friendly Helper buff to all ally Cookies when entering battle. While Caramel Choux Cookie is using her skill, she will briefly become resistant to interrupting effects.', 'I just LOVE the Town Square!', 'The Cuckoo Town Square is always bustling with visitors from far and wide. Cookies love to stroll and shop along the high streets, particularly enchanted by Weaving Magic. But the true gem of the Town Square is none other than Caramel Choux Cookie! Whenever there''s an issue or complaint to be solved, this adorable little Cookie springs into action! Donning her hat and grabbing her briefcase, she scurries to assist whoever needs help. She''s known for her grit and hardworking nature, but what truly sets her apart is her kindheartedness. She greets everyone in the Square with a cheerful "Good Morning!" and radiates positive energy. Surprisingly, she finds even the most daunting complaints exciting! When asked how she does it all, she simply replies, "I just LOVE the Town Square!"', 'Thorough, Friendly', 'Madeline Dorroh'),
('Butter Roll Cookie', 'Charge', 'Front', 'Epic', 'butter-roll-cookie.png', '2024-03-13', ARRAY['steel', 'chaos']::text[], ARRAY['almond']::text[], 'Dough Experiment', '12', 'Butter Roll Cookie spins his whisk, dealing damage and sucking in enemies at the center of the whisk vortex, reducing their ATK and ATK SPD, and increasing Butter Roll Cookie’s DMG Resist. He then deals more damage with his whisk and Stuns his enemies, dealing extra damage to enemies resistant to Stuns. While Butter Roll Cookie is using his skill, he will briefly become resistant to interrupting effects.', 'This will be the greatest experiment of my career!', 'One of Beast-Yeast''s best-kept secrets is the mysterious Laboratorium. There, a team of passionate scientists conducts all sorts of peculiar experiments on the Cookie dough under the leadership of Director Butter Roll Cookie, a baker extraordinaire wielding an enormous whisk. Butter Roll Cookie regards his subordinates'' mistakes as happy little accidents paving the way to future breakthroughs. There is no baking conundrum Butter Roll Cookie''s expert hands cannot whip up a solution for! Under his rolling pin, meringues come out light as air and dough, smooth as silk, earning him an unquestionable authority. And yet, there is something bone-chilling about the way Butter Roll Cookie''s smile vanishes from his face when he works his dough.', 'Brawny, Venturous', 'Kieran Regan'),
('Matcha Cookie', 'Magic', 'Middle', 'Epic', 'matcha-cookie.png', '2024-02-28', ARRAY['poison', 'grass']::text[], ARRAY['chocolate', 'raspberry']::text[], 'Sinister Scheme|Cooldown = 12', '12', 'Matcha Cookie summons Tea Seeds at the enemies'' location and causes an explosion. The Tea Seeds poison enemies, amplify debuff effects, and increase the duration of Poison-type Periodic DMG inflicted by the team. At times, Matcha Malice may manifest from a Tea Seed, shackling a random enemy, dealing damage, Cursing them and applying Healing, , and Amplify DMG debuffs. Matcha Malice is even applied to Cookies who are resistant to interrupting effects. At the end of the skill''s duration, Matcha Malice will deal explosion DMG and apply Silence. The chance of Matcha Malice''s appearance will increase with more debuffs applied to Matcha Cookie. While Matcha Cookie is using her skill, she will briefly become resistant to interrupting effects.', 'Heh? Go away...! Mheh...', 'Tea plants that grow in the dark have no other option but to feed on the energy of darkness. Leaves from such a plant were supposed to grant incredible dark powers to Matcha Cookie, but whoever made her seems to have forgotten an essential ingredient, and it greatly affected her personality. Now she spends most of her time in darkness, thinking of sinister plans and giggling. Little is known about Matcha Cookie, but the greatest mystery is what exactly the missing ingredient was...', 'Analytical, Serene', 'Triya Leong'),
('Mercurial Knight Cookie', 'Charge', 'Front', 'Epic', 'mercurial-knight-cookie.png', '2024-02-07', ARRAY['steel']::text[], ARRAY['almond', 'raspberry']::text[], 'Mercurial Knight''s Oath|Cooldown = 11', '11', 'With the power of mercury, Mercurial Knight Cookie''s regular attacks are strengthened, dealing area damage to enemies and casting Mercury Poisoning. Mercurial Knight Cookie will then land his final strike, dealing damage and additional damage based on the number of Mercury Poisoning stacks. When Mercurial Knight Cookie is inflicted with a debuff, he will gain an Amalgamation buff, and when he gains enough stacks, he''ll dispel all debuffs and enter Mercury Storm mode. In Mercury Storm mode, Mercurial Knight Cookie will not receive an Amalgamation buff. Due to his mercurial armor, Mercurial Knight Cookie is immune to the Spore Dispersal and Mushroom Mutation effects. While Mercurial Knight Cookie is using his skill, he will briefly become resistant to interrupting effects. When Mercurial Knight Cookie enters the battlefield with Silverbell Cookie, the Silver Knighthood buff will activate.', 'I made an oath to protect the Guardian of the Silver Tree.', 'Mercurial Knight Cookie is the commander of the Silver Tree Knights who has sworn to protect the Silver Tree and its Guardian. Blessed by Silver, he cast aside his former flavor, scent, and memories (and mastered the sacred art of Amalgamation). When in battle, enemies see nothing but a blur of silver, swift and fluid like mercury. Perhaps the gravity of his mission has changed the very nature of his crispy Cookie dough.', NULL, 'Chester Rushing'),
('Silverbell Cookie', 'Support', 'Rear', 'Epic', 'silverbell-cookie.png', '2024-01-19', ARRAY['grass']::text[], ARRAY['chocolate', 'almond', 'raspberry']::text[], 'Gleeful Chime|Cooldown=15', '15', 'Silverbell flowers bloom, periodically healing the allies and granting a DMG Resist buff. Healing targets will also receive bonus healing depending on the number of buffs they currently have. Enemies will receive damage and gain the Silverbell Pollen debuff dealing periodic damage. When Silverbell Pollen''s duration is over, it will cause area damage and Stun the targets in range. Silverbell Cookie is immune to the Spore Dispersal and Mushroom Mutation effects. Entering the battle with Mercurial Knight Cookie will activate the Silver Knighthood effect.', 'One day, we all will become happy...!', 'If you ever encounter a wisp of white light, wandering across the misty trees with a cheerful chiming, do not let your guard down. For Silverbell Cookie will never miss a shot. Resembling a soft flower petal adorned with beads of morning dew, Silverbell Cookie is not as delicate as he might seem. As a loyal Knight of the Faerie Kingdom, he has sworn to protect its secrets with his life. And yet, despite the heavy burden of his duty, this Cookie always keeps a pure, bright smile—after all, there is all, there is no stronger shield than a loving heart.', NULL, 'McKenzie Atwood'),
('Rebel Cookie', 'Ambush', 'Front', 'Epic', 'rebel-cookie.png', '2024-01-04', ARRAY['wind']::text[], ARRAY['chocolate', 'applejelly', 'almond', 'raspberry']::text[], 'Here, There, Everywhere!|Cooldown=13', '13', 'Rebel Cookie uses his magic, decreasing the enemies’ DEF, making them more vulnerable to all types of damage, and dealing damage. Enemies with decreased DEF will receive additional damage. Rebel Cookie will increase the allies’ CRIT% and provide an HP Shield for them, blocking damage equal to a portion of the damage he has dealt. After finishing using his skill, he will create 2 decoys that will Push enemies back with each Regular Attack. The decoys have a number of Hits instead of HP. While Rebel Cookie is using his skill, he will briefly become resistant to interrupting effects.', 'I will never forgive injustice!', 'Be aware, greedy Cookies! One swift Cookie might already be going over your fence to fix injustice as we speak! Rebel Cookie, made with newly harvested rice that was organically farmed with just the right method, is bound to make you feel healthier just by looking at him! With self-taught excellency in magic, he is someplace one second and somewhere else in another, traveling on his cloud to rob the storages of wealthy and corrupt Cookies! Even when he gets locked up by the guards... POOF! He''s gone, leaving a straw doll in his stead. Rebel Cookie equally and fairly distributes the stolen Jellies among villagers, which is why every village loves him! He will never stop fighting for justice! Rebel Cookie will undoubtedly go down in history!', 'Brave, Agile', 'Edward Hong'),
('Crème Brûlée Cookie', 'Ranged', 'Rear', 'Epic', 'creme-brulee-cookie.png', '2023-12-13', ARRAY['light']::text[], ARRAY['raspberry', 'caramel']::text[], 'Accelerando|Cooldown=9', '9', 'Crème Brûlée Cookie''s passionate, captivating performance deals Light-type damage to enemies and enhances his regular attacks with the Accelerando buff. Crème Brûlée Cookie''s regular attacks target the enemy with the highest ATK and, when enhanced, apply the Mysterious Melody buff to nearby Cookies. The pianist will also create Crème Brûlée Pieces depending on the number of Accelerando stacks. Crème Brûlée Pieces will deal damage to enemies in the order of highest ATK, deal additional damage to targets vulnerable to elemental damage, and partially ignore enemies'' DMG Resist at maximum Accelerando stacks. Crème Brûlée Cookie will lose x2 Accelerando stacks if the skill effect ends with the maximum number of stacks. While Crème Brûlée Cookie is using his skill, he will briefly become resistant to interrupting effects.', 'Each ivory key should be played with purpose.', 'Get ready to welcome the star of the night, Crème Brûlée Cookie, famous for his unique reinterpretations of timeless pieces and masterful technique. Having crossed the firmament of academic music like a bright comet, this talented pianist is known for getting extremely sensitive before a performance and leaving the stage as soon as the final note fades away. Such traits have brought forth rumors of Crème Brûlée Cookie''s arrogant nature, and yet he doesn''t seem to pay them any thought. For all he cares for is music! A notorious perfectionist, Crème Brûlée Cookie keeps practicing feverishly until his inner critic is satisfied. Tonight, the excited audience showers the maestro with generous applause as he appears on stage and sits in front of the grand piano. He lays his hands on the keyboard, and, after a brief moment of tense, sincere silence... all worldly notions surrounding Crème Brûlée Cookie vanish, and the mesmerizing sounds of his music resonate through the hall and beyond, touching the very souls of the listeners.', 'Musical, Thorough', 'Alex Bankier'),
('Linzer Cookie', 'Support', 'Rear', 'Epic', 'linzer-cookie.png', '2023-12-13', '{}'::text[], ARRAY['caramel', 'chocolate']::text[], 'The Culprit... is YOU!|Cooldown = 16', '16', 'Linzer Cookie gains Deduction stacks instead of regular attacks. Upon using her skill, she increases the CRIT% of her allies and applies the Suspect debuff to the enemy with the highest ATK, dealing damage to the target and area damage to the enemies nearby. The Suspect debuff is enhanced with Deduction stacks, and when using the skill with the maximum number of stacks, the debuff will decrease the target''s DEF and apply a buff for allies. The renowned writer''s impeccable deduction allows the Suspect debuff to be applied even to targets with debuff immunity. While Linzer Cookie is using her skill, she will briefly become resistant to interrupting effects.', 'Things always seem perfect in the exposition.', 'Who is that tall, elegant lady wearing a fashionable pillbox hat? Why, the world-famous mystery novelist Linzer Cookie, of course! Writing an excellent detective story is like cooking a gourmet dessert: it takes a time-proven recipe of undeniable facts, an array of scrumptious plot twists, a decadent, visceral, plentiful filling of sweet suspense, but, first and foremost, the author''s impeccable craftsmanship and passion. And the overwhelming popularity of Linzer Cookie''s books proves she has it all: each new release means a long queue of faithful fans waiting by the bookstore from the early hours. Betting on the culprit''s identity, trying to solve the sinister riddles... it''s a cult following! Of course, Linzer Cookie never reveals her secrets: with her trusty pen and the signature glint in her eye, the star writer is already working on a new manuscript, stained with a few drops of strawberry jam...', 'Attentive, Sharp-eyed', 'Dawn M. Bennett'),
('Olive Cookie', 'Support', 'Rear', 'Epic', 'olive-cookie.png', '2023-11-03', ARRAY['earth', 'fire', 'electricity']::text[], ARRAY['chocolate', 'almond']::text[], 'Bat Attack|Cooldown=15|Description=Olive Cookie runs off as though she’s forgotten her exploration equipment, then returns chased by a cauldron of bats. She trips, and the bats fly over her to attack enemies in front of Olive Cookie. The bats differ in types depending on their color, they apply debuffs, and Stun enemies with a certain chance.', '15|Description=Olive Cookie runs off as though she’s forgotten her exploration equipment, then returns chased by a cauldron of bats. She trips, and the bats fly over her to attack enemies in front of Olive Cookie. The bats differ in types depending on their color, they apply debuffs, and Stun enemies with a certain chance.', 'Olive Cookie runs off as though she’s forgotten her exploration equipment, then returns chased by a cauldron of bats. She trips, and the bats fly over her to attack enemies in front of Olive Cookie. The bats differ in types depending on their color, they apply debuffs, and Stun enemies with a certain chance.', 'Ancient relics await!', 'From long, winding canyons and dense rainforests to scorching Parmasands! Olive Cookie the archaeologist seeks out remote locations veiled from the world! This Cookie owes her wits and smarts to all the ripe, oily olives in her dough. She''s always busy researching and recording historical facts and important stories of ancient kingdoms. Is that a relic?! A trickle of olive oil runs down her face in the long-awaited moment of excitement...! But there''s no time to celebrate: time to pay respects by publishing the details in a research paper! Olive Cookie will do anything to unearth the secrets of history—like running headfirst into a cave full of bats! Once again, she fixes her glasses, tightens her backpack straps, and ventures toward her next discovery!', NULL, 'Negin Farsad'),
('Mozzarella Cookie', 'Magic', 'Middle', 'Epic', 'mozzarella-cookie.png', '2023-11-03', ARRAY['earth']::text[], ARRAY['chocolate', 'raspberry']::text[], 'Mozzarella Master Plan|Cooldown = 11', '11', 'Mozzarella Cookie rings her bell to apply buffs to allies and summon her Mozzarella Bird. The bird deals damage to enemies and flies off to create a Mozzarella Puddle. Enemies fallen in the puddle will have their movement speed and attack speed reduced.', 'I have a feeling it''s about to get interesting!', 'There''s a Cookie who keeps a keen eye on the Golden Cheese Kingdom from her Control Chamber. Why, it''s none other than Mozzarella Cookie! This Cookie''s been fixing errors left and right in the Golden City under the Big Cheese''s command! From fishing out a Cheesebird''s lost ring in the waterway to tracking down stray monsters, no bug is too big for this smart Cookie! At times, she controls her Marzipan Cookies in the middle of watching a monster fight or supercar race, but she''s never made a mistake! She''s hailed as the Brains of the Golden City—wielding her weapon of endless data flowing through the cheese network, but not even herself knows what she''s really up to. In the darkness of her Control Chamber, only the golden light from her system console reflects her innermost thoughts.', 'Independent, Mysterious', 'Christina Costello'),
('Fettuccine Cookie', 'Defense', 'Front', 'Epic', 'fettuccine-cookie.png', '2023-10-19', ARRAY['earth']::text[], ARRAY['chocolate', 'almond', 'peanut']::text[], 'Unstable Fettuccine|Cooldown = 12|Initial = 1', '12|Initial = 1', 'Fettuccine Cookie taunts enemies and smacks them down with her giant fettuccine arms, dealing DMG, making the enemies prone to Earth-type DMG and reducing their ATK. Next, she restores her HP and gains a Fettuccine Wraps buff. This slightly confused Cookie''s Unstable Aura reduces enemies'' ATK within its range and restores the team''s HP after a given number of enemies within said range are defeated. The more Fettuccine Cookie''s Max HP is reduced, the more her DMG Resist increases. Once per battle, after being defeated, Fettuccine Cookie becomes Immortal and decreases enemies'' ATK SPD with her Unstable Aura at the expense of her own ATK SPD for the duration of her Immortal state. While Fettuccine Cookie is using her skill, she will become resistant to interrupting effects.', 'Woo... I''m... a mummy...', 'Woo... In the vibrant domain of the Golden Cheese Kingdom, one Cookie stands out from the usual crowd—Fettuccine Cookie! While the residents of The Golden City adorn themselves in sparkling gold and jewels, Fettuccine Cookie is wrapped in stale pasta noodles. Then again... considering her instinctive attraction to precious metals, there''s no doubt she hails from the Kingdom of Gold. One look at this Cookie slowly trudging the kingdom''s dark alleys, unaware of her origin or purpose, will send a chill down some Cookies'' dough. Who knows: you might end up transported to a hidden corner of the Golden Cheese Kingdom. Some even say that Fettuccine Cookie herself might be the error... Whether she knows about this theory is unclear, as her only interest seems to be gazing at her reflection in the waters to see if her pasta noodle is wrapped tight.', 'Serene, Mysterious', 'Nadia Hamzeh'),
('Burnt Cheese Cookie', 'Charge', 'Front', 'Epic', 'burnt-cheese-cookie.png', '2023-09-26', ARRAY['earth']::text[], ARRAY['chocolate', 'almond']::text[], 'Protector of the Golden City|Cooldown = 10', '10', 'Summons giant boulders from beneath the earth, dealing DMG to nearby enemies and granting Earth-type CRIT DMG buff for all allies. Afterwards, the boulders explode, dealing DMG and Stunning enemies. Burnt Cheese Cookie grants the Protector of the Golden City and the Curse Protection buffs to himself and the ally Cookie with the highest ATK, absorbing part of the damage they take with DMG Focus and making them Immune to Debuffs. Burnt Cheese Cookie and Golden Cheese Cookie''s DMG Resist increases when entering a battle together. If Golden Cheese Cookie becomes enclosed in her Sarcophagus or enters the Immortal''s Return state during battle, Burnt Cheese Cookie''s ATK and ATK SPD will temporarily increase, and his Cooldown will reset. The Protector of the Golden City and Curse Protection buffs will be applied to Golden Cheese Cookie enclosed in her Sarcophagus or Immortal''s Return state first. While using his skill, Burnt Cheese Cookie will briefly become resistant to interrupting effects.', 'Only the worthy may enter the Golden Paradise!', 'To gain entry to the Ever-Gleaming Golden Paradise, you must pass the trials of the Gatekeeper—Burnt Cheese Cookie. Eternally devoted to the Goddess of the Golden City, this Cookie has warded off countless trespassers at the gates of the Golden Cheese Kingdom. Though many have tried, none have managed to proceed past Burnt Cheese Cookie''s fearsome jackals and the gatekeeper himself, clad in his jackal mask. When asked, "Why do you work tirelessly day and night?" He is reminded of the sacred vow he made to Her Radiance—to protect her kingdom from darkness. So, once again, Burnt Cheese Cookie heads to the gates to serve and protect, to fulfill his duties.', NULL, 'Ryan Colt Levy'),
('Frilled Jellyfish Cookie', 'Support', 'Middle', 'Epic', 'frilled-jellyfish-cookie.png', '2023-09-08', ARRAY['water', 'electricity']::text[], ARRAY['chocolate', 'almond', 'raspberry']::text[], 'Frilled Shackles|Cooldown = 12|Initial = 1', '12|Initial = 1', 'Upon using her skill, Frilled Jellyfish Cookie Shackles up to 5 enemies (targets Cookies first) with her tentacles, dealing Sea Foam damage and reducing their . The targets are inflicted with Zap and take increased Water-type DMG. Additionally, Frilled Jellyfish Cookie will burrow in the ground and protect herself with a DMG Resist buff. When Frilled Jellyfish Cookie uses her skill, ATK SPD changes don''t affect her actions. If Frilled Jellyfish Cookie is defeated, she will dissipate into several little jellyfish, who will periodically provide Healing for the team.', 'My jellyfish told me a new story. Would you like to hear?', '"What news do you bring today, jellyfish?" Frilled Jellyfish Cookie asks her little friends coming from all corners of the sea first thing in the morning. There is no other Cookie in the entire kingdom of Tearcrown with a keener eye for cleanliness and beauty. Carried by seawater, Frilled Jellyfish Cookie appears wherever there is a need for tidying up. Perhaps it is thanks to her tireless efforts the scenery of the Kingdom of Merfolk is so breathtaking. Frilled Jellyfish Cookie''s soft, Jelly-like body allows her to float anywhere in the Saccharine Sea, yet she has chosen to serve only one . When asked why, she always answers, "How could I not love someone full of life?"', 'Lucky, Underwater', 'Jessie Gill'),
('Peppermint Cookie', 'Support', 'Rear', 'Epic', 'peppermint-cookie.png', '2023-08-09', ARRAY['water']::text[], ARRAY['chocolate', 'almond']::text[], 'Freshness of the Sea|Cooldown = 17', '17', 'Peppermint Cookie blows the conch shell to summon the Peppermint Whale. The refreshing sound of the conch shell heals the team, increasing their DMG Resist and Debuff Resist. The Peppermint Whale creates a wave, dealing Water-type damage to enemies in front of it, and also Heals the allies for an amount equal to a portion of the damage dealt. Fresh water brought by the whale covers the team with an HP Shield. Peppermint Cookie will briefly become resistant to interrupting effects while using the skill.', 'Listen to the waves with me!', 'Mint leaves for Peppermint Cookie were gathered from a town near the clear sea. This Cookie likes to spend time at the shore, staring dreamily at the horizon, or playing the shell ocarina. An old friend, the Peppermint Whale, often appears to the sound for company. Peppermint Cookie treasures the simple but unchanging things, just like the waves that come and go. May the Cookie''s smile remain unchanging as well!', 'Lucky, Heat-proof', 'Emily Hinkler'),
('Black Lemonade Cookie', 'Bomber', 'Middle', 'Epic', 'black-lemonade-cookie.png', '2023-07-21', ARRAY['electricity']::text[], ARRAY['raspberry', 'chocolate']::text[], 'Electrifying Rock!|Cooldown = 10', '10', 'Black Lemonade Cookie plays her electric guitar, dealing damage to the enemy with the highest HP (targets Cookies first), inflicting Zap, and applying debuffs that increase CRIT DMG the enemy receives and decrease their DEF. She then deals damage to the nearby enemies and inflicts a debuff reducing their ATK. Black Lemonade Cookie grants the Electrifying Rock Spirit buff to the team and strengthens her next regular attacks to target the enemy with the highest HP and enemies near them. When Ally Cookies with the Electrifying Rock Spirit buff deal Zap damage or a critical hit, their Electrifying Rock! charge increases. Once the Electrifying Rock! is charged, they deal additional damage to enemies. While Black Lemonade Cookie is using her skill, she will briefly become resistant to interrupting effects.', 'This song is gonna be pretty intense!', 'If you happen to pass by a dark basement and hear electrifying guitar sounds along with a fresh citrus scent, you might''ve just stumbled onto Black Lemonade Cookie''s studio! She may look distant and aloof at times, but once she gets on stage, she''s a whole new Cookie! With her signature two-tone lemon icing and energizing sound, every Cookie is bound to shake to the rhythm of her music. Some Cookies find Black Lemonade Cookie''s music hard to follow, but everyone agrees that all of her songs are a labor of love and passion. and that''s what matters to Black Lemonade Cookie, after all. No matter how dark and small the stage, she''ll always continue to sing and give her everything for her dedicated fans!', NULL, 'Jenny Yokobori'),
('Rockstar Cookie', 'Healing', 'Middle', 'Epic', 'rockstar-cookie.png', '2023-07-05', '{}'::text[], ARRAY['chocolate', 'applejelly', 'almond']::text[], 'Legend of Rock|Cooldown=15', '15', 'Rockstar Cookie performs a rock anthem, periodically Healing the team''s HP and applies the Legendary Rock Spirit buff, Curse Protection buff, and a CRIT% buff for the whole team excluding himself based on his CRIT% boost from equipped Toppings. Under Legendary Rock Spirit, the target will have their HP restored whenever they deal . If Rockstar Cookie is defeated for the first time, he will have all active debuffs on himself removed and begin his Encore. During Encore, Rockstar Cookie will provide extra Healing and increase the Healing the team receives. While Rockstar Cookie is using his skill, he will briefly become resistant to interrupting effects.', 'Are you ready to ROCK?!', 'Whaaaaam! Wacka wow! Inside the sizzling oven, Rockstar Cookie discovered the sound of rock ''n'' roll. He realized that to move the audience, one must not only be talented but also feel the true Rock Spirit within! Many legendary hits were created with that philosophy in mind. Every Cookie who has seen Rockstar Cookie perform was changed forever. The blazing sound! The overwhelming charisma! The legend might have taken a path different from his earlier days filled with experimentation, but his Rock Spirit still resonates with everyone!', 'Musical, Independent', 'Michael Schwalbe'),
('Tarte Tatin Cookie', 'Ranged', 'Rear', 'Epic', 'tarte-tatin-cookie.png', '2023-06-08', ARRAY['fire']::text[], ARRAY['raspberry', 'applejelly', 'caramel']::text[], 'Cannonade|Cooldown = 12', '12', 'When Tarte Tatin Cookie fires her cannon, she reduces her own Cooldown and Shackles her enemies after a certain number of hits. Upon using her skill, she will fire a cannonball straight towards the center of the enemy team. Hit enemies suffer from Burn and Bosses receive extra damage. After a certain number of skill uses, Tarte Tatin Cookie will fire an enhanced cannonball. During the battle, when Tarte Tatin Cookie successfully defeats an enemy or a boss, her ATK will increase. While Tarte Tatin Cookie is using her skill, she will briefly become resistant to interrupting effects.', 'Stand back, I''ll take care of that.', 'Whether it''s the past or the future of dragon hunting, you can be sure that Tarte Tatin Cookie is part of it! Years and years of carrying around her customized cannon on dragon hunts far and wide has helped build Tarte Tatin Cookie''s reputation as an extremely skilled and experienced dragon hunter. The way she confronts the dragons, massive threats to all Cookiekind, without even a trace of fear is reminiscent of the Ancient Heroes. It inspires the Cookies around her and sets their battle spirit aflame! Tarte Tatin Cookie may seem hard to approach because of her aloof personality and serious attitude. But unlike her cold exterior, she has a warm side to her that means she never forgets a friend. After all, the best hunters are those who have a lot to protect. You''re sure to find Tarte Tatin Cookie fighting another enormous beast somewhere again today, firing her cannon without hesitation. BOOM!', 'Handy, Sharp-eyed', 'Kat Cressida'),
('Royal Margarine Cookie', 'Ambush', 'Middle', 'Epic', 'royal-margarine-cookie.png', '2023-05-18', ARRAY['poison']::text[], ARRAY['chocolate']::text[], 'Buttercream Blast', '12', 'Royal Margarine Cookie soars on Buttercream''s back and fires Buttercream Blasts at the 3 enemies with the highest ATK thrice. Buttercream Blasts deal damage, Poison the targets, reduce their ATK and DEF, and amplify debuffs they gain. Next, Buttercream swoops down towards the enemies, dealing damage and additional damage in proportion to the number of periodic damage effects the targets'' have applied. Buttercream Blasts target boss monsters first. While Royal Margarine Cookie is using his skill, he will briefly become resistant to interrupting effects.', 'The dragon rider you''ve been waiting for has arrived!', 'When the shadow of the golden dragon glides over Dragon City, it is not fear and dread that fills the old alleyways, but rather excitement and anticipation. The famous Royal Margarine Cookie has arrived! Look at those sleek locks, jaunty attire, and the shiny butter knife tucked under his belt— there is no doubt that this Cookie is the last descendant of the legendary Dragon Rider Clan. Indeed, any seasoned dragon hunter will immediately know that his companion Buttercream is no dragon but a wyvern. But as long as Royal Margarine Cookie is using his dazzling smile as a distraction, such details are no longer of importance. Be careful, however: just one look at that smile is enough to make anyone fall for this handsome Dragon Rider!', 'Intuitive, Venturous', 'Peyton Crim'),
('Kouign-Amann Cookie', 'Defense', 'Front', 'Epic', 'kouign-amann-cookie.png', '2023-04-20', ARRAY['light']::text[], ARRAY['almond', 'raspberry', 'caramel']::text[], 'Paladin''s Way|Cooldown = 12', '12', 'After using the skill, Kouign-Amann Cookie channels the Power of the Light, enhancing her regular attacks: they deal Light-type DMG and extra DMG . Kouign-Amann Cookie will also increase the ATK SPD of the two Cookies with the highest ATK SPD, make all her allies resistant to ATK SPD debuffs, and increase the Light-type DMG dealt by other Cookies. When the skill''s duration reaches its end, Kouign-Amann Cookie will gather the Power of the Light and perform a powerful attack, partially ignoring the target''s DMG Resist with a swing of her sword. Having no fear of defeat, Kouign-Amann Cookie will increase her DMG Resist whenever she gains a debuff, . While Kouign-Amann Cookie is using her skill, she will briefly become resistant to interrupting effects.', 'Behold the honorable Paladin before you!', 'The Crème Knights is a noble institution, known not only for its rich tradition of ceremony and good deportment but also for the frilly dress-wearing Paladin: Kouign-Amann Cookie! Don''t let her lovely appearance distract you; this Cookie is blessed by the Light itself and can defeat even experienced Paladins with just a swing of her sword. Kouign-Amann Cookie always stays true to her path and fights with honor, so it''s no wonder the whole school looks up to her. There was a time when the fear of defeat and disappointing those around her troubled Kouign-Amann Cookie greatly, but instead of running away she faced those fears and conquered the insecurity within herself. For those of you fearless enough to duel this honorable Paladin, may you have a strong conviction and a brave heart! After all, nothing motivates Kouign-Amann Cookie more than battling opponents who have already battled themselves!', 'Brave, Tenacious', 'Ariana Molkara'),
('Prune Juice Cookie', 'Bomber', 'Middle', 'Epic', 'prune-juice-cookie.png', '2023-03-30', ARRAY['poison']::text[], ARRAY['chocolate', 'raspberry', 'applejelly']::text[], 'Prune Juice Potion|Cooldown = 15', '15', 'For Prune Juice Cookie''s regular attack, he throws a Prune Juice Bottle at the farthest enemy, poisoning the target and nearby enemies. Upon using his Skill, Prune Juice Cookie will throw a giant Prune Juice Bottle containing poison. When the bottle shatters, it will inflict Poison DMG Boost, Sticky Goo, Poison, and summon Prune Jellies. The HP of summoned Prune Jellies are reduced by the number of hits. Summoned Prune Jellies will spread Prune Gas from time to time, poisoning nearby enemies. Summoned Prune Jellies are consisted of poison, immune to any kind of periodic effects and are not affected by Shield or Healing.', 'Magic, huh? Just another means to an end, don''t you think?', 'When you smell the fragrant yet subtle scent of plums across the door at the top of the endlessly spiraling staircase, you know Prune Juice Cookie is brewing his magic potions! This Cookie, made from the richest and most potent prune juice, is the best potion maker at the Parfaedia Institute. His potions are amazingly effective-just a single sip will have you feeling the dizzying effects! They say that his outstanding talent is not the sole reason he picked the efficient minimalistic art of potions over fancy, sweet dessert magic... But perhaps it''s not so smart to snoop around the genius potion maker, as his charms and theatrics will persuade you to buy all of his potions! Even if you don''t understand his true intentions, the effort he puts into his potion-making is evident in the ever-boiling cauldron and notebooks covered in potion stains.', 'Handy, Venturous', 'Kenny Yates'),
('Space Doughnut', 'Charge', 'Front', 'Epic', 'space-doughnut.png', '2023-03-09', '{}'::text[], ARRAY['chocolate']::text[], 'Doughnut Beam|Cooldown=12', '12', 'Fires the Doughnut Beam, dealing damage, reducing the targets'' DEF, and amplifying debuffs they receive. Hit targets will turn into donuts (excluding bosses and Cookies). The target will receive extra damage if they are already afflicted with a DEF-reducing debuff. When the targets turned to donuts reach a certain number, Space Doughnut will use Super Doughnut Blast, rolling over the enemies, dealing damage and Stunning them. Space Doughnut does not take damage while using their skill.', 'Kyou-kya! Kyou-kya?', 'Communication with this mysterious creature has proven to be a rather daunting task. We have yet to determine where they came from, where they are going, or even what they taste like... Does the Space Doughnut know? Another mystery! However, nothing stops us from befriending this adorable being even though we don''t share the same language. And it seems like the Space Doughnut has already made a bunch of flat friends on their way here!', 'Curious, Mysterious', NULL),
('Blueberry Pie Cookie', 'Magic', 'Middle', 'Epic', 'blueberry-pie-cookie.png', '2023-02-14', ARRAY['electricity']::text[], ARRAY['applejelly', 'caramel', 'raspberry']::text[], 'Cursed Tome|Cooldown = 15', '15', 'An evil spirit appears from the Tome, dealing damage to the enemies and inflicting them with the Greed of the Tome debuff. It will also heal Blueberry Pie Cookie’s HP and increase her DMG Resist. The Tome will gain a stack of Greed whenever the spirit deals damage to Cookies, or the target inflicted with the Greed of the Tome debuff becomes incapacitated. Once the Tome has enough stacks of Greed, it will unleash its Sealed Power, increasing Blueberry Pie Cookie''s ATK and dealing DMG to the enemies. While Blueberry Pie Cookie is using her skill, she will briefly become resistant to interrupting effects. DMG proportional to Max HP is capped at 300,000.', 'I know all there is about the Archives.', 'Somewhere within the abandoned and silent City of Wizards, a lone Cookie remains in the towering Archives. Blueberry Pie Cookie has kept watch over the Wizard Archives'' dangerous tomes for countless years. Following her destiny, she continues to organize the endless shelves day by day. On a dark moonless night, when an oath to the Wizards had faded away with the light, Blueberry Pie Cookie''s curiosity got the better of her: she opened and read one of the forbidden tomes... As days and nights of caretaking the Archives pass, she takes solace in a slender beam of moonlight that creeps in through a small window. Was forsaking an oath too much for a Cookie to handle?', 'Attentive, Thorough', 'Burgandi Trejo Phoenix'),
('Milky Way Cookie', 'Charge', 'Front', 'Epic', 'milky-way-cookie.png', '2023-01-19', '{}'::text[], ARRAY['chocolate', 'almond', 'caramel']::text[], 'Sugarcloud Express|Cooldown = 15', '15', 'Milky Way Cookie jumps onto her dream train, gaining a DMG Reduction buff and providing a Stun Resistance buff for the entire team. Then she will push back the enemies several times, applying a DEF Reduction debuff and dealing damage. Once she''s done with her shift, Milky Way Cookie will cast a Shield onto herself and the rest of the team. While Milky Way Cookie is using her skill, she will briefly become resistant to interrupting effects. Being a dweller of the World of Dreams, Milky Way Cookie is not susceptible to the Beckoning Dreams & Dream of Doom effect.', 'Choo choo! Next station is... The World of Dreams!', 'Take a handful of star powder gathered from all over the Milky Way Galaxy, illuminate it with delicate moonlight—and voila! Meet Milky Way Cookie, the faithful servant and the conductor of the Sugarcloud Express that will take you to your sweetest dreams and back. Don''t be afraid and hop on: one sprinkle of Milky Way Cookie''s star powder is enough for a colorful, vibrant dream-just like reality but better! Everything is possible in the World of Dreams, and accidents happen, too: every now and then, the train''s floor disappears, and cars reshuffle randomly, leaving crowds of passengers in utter confusion. And right in the middle of the conductor''s scheduled nap time! But professionalism never betrays, and there is no problem Milky Way Cookie can''t sort out. Colorful hair neatly tied with a Star Jelly, conductor''s hat on, and choo choo! The Sugarcloud Express will deliver you to your dreamy destination according to the schedule. Just make a wish upon a twinkling star...!', 'Brave, Lucky', 'Della Saba'),
('Prophet Cookie', 'Support', 'Rear', 'Epic', 'prophet-cookie.png', '2023-01-05', '{}'::text[], ARRAY['almond', 'chocolate']::text[], 'Seven Prophecies|Cooldown=19', '19', 'Prophet Cookie delivers one out of seven prophecies. Upon invoking a prophecy, Prophet Cookie will heal an ally and amplify buffs they receive. Additionally, an extra skill effect will be activated depending on the symbol of the prophecy, dealing damage to the enemies and amplifying debuffs they receive. The debuffs applied by the prophecies are weaker than those of the original skills and does not inflict elemental type DMG. Some prophecies do not have any additional effects. You can lock the effect of the prophecy, guaranteeing a specific effect, by equipping Toppings. While Prophet Cookie is using his skill, he will briefly become resistant to interrupting effects. Wandering around the Kingdom, Prophet Cookie will come up with Fortune Cookies every three days. Tap the Fortune Cookie to obtain a gift. The higher Prophet Cookie’s rank, the better gift!', 'Ah, I''ve been expecting you...', 'This wizened Cookie is often called "Fortune Cookie" for his ability to know what''s coming before it happens. His Scroll of Prophecy guides his path, even if it isn''t always right. Some say the source of his foresight is his mysterious purple Crystal Ball, but in reality, it is his majestic beard!', NULL, 'Gideon Emery'),
('Pinecone Cookie', 'Bomber', 'Front', 'Epic', 'pinecone-cookie.png', '2022-12-14', ARRAY['ice']::text[], ARRAY['caramel', 'almond', 'raspberry']::text[], 'Pinecone Bomb|Cooldown=12', '12', 'Pinecone Cookie gets up on the tree golem and simultaneously heals themselves and the two allies with the highest ATK. While Pinecone Cookie is riding the tree golem, their Max HP is increased. Pinecone Cookie then throws Pinecone bombs at the enemy Cookie with the highest ATK, Stunning them. The Pinecone Bombs deal area damage to nearby enemies. If there are targets suffering from Frost within the area damage range, they will also become Stunned. If a target is immune to Stun, it will receive additional DMG.', 'The mighty forest keeper is here to protect the woods!', 'If you see a little Cookie running among the trees, it''s probably Pinecone Cookie, the mighty keeper of the forest. Get outta the way! Busy, busy! The forest is so vast, yet there''s only one Pinecone Cookie! There is so much to do: help the forest animals prepare for winter hibernation, straighten out the quarreling birds, find and scratch that itchy patch of bark for the oak tree, and much more! Each choco bark layer of Pinecone Cookie''s imposing hat is filled with eagerness to protect their woodland home. That''s right: the forest has been their home for as long as they can remember—which is why they prefer the company of trees and animals. Yes, the mighty forest keeper is hardly familiar with the ways of their fellow Cookies! But what does it matter when they know everything about the forest dwellers and can understand the language of the rustling leaves?!', 'Cold-proof, Nature-loving', 'Mara Junot'),
('Carol Cookie', 'Healing', 'Rear', 'Epic', 'carol-cookie.png', '2022-11-30', ARRAY['grass']::text[], ARRAY['chocolate', 'almond']::text[], 'Magic Songs', '16', 'Sings the Song of Joy to restore the team''s HP and increase their CRIT% and CRIT DMG. When only two or fewer Cookies are left, including Carol Cookie, switches to the Song of Change instead, having her Cooldown immediately reset and decreased for the remainder of the battle. The Song of Change damages the enemies, increases the team''s CRIT% and CRIT DMG, and reduces the Cooldown for the remaining team members. With each regular attack, Carol Cookie sings the Song of Energy and restores the entire team''s HP. However, the fewer team members she needs to heal, the more healing each individual member will receive. While Carol Cookie is using her skill, she will briefly become resistant to interrupting effects.', 'A song to soothe your soul!', 'This gentle Cookie believes that the song is stronger than the sword! She knows how to exert great power with beautiful poetry and melodies only. "No matter what happens, I will always have my songs. My Song of Love will always be around, my Song of Peace will cast darkness away, and my Song of Comfort will bring a smile to a tired face!"', NULL, 'Bailey Stender'),
('Macaron Cookie', 'Magic', 'Middle', 'Epic', 'macaron-cookie.png', '2022-11-09', '{}'::text[], ARRAY['chocolate', 'raspberry']::text[], 'Mighty Macaron Parade|Cooldown = 15', '15', 'Following Macaron Cookie''s exciting cheer, the Macaron Animals will start marching, dealing DMG to nearby enemies. Non-Cookie enemies will receive additional DMG. Her contagious enthusiasm will increase the ATK and CRIT% of her allies and restore their HP. Depending on the number of hits from the Macaron Animals, Macaron Cookie will gain a stack of the Happy Parade buff. Macaron Cookie will then restore the HP of her allies proportional to the number of stacks of Happy Parade once the parade is over. While Macaron Cookie is using her skill, she will briefly become resistant to interrupting effects.', 'Let''s begin our parade!', 'Did you think this Cookie was made with artificial food coloring? Guess again! She is made with 100% all-natural ingredients. Even her long, gorgeous eyelashes are completely organic. Cookies are drawn to her friendly smile and gentle voice. In fact, cute little Macaron Animals love to gather around her too. Once she starts playing on her macaron drum, the Macaron Animals start a tiny parade. At times, the parade can get out of hand, but Macaron Cookie still enjoys the company anyway. When she gets really excited, Macaron Cookie may demonstrate her most festive performance for you.', 'Musical, Venturous,', 'Paula Rhodes'),
('Schwarzwälder', 'Charge', 'Front', 'Epic', 'schwarzwalder.png', '2022-10-13', ARRAY['steel', 'chaos']::text[], ARRAY['almond', 'chocolate']::text[], 'Choco Chip Hammer|Cooldown = 12|Initial = 2', '12|Initial = 2', 'Each Schwarzwälder''s regular attacks has a chance to stun the target. The first cooldown of his skill will be shortened, allowing for faster skill use. Upon using the skill, Schwarzwälder will receive the Howling effect, increasing his own ATK SPD, and DMG Resist, and increasing the team''s ATK. When the effect duration is over, Schwarzwälder will charge at the enemies, strike them with his hammer, stun them, and inflict the Hammer Shock debuff. The debuff will reduce the enemies’ ATK and cause them to receive more damage from the next Schwarzwälder''s skill attacks with the hammer. While Schwarzwälder is using his skill, he will briefly become resistant to interrupting effects.', 'Want a taste of THIS hammer?', 'Red eyes, rough mane, sharp fangs! His name is Choco Werehound Brute, and his enormous hammer will make the Cookie Kingdom tremble! And if the sound of the distant thumping of this fearsome giant''s heavy feet is not enough, his roar will make you faint! Choco Werehound Brute might be no more than underling running itsy-bitsy errands, but his ambitions do not end here. Far from it! One day, he will become the strongest Cake Monster, and then, THEN...! The whole world will fear the name "Choco Werehound Brute!" And so, the big dreamer bids farewell to another gorgeous sunset under the pouring rain... The life of an upstart villain is rough and tough, but Choco Werehound Brute must be strong. He must not let anyone know of his proper aristocratic upbringing and his real name... Schwarzwälder.', NULL, 'Kellen Goff'),
('Candy Diver Cookie', 'Support', 'Rear', 'Epic', 'candy-diver-cookie.png', '2022-09-27', '{}'::text[], ARRAY['candy', 'chocolate']::text[], 'Deep-sea Diver|Cooldown=15', '15', 'While wandering the depths of the Duskgloom Sea, Candy Diver Cookie has become immune to enemy attacks by obtaining the Safeguarded ability. Their regular attacks reduce the DEF and increase DMG received by the nearest enemy. Upon using the skill, Candy Diver Cookie will discover various relics from the deep sea, providing buffs and healing to the Cookie''s allies The super success rate will increase depending on Candy Diver Cookie''s Amplify Buff rate. Every relic provides a different effect.', '●●●!! ◀◎○???', 'Plop... Splash! Candy Diver Cookie pulls the lever on the wetsuit, and the two gumballs swirl a lap inside their helmet. Always out there, charting the unknown regions of the ocean floor, making sketches of fishes no one has ever seen, this deep-sea explorer might be tiny, but they leave an unforgettable first impression. Candy Diver Cookie has examined every underwater nook and cranny through the barnacled candy glass and probably witnessed whole coral forests grow and dissipate into pale dust that covers the soggy carcasses of sunken ships. All this curiosity, yet Candy Diver Cookie cannot find the answer to this one question: how does one end up all alone at the sea bottom? Whenever they try to catch onto the pieces of this mystery in the ocean of memory, they slip into the darker, deeper abyss.', 'Venturous, Underwater', '○●◎◆'),
('Captain Caviar Cookie', 'Bomber', 'Middle', 'Epic', 'captain-caviar-cookie.png', '2022-09-06', ARRAY['water']::text[], ARRAY['raspberry']::text[], 'Black Shark Torpedo|Cooldown = 15', '15', 'Captain''s orders! The Black Shark submarine will appear at Captain Caviar Cookie''s call, shoot 3 Black Shark Torpedoes at the enemies, and increase the team''s Debuff Resist. Augmented with the latest technology of the Republic, the torpedoes will aim for the enemy with the lowest HP (targets Cookies first) in descending order. Once the torpedo hits the target, it will cause an explosion, dealing area damage and inflicting DEF Reduction. Captain Caviar Cookie is immune to any type of Fear, for he is a fearless sea wolf. While Captain Caviar Cookie is using his skill, he will briefly become resistant to interrupting effects.', 'It''s CAPTAIN Caviar Cookie to the likes of you!', '"Don''t ya dare fear the waves as long as you have a Captain in me!" Captain Caviar Cookie''s bellowing voice, louder than the squall itself, can inspire the most desperate and ragtag bunch of sailors! This sea wolf laughs in the face of gale and waves-after all, the very caviar in his dough was a gift of a tide much rougher. It is easy to mistake the ever frowning, sharp-toothed Cookie for a vile pirate, but make no mistake: this Cookie before you is a respected Elder, one of the Republic''s most famed heroes, savior of Choco Mud Town, and the bane of all villains and monsters plaguing the seas. Captain Caviar Cookie''s trusty ship, the Salty Shark, and its seasoned crew have weathered many a storm only to find a way out to a safe haven. What song will they sing today, sailing towards a new glorious adventure?', 'Underwater, Nature-loving', 'Dave Fennoy'),
('Cream Unicorn Cookie', 'Healing', 'Rear', 'Epic', 'cream-unicorn-cookie.png', '2022-07-28', ARRAY['fire']::text[], ARRAY['chocolate', 'applejelly']::text[], 'Midsummer Night''s Dream|Cooldown = 17', '17', 'The music starts, and Cream Unicorn Cookie transforms into the Dreamy Unicorn. The Dreamy Unicorn reduces CRIT DMG received by the team and charges towards the enemies, silencing them. While silenced, the enemies skill Cooldown will be paused. The Dreamy Unicorn will leave Dancing Butterflies behind itself. These butterflies will fly towards the allies and heal them. The amount of Healing received depends on the amount of HP lost. Regular Healing targets will receive a DMG-reducing buff.', 'Laughing together is a true marvel...', 'A desolate amusement park lies in darkness. Lights flicker on one by one. A merry-go-round begins to rotate slow and steady to a bygone song of the past. The park magically returns to life as a lone pony, embraced by the purest of rainbows, opens their eyes. The silky mane and creamy tail turn into elegant locks of hair. Decorations spring to life as fluttering sugar butterflies. Cream Unicorn Cookie flies around the park with the sugar butterflies in tow. After floating among the attractions, a graceful landing on top of the Ferris wheel concludes the course. A whisper escapes while gazing upon the entirety of the park. "In the end, all that shines are memories and stars." A flashback of the glee and joy of young Cookies running towards the merry-go-round plays before wistful eyes. If only it could turn for eternity... A dream of happiness and laughter has manifested as a unicorn. The dream never stops, regardless of night or day.', 'Lucky, Intuitive', 'Joshua David King'),
('Financier Cookie', 'Defense', 'Front', 'Epic', 'financier-cookie.png', '2022-07-07', ARRAY['light']::text[], ARRAY['chocolate', 'almond']::text[], 'Paladin Protection|Cooldown = 15', '15', 'Like a true Paladin of unfaltering belief, Financier Cookie protects an ally Cookie from the start of the battle until the moment she hits the ground. Financier Cookie''s top priority is Clotted Cream Cookie, but if he is not present, she''ll protect the allied Cookie with the highest ATK. Upon using her skill, Financier Cookie''s regular attack will deal area damage, she will also heal herself, the Cookie she is protecting, increase their ATK, DMG and CRIT Resist, and grant them the Light''s Shield. She will then deal area damage against her enemies. The Light''s Shield will act as a Shield and deliver the Light''s Judgment to those who dare to damage it when it disappears. While Financier Cookie is using her skill, she will briefly become resistant to interrupting effects.', 'Financier Cookie, at your service.', '"I will only kneel before the Divines!" Financier Cookie has the qualities of an exemplary Paladin: she is most humble and sincere when offering a prayer yet radiates confidence and power, wielding her sword. No other cadet of the Paladin Academy could parallel Financier Cookie''s outstanding abilities—perhaps, she was meant to be chosen for the honorable position of the personal bodyguard. A true Paladin does not flinch at an order: the greatest deeds perpetuating the order''s glory are done by those who are not afraid of challenges, and Financier Cookie marches towards her goal with scrupulous and cold determination. But appearances can be deceiving: seek the Republic''s most unfortunate, and they will tell you the Paladin''s heart is full of kindness and compassion.', NULL, 'Marissa Lenti'),
('Crunchy Chip Cookie', 'Charge', 'Front', 'Epic', 'crunchy-chip-cookie.png', '2022-05-27', ARRAY['darkness']::text[], ARRAY['almond', 'applejelly']::text[], 'Wolf Squadron', '13', 'Crunchy Chip Cookie''s regular attacks leave the Claw Mark on the enemy with the highest ATK. Upon using the skill, the Cookie charges towards the enemies, slamming them and summoning his Cream Wolf. When Crunchy Chip Cookie is defeated, the Cream Wolf becomes enraged and continues fighting alone. In this state, the Cream Wolf becomes resistant to incapacitating effects. If Crunchy Chip Cookie is revived, he will hop back onto the Cream Wolf. Crunchy Chip Cookie and his wolves are less affected by Knockbacks and Flying. While Crunchy Chip Cookie is using his skill, he will briefly become resistant to interrupting effects.', 'Owooo! Guess who''s here first! Ha ha!', 'One howl is all it takes to prep the Cream Wolves for battle, even in the middle of the night. Led by Crunchy Chip Cookie, this elite squad protects the frozen borders of the Dark Cacao Kingdom. The squad captain may be famous for his quick temper—which is not surprising given the sheer amount of the crunchiest choco chips in his dough—but rest assured: Crunchy Chip Cookie is loyal and reliable, just like his white-maned wolf companion. His oath to his king has kept him and his comrades persevering through piercing winds and snowstorms to ensure the kingdom''s safety from the Licorice Sea. No other squadron stands a chance against these ferocious warriors that race through the mountains on the back of their wolves, defeating every monster they come across. Another serene morning in the Dark Cacao Kingdom; perhaps, we have to thank Captain Crunchy Chip Cookie for it!', 'Cold-proof, Intuitive', 'Justice Washington'),
('Wildberry Cookie', 'Defense', 'Front', 'Epic', 'wildberry-cookie.png', '2022-05-03', ARRAY['steel']::text[], ARRAY['peanut', 'almond']::text[], 'Wild Punch|Cooldown = 10', '10', 'Wildberry Cookie unleashes his Battle Rage, dealing more powerful attacks and activating his Wild buff that cannot be dispelled. At the end of the Battle Rage mode, Wildberry Cookie musters all his strength, dealing an uppercut and a final blow. The Wild buff will stack with each hit Wildberry Cookie receives: the more stacks he has, the more powerful his final blow''s DMG will be. While Wildberry Cookie is dealing an uppercut and his final blow, he will become resistant to interrupting effects. Being a large Cookie, Wildberry Cookie is less affected by Knockback or Flying.', 'For the Hollyberry Kingdom!', 'Filled to the brim with wild tropical berries, Wildberry Cookie''s ardent loyalty to the Hollyberry Kingdom is unquestionable. And the brightly gleaming jewel embedded into his mighty gauntlet is proof! Young Wildberry Cookie once roamed the ramshackle alleys of the Hollyberry capital until an offered him a helping hand. Insidious whispers have been following this knight of few words ever since: they claim he is prone to solving problems with brute force, but these rumors cannot be farther from the truth. Wildberry Cookie has sworn to do whatever it takes to protect his kingdom and its royal dynasty! Even though sometimes what it takes is serving generous amounts of berry juice!', 'Brawny, Serene', 'Kamran Nikhad'),
('Cherry Blossom Cookie', 'Ambush', 'Rear', 'Epic', 'cherry-blossom-cookie.png', '2022-04-18', ARRAY['grass']::text[], ARRAY['raspberry', 'chocolate']::text[], 'Cherry Blossom Rain', '17|Description=Get ready for a storm of cherry blossoms! Cherry Blossom Cookie flies up to shower her enemies with a rain of cherry blossoms, dealing area damage. She will deal additional damage to non-Cookie opponents and increase the ATK of all allies: the bonus value will depend on the number of enemies hit with the skill.', 'Get ready for a storm of cherry blossoms! Cherry Blossom Cookie flies up to shower her enemies with a rain of cherry blossoms, dealing area damage. She will deal additional damage to non-Cookie opponents and increase the ATK of all allies: the bonus value will depend on the number of enemies hit with the skill.', '1=Shall we go on a picnic?', 'On a warm spring day, the first pink cherry blossoms were collected, then infused for a generous amount of time. Then this essence was used to create Cherry Blossom Cookie. Just by looking at her, you will feel splendid and warm inside, with a tingle on both your cheeks. On a perfect day, you can see her humming, trying to fly into the air with her umbrella open. She is most adorable when she offers you delicious sandwiches and tea. But watch out, once she starts to chat, you will lose track of time!', 'Brave, Friendly', 'Sarah Wiedenheft'),
('Caramel Arrow Cookie', 'Ranged', 'Front', 'Epic', 'caramel-arrow-cookie.png', '2022-03-25', ARRAY['darkness']::text[], ARRAY['raspberry', 'almond', 'caramel']::text[], 'Arrow of Resolution|Cooldown = 10', '10', 'Few enemies can keep their wits when they see the twin blades turning into a bow! Caramel Arrow Cookie performs a ranged attack (targets Cookies first) and leaves an Arrow Mark on the hit enemy. After the ranged attack, the Arrow Mark explodes when Caramel Arrow Cookie rushes towards the enemy, dealing DMG proportional to the enemy''s Max HP (this DMG is capped at 300,000). During the ranged attack, Caramel Arrow Cookie receives a buff that makes her immune to debuffs. While Caramel Arrow Cookie is using her skill, she will become resistant to interrupting effects.', 'I shall defend the Wall with my life.', 'At the very edge of the continent, atop the tall wall of the Black Citadel, stands a figure frowning into the dark. Night and day, all year round, Caramel Arrow Cookie, the First Watcher of the Dark Cacao Kingdom, will always protect the Cookies from the horrors of the Licorice Sea. A master of the Dark Cacao martial art tradition of the perfect balance and a wielder of the black and white twin blades, Caramel Arrow Cookie''s loyalty to her king and subordinates remains unwavering even in exile. Some say the kingdom is but a shadow of its former glory, with values like trust becoming a commodity. But a vow is a vow. Standing there atop the tall wall, Caramel Arrow Cookie is staring sharply at the churning dark waters below. The First Watcher will protect the Dark Cacao Kingdom until the very last crumb.', 'Agile, Sharp-eyed', 'Dani Chambers'),
('Affogato Cookie', 'Bomber', 'Middle', 'Epic', 'affogato-cookie.png', '2022-02-24', ARRAY['poison']::text[], ARRAY['raspberry', 'chocolate']::text[], 'Sweet Scheme|Cooldown = 15', '15', 'Secretly curses the enemy with the highest ATK (targets Cookies first). The cursed target cannot receive any buff effects for a certain time (limited to buffs that can be dispelled). It will also receive amplified debuffs and will spread Poison inflicting periodic damage to nearby enemies and themselves. If Poison is dispelled, it will cause great damage to nearby enemies.', 'The best medicine... tastes sweet in your mouth.', 'One piping hot cup of dark roasted coffee and a frozen scoop of the sweetest vanilla ice cream! Born of two desserts—so different yet so delicious—Affogato Cookie''s flavor is unparalleled! Neither coffee nor ice cream, Affogato Cookie spent restless years without a place to belong until he came up with a simple solution: to create a land of his own once and for all! He appeared out of nowhere on a frigid night in the Dark Cacao Kingdom and has been busy earning the trust and favor of the locals with the help of his strange concoctions and mysterious chants. These are troubling times for the Dark Cacao Kingdom and the throne is empty... What sinister intention is Affogato Cookie hiding behind his snide smile?', 'Analytical, Independent', 'Conrad Haynes'),
('Tea Knight Cookie', 'Charge', 'Front', 'Epic', 'tea-knight-cookie.png', '2022-01-19', ARRAY['steel']::text[], ARRAY['almond', 'raspberry']::text[], 'Battlemaster|Cooldown = 13', '13', 'Inflicts damage to the nearest enemy (targets Cookies first) and leads the battle on, providing a buff for his allies. There are several kinds of available buffs; each kind is applied to the Cookie meeting the required conditions. Whenever an allied Cookie is defeated, the Wrath of the Commander effect is triggered. Wrath of the Commander cannot be dispelled and stacks up to four times. At maximum stacks, Tea Knight Cookie will become resistant to interrupting effects.', 'Never forget your oaths, young one.', 'There was a time when dreadful dragons ruled the skies. Their fire ravaged entire kingdoms, and their claws crumbled countless Cookies. An order of knights in shiny silver armor, infused with courage and battle prowess, swore to put an end to this threat. Led by Tea Knight Cookie, the knights courageously opposed the gargantuan monsters through fire and jam and remained in history. But even the most fragrant tea loses its aroma—with time, the glorious tale of the knight became a legend, a mere echo of the past. Tea Knight Cookie, the fearless hero, was forgotten by those he strove to protect. Now sadness and regret shadow his scar-ridden face. Perhaps he wanted to be forgotten...? Yet... when he reminisces the battles he fought side by side with his comrades of old, a spark lights up in his eyes: the flame within him still burns bright!', NULL, 'Jason Marnocha'),
('Eclair Cookie', 'Support', 'Middle', 'Epic', 'eclair-cookie.png', '2022-01-19', '{}'::text[], ARRAY['chocolate', 'almond']::text[], 'Book of History|Cooldown = 16', '16', 'With all the knowledge and research accumulated over the years, analyzes and identifies the opponent''s weakness. Casts ''Weakness'' debuff to 3 enemies with the highest ATK (targets Cookies first), amplifying the DMG they receive, and deals DMG. If the enemy is defeated while under the Weakness debuff, all allies gain an HP shield.', 'Ah, have you brought me a relic? Come now, let me take a look!', 'When you''re looking around the museum, taking a look at the ancient relics that hold mysteries and stories untold, it feels as if the whole world has grown peaceful and silent. That''s usually when the curator of this museum will approach you with a gentle and kind greeting. Eclair Cookie, at your service! With an entire dessert covered in premium fondant icing adorning his hat, he''ll greet guests of the museum with elegance and grace, all while making sure there''s no trace of dust to be found. But it must be said that he tends to go overboard with his explanations whenever a guest shows interest in his favorite topic: dragon-fighter Cookies! Which is precisely why he''s mostly seen in his office, writing reports on these brave and heroic dragon-fighter Cookies. He may be sitting in front of his desk, but do not underestimate his scholarly heart—for his passion for history burns bright as any other adventurer exploring this world.', 'Analytical, Friendly', 'Zeno Robinson'),
('Cocoa Cookie', 'Defense', 'Front', 'Epic', 'cocoa-cookie.png', '2021-12-09', '{}'::text[], ARRAY['almond', 'chocolate']::text[], 'Cocoa is Love|Cooldown=15', '15', 'Cocoa Cookie jumps into a giant cocoa mug and happily spins around for a given time, attacking the enemies. At the same time, Cocoa Cookie restores the HP for all allied Cookies except for summoned creatures and makes them immune to stunning. While Cocoa Cookie is using her skill, she will briefly become resistant to interrupting effects. Cocoa Cookie''s regular attack will heal 3 allies (targets Cookies first) with the lowest HP.', '1=How about a cup of cocoa?', 'Even if her dough is 80% cocoa, she''s always sipping hot cocoa, even during the summer time. Her marshmallow hat is so deliciously sweet, she needs to resist the temptation of taking a chunk out of it and dipping it into her cup. Her plump smooth cheeks just add to her charm! When she indulges in a freshly prepared cup of cocoa, all her worries melt away.', 'Attentive, Friendly', 'Kody Kavitha'),
('Cotton Cookie', 'Support', 'Rear', 'Epic', 'cotton-cookie.png', '2021-11-18', ARRAY['grass']::text[], ARRAY['chocolate']::text[], 'A Warm Light|Cooldown = 17', '17', 'While Cotton Cookie''s lantern shines, the warm light will periodically restore the allies'' HP and increase the summoned creatures'' ATK. Additionally, Cotton Cookie summons sheep that will charge at the enemies, dealing area damage and stunning them. The summoned sheep will fight alongside the Cookies for a certain time. While Cotton Cookie is using her skill, she will briefly become resistant to interrupting effects.', 'I hope this light will reach all corners of this land...', 'The soft and warm cotton fluff in Cotton Cookie''s dough granted her a heart so warm not even a raging blizzard could scare her off. The way she handles her flock of cute wooly sheep ever so gently with her tiny lantern in hand can make anyone feel at peace! Having a lantern in Cotton Cookie''s land of constant snowfall is very important: not only stray sheep but also Cookies lost among the dreary white hills depend on it. Cotton Cookie can often be seen restlessly looking at the sky on snowy days&mdash;as though expecting to find something amidst the drifting snowflakes. Sometimes, she mentions a Cookie dear to her: her serene, calm face lightens up, making the listener wonder... what happened? Will we ever learn that someone out there is keeping a piece of these snowy plains in their heart? And that a warm yellow light of the tiny lantern will always shine for that special someone. Always.', NULL, 'Cherami Leigh'),
('Pumpkin Pie Cookie', 'Magic', 'Middle', 'Epic', 'pumpkin-pie-cookie.png', '2021-10-28', ARRAY['darkness']::text[], ARRAY['almond', 'raspberry', 'chocolate']::text[], 'Pompon, help!|Cooldown = 17|Initial = 1', '17|Initial = 1', 'Pumpkin Pie Cookie''s Pompon grows to a giant size, causing area damage. For a given period of time, Giant Pompon inflicts melee area damage up to 3 enemies and applies a non-stackable debuff, decreasing the amount of healing the enemies receive. While on the battlefield, Giant Pompon increases ATK SPD for all allied summoned creatures. Giant Pompon will be more resistant to interrupting effects while performing the first special attack. Also, Pumpkin Pie Cookie can use her decreased first cooldown to use the skill sooner. Pompon is resistant to certain interruption effects.', 'We''ll always be together, Pompon...', 'It''s Halloween, a time of spooky fun for all ghosts and Cookies. And amidst the Jack-o''-lanterns adorning the streets, stands Pumpkin Pie Cookie watching others dressed up in their costumes. Perhaps it''s because she was made of a pumpkin that grew in the shade of an abandoned house, untouched by the sun, but she seems... distant, even though she has a smile on her face. One might try to escape this Cookie''s uncanny presence, but there is something eerily captivating in the way she slowly bats her eyelashes... Pumpkin Pie Cookie''s favorite things on Earthbread are her fluffy and poofy dress that resembles a pumpkin and the old, tattered doll she always carries around. This Cookie will hold your hand and drag you to play with her whenever there''s an exciting festival. Surprisingly, no one has ever said no. You can only wonder if it''s because of Pumpkin Pie Cookie''s doll that looks almost alive or the giant wavering shadow behind her...', 'Analytical, Curious', 'Suzie Yeung'),
('Twizzly Gummy Cookie', 'Ranged', 'Rear', 'Epic', 'twizzly-gummy-cookie.png', '2021-10-08', ARRAY['electricity']::text[], ARRAY['applejelly', 'chocolate']::text[], 'Twizzly Beam|Cooldown=16', '16', 'Twizzly Gummy Cookie overloads her Electrojelly Gun and fires a powerful electrifying laser beam. While Twizzly Gummy Cookie is using her skill, her CRIT DMG is increased and enemies hit by her laser beam will be Zapped. This is a non-stackable debuff that deals periodic damage and temporarily disrupts HP Shields. While Twizzly Gummy Cookie is charging her laser, she will briefly become resistant to interrupting effects.', 'Ha... ha ha! HA HA! HA HA HA! Who''s next?!', 'Would you look at that? Gummy wires twisted here and there, sparks flying everywhere! Maybe that''s why Twizzly Gummy Cookie''s temperament is like chaos itself! She insists that if she doesn''t wreak havoc even for one day, her hair will start crackling electricity! *BZZZZT* With her ticking time bomb of a Electrojelly Gun, she will bulldoze a planet and pulverize the planet right next to it! No wonder they call her the Cosmic Criminal—look at her cause absolute mayhem everywhere she lands! To her, battles are just another game that gives her electrifying thrills. Looks like she''s done messing with her universe and ready to jump to another dimension! Just what could she be plotting next? Her evil cackling and rampaging sparks can''t be good news... Well, good luck to those who come in her way... because it''s gonna hurt!', 'Tenacious, Independent', 'Dawn M. Bennett'),
('Mala Sauce Cookie', 'Charge', 'Front', 'Epic', 'mala-sauce-cookie.png', '2021-10-08', ARRAY['fire']::text[], ARRAY['almond', 'raspberry']::text[], 'Spicy Mala Strike|Cooldown = 15', '15', 'Strikes the ground with her mace, rupturing it and dealing area damage. Spicy Mala Sauce lava will erupt from the crack and apply the Burn debuff dealing periodic damage to the enemies. In addition, this skill increases the CRIT% of the two allies (targets Cookies first) with the highest CRIT% stat. While Mala Sauce Cookie is using her skill, she will briefly become resistant to interrupting effects.', 'Time to spice things up!', 'The blistering heat of the Dragon''s Valley seems inhospitable to all forms of life. That is... until you get to know the spicy Cookies of the Mala Tribe. The entire tribe is unyieldingly spicy, but none come close to Mala Sauce Cookie with her mind-numbing, fiery taste! Her strength knows no bounds: a simple tap on a boulder shatter it to pieces, a full swing of her Morning Star Anise triggers a massive whirlwind. Due to her fierce determination to protect the tribe, she was the only cookie who succeeded in the dreaded Trial of the Dragon. It''s no wonder that she is destined to be the future leader! Despite the twists and turns with her first adventure outside of the village, if she can captivate the spicy denizens of the Mala Tribe, the outside world doesn''t stand a chance!', 'Brave, Heat-proof', 'Caitlyn Elizabeth'),
('Moon Rabbit Cookie', 'Defense', 'Front', 'Epic', 'moon-rabbit-cookie.png', '2021-09-17', '{}'::text[], ARRAY['almond', 'chocolate']::text[], 'Giant Rice Cake Bunny|Cooldown=14', '14', 'After transforming into a Giant Rice Cake Bunny, Moon Rabbit Cookie jumps up and down, dealing DMG to all enemies. Enemies hit with this skill will be marked with a Healing Rice Cake, and when the marked enemies are defeated, the Healing Cake will restore the HP of all allies. The healing amount will depend on the target. While Moon Rabbit Cookie is using her skill, she will be more resistant to interrupting effects.', 'Fummoon in the sky, and in ma tummy!', 'Fresh rice harvested from the happy soils of the Cookie World was used for baking the happy Moon Rabbit Cookie. This Cookie''s chubby cheeks are always filled with sweet rice cakes. And while some may think it''s cute, her craving for more rice cakes might be one of the strongest forces of the Universe. That craving can even become so strong that she might turn into a giant Rice Cake Bunny, and—oh boy!—you''d better keep your distance because she is going to wreak SWEET HAVOC. A group of particularly brave Cookies once tried to keep the giant Rice Cake Bunny in check by grabbing each other''s hands and building a circle around her. Ever since, the Cookies have kept a tradition of holding hands and going around in circles under the full moon.', 'Independent, Intuitive', 'Cristina Pucelli'),
('Raspberry Cookie', 'Charge', 'Front', 'Epic', 'raspberry-cookie.png', '2021-09-02', ARRAY['steel']::text[], ARRAY['almond', 'raspberry', 'chocolate']::text[], 'Raspberry Reprise|Cooldown = 11', '11', 'Raspberry Cookie briefly retreats to assume the En-Garde Stance. In this state, she gains an HP Shield as well as increased DMG Resist. Raspberry Cookie will additionally become immune to incapacitating effects, and will use Raspberry Reprise once more if she becomes affected by such effect. After this, she will charge at the closest enemy (targets Cookies first) and unleash her Raspberry Reprise at them, briefly reducing the target''s DEF and ATK with the final hit.', 'Fear the scarlet crest!', 'Amidst the generous raspberry fields illuminated by the Hollyberry Kingdom''s hot sun, proudly stands the grand Chateau Raspberry. In this place of history and culture, Raspberry Cookie was born and raised. Just like her great ancestors, she began fencing even before she learned the intricacies of aristocratic etiquette and rhetoric. Raspberry Cookie has been molded to become the heir and defender of the noble House Raspberry, sworn to protect its legacy. With her sword in hand, elegantly glazed hair fluttering in the summer breeze, and the proud House Raspberry banners behind her back, Raspberry Cookie is about to claim another victory from the clasp of fate.', 'Brave, Sharp-eyed', 'Christina Kirkman'),
('Parfait Cookie', 'Support', 'Rear', 'Epic', 'parfait-cookie.png', '2021-08-17', '{}'::text[], ARRAY['chocolate', 'almond']::text[], 'Paru-Paru-Parfait!★|Cooldown=17', '17', 'Grabs the microphone and belts her heart out. Touched by the earnest and sincere song, all allies will recover some HP and receive a buff that increases DEF and resistance to debuffs. While Parfait Cookie is using her skill, she will briefly become resistant to interrupting effects.', 'Pretty toppings, sweet and lovely! I''m Parfait Cookie, and don''t you forget it!', 'In a time when there''s never a day without a new hot celebrity idol, this singer-songwriter Cookie desperately tries to stick out with sweet toppings in vivid colors! Parfait Cookie''s distinct style involves layers of chocolate and candy, topped with dripping syrup. Despite still being a rookie, this Cookie already has dozens of self-written songs. Parfait Cookie''s melodies may be just as creative and unique as her colorful mixture of toppings, but her lyrics are always as pure and honest as vanilla ice cream. "It doesn''t matter if the audition goes bad, if no one recognizes me, or even if my toppings melt in the summer rain! I keep playing my guitar and sing about the truth in my heart."', 'Musical, Thorough', 'Amanda Lee (Credited as: AmaLee)'),
('Sorbet Shark Cookie', 'Ambush', 'Middle', 'Epic', 'sorbet-shark-cookie.png', '2021-08-03', ARRAY['water']::text[], ARRAY['chocolate', 'almond', 'raspberry']::text[], 'Shark Splash|Cooldown=13', '13', 'The Cookie ambushes the frontmost enemies in shark form, dealing area damage. Deals additional damage to the two enemies (targets Cookies first) with the highest Max HP within the skill''s area of effect. For enemies that are Cookies, the additional attack will be dealt as true damage relative to the enemies'' Max HP and cannot exceed 300,000. For other enemies, the additional damage will be regular damage.', '0Ooo0oo0o!', 'Once upon a time, there was a shark that lived in the deep blue sea. This curious swimmer often popped up to the surface to watch the pirates party on their ships. The shark yearned to join the Cookies for these parties, but they always ran away. Saddened, the shark disappeared into the sea for ages. Until suddenly... Sorbet Shark Cookie burst forth from the depths! This Cookie is, frankly, not the fastest runner, can only make bubbly noises instead of words, and gets soggy in the water just like everyone else. But even so, Sorbet Shark Cookie is always wearing a bright smile! After all, the world above the sea is vast and there''s so many things to see!', 'Heat-proof, Underwater', 'Arianna Ratner'),
('Squid Ink Cookie', 'Magic', 'Middle', 'Epic', 'squid-ink-cookie.png', '2021-08-03', ARRAY['water']::text[], ARRAY['raspberry', 'chocolate']::text[], 'Ink Tentacle Slap|Cooldown=16', '16', 'Where did Squid Ink Cookie go? And what is this giant squid doing here?! The monster is about to make anyone flat as a Cookie with a series of rapid slaps dealing area damage.', 'Not me...', 'Squid Ink Cookie came out of the oven not even a little bit crispy. Maybe that''s because of all the viscous ink inside! The Cookie was found floating along the seashore, all weak and confused. There is a theory that this Cookie is the legendary treasure-eating sea monster that attacked treasure ships, hungry for more gold. But Squid Ink Cookie can''t remember anything of that and spends all the time oozing blackish inky tears.', 'Heat-proof, Underwater', 'Courtney Lin'),
('Lilac Cookie', 'Support', 'Middle', 'Epic', 'lilac-cookie.png', '2021-07-15', ARRAY['grass']::text[], ARRAY['caramel', 'chocolate']::text[], 'Chakram Throw|Cooldown=13|Description=Lilac Cookie throws his chakrams in several rounds over a period of time. Friendly units are impressed by the graceful movements, and gain increased regular attack DMG proportional to their ATK SPD boost rate.', '13|Description=Lilac Cookie throws his chakrams in several rounds over a period of time. Friendly units are impressed by the graceful movements, and gain increased regular attack DMG proportional to their ATK SPD boost rate.', 'Lilac Cookie throws his chakrams in several rounds over a period of time. Friendly units are impressed by the graceful movements, and gain increased regular attack DMG proportional to their ATK SPD boost rate.', 'Those who sense my scent... Never leave alive.', 'Lilac petals are known as one of the core ingredients of the love potion. Finely sliced fragments of these petals were sprinkled into the dough and baked under the scorching desert sun. Lilac Cookie treads behind the veil of darkness only to appear with a gust of petals, mere moments before his unsuspecting foes take their final breath. Luring his targets with an irresistible fragrance, Lilac Cookie swiftly sends them to their end with his razor-sharp chakrams, leaving neither footprints nor a sound. The only remnants of his presence are but a few purple petals on the ground... and the lingering, yet soothing scent of lilac in the air.', NULL, 'Behzad Dabu'),
('Mango Cookie', 'Magic', 'Middle', 'Epic', 'mango-cookie.png', '2021-06-22', ARRAY['water']::text[], ARRAY['chocolate', 'applejelly', 'raspberry']::text[], 'Mango Juice Wave|Cooldown=15', '15', 'Sends forward a wave of tropical mango juice, inflicting damage to enemies. The fresh, sweet waves also increase the allies'' ATK for a short time. While Mango Cookie is using his skill, he will briefly become resistant to interrupting effects.', '1=Any Cookie would fall in love with local views!', 'The sun glistens above the serene palm trees of the Tropical Soda Archipelago. Once you arrive, Mango Cookie will give you a cheerful, hearty welcome making you feel right at home! With ripe mangoes mixed straight into the dough, Mango Cookie is pure-spirited and tenderhearted. Whether it''s spending time along the emerald coasts or exploring the islands with his canoe, Mango Cookie makes sure to enjoy life to the fullest. When the sun reaches its peak, sometimes he''ll hang up his hammock underneath the shade of the palm trees and take a relaxing nap. When Cookies visit the archipelago, Mango Cookie can''t help becoming a hyper chatterbox. Mangoes will ripen by the time he runs out of stories to tell!', 'Heat-proof, Musical', 'Christian Banas'),
('Red Velvet Cookie', 'Charge', 'Front', 'Epic', 'red-velvet-cookie.png', '2021-05-28', ARRAY['darkness']::text[], ARRAY['almond', 'chocolate']::text[], 'Crimson Hand|Cooldown = 15', '15', 'Face the might of the Cakes! The Cookie grasps the rearmost enemy, brings it in front of the Cookie squad, dealing great damage and stunning them for a short time. Cannot be interrupted.', 'TO BATTLE!', '"OBEY ME, MY BEASTS!" Red Velvet Cookie''s order, like a thunderbolt, rolls over the battlefield. "FALL IN!" And the horde of snarling Cake Monsters obediently assumes a dreadful battle formation. The crimson general personally leads his legion into battle, sowing fear with his clenched cake fist and his black eye gleaming with the dark fire of battle fervor. The battle-hardened warrior will see his mission to its end with precision and relentlessness. "UNLEASH CHAOS, MY BEASTS!" he roars as the battle begins. Adding silently: "But please, come back alive..."', 'Intuitive, Serene', 'Max Mittelman'),
('Pastry Cookie', 'Ranged', 'Rear', 'Epic', 'pastry-cookie.png', '2021-05-13', ARRAY['wind']::text[], ARRAY['raspberry', 'caramel']::text[], 'Battle Prayer', '13', 'Injustice shall be purged! After Pastry Cookie uses her skill, her regular attacks become stronger, and she will fire Lightbringer Bolts at up to two enemies, dealing damage. The bolts will later ricochet, dealing additional damage. Pastry Cookie will gain the Battle Prayer buff, increasing the number of targets according to her ATK SPD boost rate. She will also increase her ATK SPD and allied Wind-type Cookies'' CRIT%.', 'For the Order!', 'In the name of the Dough, the Oven, and the Witches, I shall fulfill my sacred duty!" Pastry Cookie left her name and her past behind on the day of her Sacred Brining when she was rebaked as a devoted sister of the St. Pastry Order. "... like a rolling pin flattening the many layers of pastry dough into uniformity, hardships and suffering produce the endurance to conquer the temptations of our crumbly bodies and souls." Now, looking from under the golden phyllo veil, these eyes see nothing else but a turbulent world to be rebuilt in the Order''s image. Wielding the Fork of Judgment, her consecrated crossbow, Pastry Cookie has set on her next mission to investigate a tainted shrine. And you would be wise not to stand in her way: the cruel cold metal hungers to deliver judgment.', 'Handy, Venturous', 'Colleen O''Shaughnessey'),
('Fig Cookie', 'Support', 'Middle', 'Epic', 'fig-cookie.png', '2021-05-13', ARRAY['grass']::text[], ARRAY['chocolate']::text[], 'Jelly Horn|Cooldown=15|Description=The sound of Fig Cookie''s Jelly Horn summons a flock of angered Fig Birds that swarm at the enemies, dealing damage. Surprised by this sudden attack, the enemies suffer from reduced ATK.', '15|Description=The sound of Fig Cookie''s Jelly Horn summons a flock of angered Fig Birds that swarm at the enemies, dealing damage. Surprised by this sudden attack, the enemies suffer from reduced ATK.', 'The sound of Fig Cookie''s Jelly Horn summons a flock of angered Fig Birds that swarm at the enemies, dealing damage. Surprised by this sudden attack, the enemies suffer from reduced ATK.', 'Let''s prance! An'' jump! An'' dance!', 'If you ever go for a forest picnic on a bright sunny day when the fragrant wind caresses your cheeks, the curious Fig Cookie may shyly appear from behind the leaves! This Cookie is known to have dwelled in verdant forests of light and honey for a long, long time. Year after year, the forest awakens at the cheerful sound of Fig Cookie''s Jelly Horn, and the brightest of flowers become more colorful and lively than ever. When Fig Cookie shares tales as old as the forest itself, animal friends gather around and listen intently. Prancing about to and fro, the Cookie sometimes ventures to the very edge of the forest to play and run with other Cookies.', 'Intuitive, Friendly', 'Giselle Fernandez'),
('Strawberry Crepe Cookie', 'Defense', 'Front', 'Epic', 'strawberry-crepe-cookie.png', '2021-04-22', '{}'::text[], ARRAY['almond', 'chocolate']::text[], 'Crepe Thrust|Cooldown = 15', '15', 'Uses the giant crepe arms to cause area damage. Reduces DMG received by two allies (targets Cookies first) with the lowest .', 'Cookies are too weak. BORING!', 'Sweet strawberry cream, crispy waffles, and chubby fresh strawberries—is there a cuter combination? Meet Strawberry Crepe Cookie with an unyielding sparkle of curiosity in their eyes. And this curiosity is a force to be reckoned with: Strawberry Crepe Cookie will stop at nothing to find an answer to every question! Having grown up with Wafflebots, this Cookie preferred tinkering with robotic parts to playing with toys. This little genius''s cute waffle headset is a tiny engineering marvel on its own. But don''t touch it! Or you risk witnessing a change from the cute Strawberry Crepe Cookie to the furious one.', 'Handy, Independent', 'Valeria Rodriguez'),
('Black Raisin Cookie', 'Ambush', 'Middle', 'Epic', 'black-raisin-cookie.png', '2021-04-08', ARRAY['darkness']::text[], ARRAY['chocolate', 'applejelly', 'raspberry']::text[], 'Shadow Watcher|Cooldown = 14', '14', 'No one can hide from the keen Black Raisin Eye! The Cookie vanishes into the shadows, appears amidst the enemy ranks (targets Cookies first), and strikes several times, dealing substantial area damage.', 'INTRUDER, stop right there!', 'Harsh wind, crooked trees, streets ravaged by the war... Who is it there, hiding among the shadows? Black Raisin Cookie, the sole protector of the unfortunate remnants of a once-great Kingdom. Made of shriveled, wrinkly raisins, this Cookie has learned the value of survival no matter what. Even having lost one arm to the dangers of this rough barren, this Cookie keeps hunting for scarce food to feed those who put their trust in her. Despite all the hardships, Black Raisin Cookie doesn''t lose the warmth of a Cookie heart: everyone deserves help, even a sorry one-legged crow. A new day is breaking, and another challenge is here. But Black Raisin Cookie will be there for the villagers, watching over them from the dark.', 'Agile, Tenacious', 'Tiana Camacho'),
('Almond Cookie', 'Support', 'Middle', 'Epic', 'almond-cookie.png', '2021-03-17', ARRAY['earth']::text[], ARRAY['chocolate', 'almond']::text[], 'Almond Handcuffs|Cooldown = 15', '15', 'Uses magical handcuffs to apprehend the enemy with the lowest max HP (targets Cookies first), dealing damage and applying the Damage Link debuff, which disperses a portion of damage the apprehended enemy receives between up to five linked enemies (cannot be applied to summoned creatures). Cannot be interrupted.', 'Let''s start from the beginning.', 'Pristine coat. Perfect shirt. Combed hair. He always starts his day fresh, prim, and proper. But it never lasts long... After being dispatched to spells gone awry from alley to alley, it looks as if Almond Cookie has been on the job for days on end without a single break. If it isn''t an enchanted grimoire moving on its own, it''s some magical cauldron spewing Jellies without pause. Despite the chaos on every scene, the veteran detective solves each case by the book with pinpoint precision. The almonds in his dough give him a hardy, rough and tough crisp that can withstand just about anything thrown at him, but he''s overworked to the point that his dough no longer contains the rich scent of almonds. "Can''t even get a coffee break," he sighs as another magical mishap needs his attention. With his coat fluttering in the wind, Almond Cookie looks upon his city and vows to keep going at it until he can finally relax with a decent coffee.', 'Analytical, Sharp-eyed', 'Ray Chase'),
('Cream Puff Cookie', 'Support', 'Middle', 'Epic', 'cream-puff-cookie.png', '2021-03-05', ARRAY['light']::text[], ARRAY['applejelly', 'peanut', 'chocolate']::text[], 'Jellius Extremus!|Cooldown = 16', '16', 'Conjures a tornado of Jellies over a large area, causing area damage and restoring the party''s HP. The spell cannot cause CRIT DMG, but instead, there is a chance to conjure it with great success depending on the CRIT%. Cast with great success, the spell will inflict greater DMG and heal a greater amount of HP. While Cream Puff Cookie is using her skill, she will briefly become resistant to interrupting effects.', 'I''m a real wizard now!', 'The sweet Cream Puff Cookie makes you feel delighted just by looking at her. Made of soft and delicate cream puff, this Cookie is as fragile as can be. Something always makes you worry about Cream Puff Cookie, but it''s certain that great power sleeps within her. Once she used to study magic on her own, but now she is a graduate of a prestigious Magic Academy! Will Cream Puff Cookie be able to become a famous wizard? Let''s find out!', 'Curious, Thorough', 'Cassandra Lee Morris'),
('Latte Cookie', 'Magic', 'Middle', 'Epic', 'latte-cookie.png', '2021-03-05', ARRAY['earth']::text[], ARRAY['chocolate', 'raspberry']::text[], 'Care for a Latte?|Cooldown = 15', '15', 'Conjures a Latte Glyph attracting enemies to its center, dealing damage, and silencing them. The Glyph remains on the ground, dealing periodic damage and even greater damage to enemies in its center.', 'Something on your mind? I can lend you an ear!', 'Coffee or milk... that is the question. Why not both? Latte Cookie''s dough was formed with coffee most bitter and acrid, balanced with the creamiest and smoothest blend of milk. With her etched staff in hand, she gracefully draws beautifully patterned Latte Glyphs in the air while daydreaming. But watch out! By chance, one of these Glyphs could be a powerful sigil for a grand spell! During her years as a student, she spearheaded research on the development of Coffee Magic with a rather eccentric aficionado of coffee. Thanks to her efforts, Latte Cookie was granted a professorship at the Parfaedia Magic Institute. You''d think that a professor would be more punctual, especially with their own lectures. But not Latte Cookie! She''s more invested in savoring a warm latte before class. Though far from achieving the Professor of the Year Reward, she knows a thing or two about inspiring her students. With her genuine compliments and encouraging smile, Latte Cookie is already the favorite professor of many.', 'Analytical, Venturous', 'Vivian Lamolli'),
('Kumiho Cookie', 'Charge', 'Front', 'Epic', 'kumiho-cookie.png', '2021-02-05', ARRAY['wind']::text[], ARRAY['almond', 'chocolate']::text[], 'Somersault|Cooldown = 14', '14', 'Transforms into a Cookie and causes area damage and charming nearby enemies, while charming them and reducing their DEF. Afterward, fires a powerful Fox Spirit Flame up to 5 enemies near Kumiho Cookie and turns back into marshmallow fox.', 'What''s your name, cutie pie?', 'A fox-shaped marshmallow wished to become a Cookie so much that it mastered a spell to shapeshift into a Cookie by surviving only on flour and butter for 999 days. As a result, she can now disguise herself as a seductive and attractive Cookie. Anyone who catches even a glimpse of her will instantly fall in love. Perhaps she''s dazzling them with her nine tails.', 'Agile, Intuitive', 'Kimlinh Tran'),
('Rye Cookie', 'Ranged', 'Rear', 'Epic', 'rye-cookie.png', '2021-01-21', ARRAY['fire']::text[], ARRAY['raspberry']::text[], 'Final Showdown|Cooldown = 15', '15', 'Shoot first if you don''t wanna be shot! The Cookie aims both pistols at the enemy with the lowest Max HP (targets Cookies first) and shoots a round, dealing a great amount of damage several times. The Cookie''s focus is so high, the Cookie will become resistant to interrupting effects. The Cookie''s ATK SPD is increased greatly for the whole Showdown duration.', 'I bite hard and never let go.', 'On the sunset of a hard day''s work, the saloon door bangs open. "As usual, boss!" she yells. Yup, it''s Rye Cookie again, so better get her order straight. She''s a bounty hunter in these here parts, sporting a shiny badge and all that. The Wild Gun, they call''er. Maybe she''s here on a job, or maybe she''s just moseying through town. Last time, there been rumors of a brazen heist: someone wiped the wheat silo clean as a whistle, not a single grain left. Wonder who coulda done that? Anyway, better to be careful ''round that one. It''s safer to be nice and quiet ''round her, lest ya wanna feel the full barrel from her wholegrain-caliber.', 'Agile, Handy', 'Amber Lee Connors'),
('Espresso Cookie', 'Magic', 'Middle', 'Epic', 'espresso-cookie.png', '2021-01-21', ARRAY['earth']::text[], ARRAY['raspberry']::text[], 'Grinding|Cooldown = 15', '15', 'Precise and even grinding is key for a magically delicious cup of coffee! A giant whirlwind inflicts periodic area damage to enemies and pulls them from afar to its center even if they are resistant to interrupts. The final burst of damage may interrupts skills. While Espresso Cookie is using his skill, he will briefly become resistant to interrupting effects.', 'Yes, I''m here. What now?', 'Precise temperature, precise quantity of coffee beans, precise roasting time! Everything must be in a precise—impeccably precise—order for the plan to work. Always busy, always on the go—this is the lifestyle of Espresso Cookie. Despite being frequently mistaken for a black mage—yes, sometimes things burn, and smoke—Espresso Cookie can''t afford to waste a second on meaningless explanations. Night after night, this pioneer of magic works on perfecting his grind and brew. "Isn''t that too much coffee?" one might wonder. Well, at least there''s always the delightful coffee fragrance in the air!', 'Analytical, Serene', 'Zach Aguilar'),
('Madeleine Cookie', 'Defense', 'Front', 'Epic', 'madeleine-cookie.png', '2021-01-21', ARRAY['light']::text[], ARRAY['almond', 'raspberry']::text[], 'Commander''s Honor|Cooldown = 10', '10', 'Calls upon the Celestial Light that allows performing ranged area attacks instead of regular attacks. While under the Celestial Light, Madeleine Cookie receives a buff making him immune to debuffs.', 'The Divine smiles upon me!', 'An offspring of a noble Cookie family from a peaceful republic across the ocean, Madeleine Cookie, armed with his family''s influence and shiny new armor, is already the Commander of a knight order. On the day of his Commander''s Oathtaking, Madeleine Cookie dedicated himself to the Divine and was granted the Sword and Shield of Radiant Light, which he prizes the most among his numerous possessions. The glorious Knight Commander''s usual duties included trotting around the city on his snow-white sugar horse or letting his heavy cape flutter dramatically on the wind during his sparring sessions. Not too long ago, the heroic Madeleine Cookie set on a quest in search of the legendary Jam of Souls capable of granting Cookies eternal life! Will the noble paladin''s first campaign bear fruit?', 'Brave, Tenacious', 'Yong Yea'),
('Licorice Cookie', 'Magic', 'Middle', 'Epic', 'licorice-cookie.png', '2021-01-21', ARRAY['darkness', 'chaos', 'poison']::text[], ARRAY['chocolate', 'raspberry']::text[], 'Licorice Servants|Cooldown = 14', '14', 'Summons a powerful Black Lightning and Licorice Servants. The potent spell briefly increases the party''s Defense. Licorice Servants are resistant to certain movement interrupting effects. If the skill is used before the summoned Licorice Servants disappear, new additional Licorice Servants will be summoned. While Licorice Cookie is using his skill, he will briefly become resistant to interrupting effects.', 'It''s unwise to get in my way... Hehe!', 'With a great portion of the blackest licorice extract in his dough and a grim-looking scythe, this Cookie is up to no good. From a young age, Licorice Cookie dreamed of becoming a wizard but never received the recognition he so rightfully deserved. Eventually, he turned to the forbidden arts of Black Magic. With time, Licorice Cookie assembled a small army of Chewy Licorice Servants raised to do his bidding. On his dark path, he met . The might of the sorceress astonished Licorice Cookie, and it didn''t take long before he swore his allegiance. Now, the Cookie is working flat out to earn his new mistress''s favor. And it seems like Dark Enchantress Cookie is not easily pleased, as Licorice Cookie''s diary filled with everyday rants and complaints could fill up a library.', 'Attentive, Curious', 'Cameron Bowen'),
('Poison Mushroom Cookie', 'Bomber', 'Middle', 'Epic', 'poison-mushroom-cookie.png', '2021-01-21', ARRAY['poison', 'chaos']::text[], ARRAY['raspberry', 'applejelly']::text[], 'Poison Cloud|Cooldown=15', '15', 'Plants mushrooms that release purple poison clouds around themselves. Poisoned enemies become disoriented and suffer from a debuff reducing Healing, but Poison Mushroom Cookie claims that was never the intention... Poison clouds deal extra Poison DMG to monsters and bosses.', 'Oooh... New friend... Want a shroomy?', 'Some mushrooms are good for you, and some are not. Take the Purple Cap Mushroom, for example. Looks so chunky and yummy! That is why that hungry Cookie ate it. Why yes, that was Poison Mushroom Cookie. Always peaceful, always daydreaming. Poison Mushroom Cookie would be mistaken for an actual mushroom in the past, but they were never angry, never at all! Poison Mushroom Cookie greeted and hugged these mistaken Cookies like dear old friends, that''s right! They offered every one of them a mushroom of their own—so sweet, so colorful. Just one bite, just one... After all, such big friendly eyes mean no harm. No harm at all...', 'Serene, Independent', 'A.J. Beckles'),
('Milk Cookie', 'Defense', 'Front', 'Epic', 'milk-cookie.png', '2021-01-21', '{}'::text[], ARRAY['almond', 'chocolate', 'peanut']::text[], 'Noble Sacrifice|Cooldown = 12', '12', 'Stands at the front line, causing area damage, and taunts the enemies, forcing them to attack himself. While the skill is active, Milk Cookie''s Divine Milk Shield decreases incoming damage. While Milk Cookie is using his skill, he will briefly become resistant to interrupting effects.', 'Darkness, begone!', 'Everything the light touches, let there be peace! Milk Cookie made a divine oath to protect the world from all evil. When raising up the Healing Milk Mace, a splendid glow soars to the skies and bathes the world in light. The forces of evil flee in terror at the sight of the Divine Milk Shield. Milk Cookie has faced many foes, and yet his resolve remains unsullied by corruption and despair. Even on the brink of exhaustion, this selfless and noble protector will cast a blessing of protection for other Cookies first.', 'Brawny, Serene', 'Daman Mills'),
('Purple Yam Cookie', 'Charge', 'Front', 'Epic', 'purple-yam-cookie.png', '2021-01-21', ARRAY['grass']::text[], ARRAY['almond', 'raspberry']::text[], 'Purple Tornado|Cooldown=12', '12', 'Ravages the battlefield in a deadly Purple Tornado, causing substantial periodic area damage. While Purple Yam Cookie is using his skill, he will briefly become resistant to interrupting effects.', 'Fiery WRATH!|', 'Purple Yam Cookie was baked in extreme temperatures again and again until the heat finally got to his head. Ever since, Purple Yam Cookie has been in an angered state (to say the least!) that''s why we advise being extremely cautious around him. When the wrath kicks in, this Cookie begins to crush and smash the surroundings in a dangerous tornado of rage. And as if that wasn''t enough, Purple Yam Cookie is always eager to fight someone! The Cookie claims that no one has suffered in the "flames of hell" more than him, but... it seem like no one has had a chance to tell him that other Cookies went through the Witch''s oven too...', 'Tenacious, Brawny', 'Sean Chiplock'),
('Pomegranate Cookie', 'Support', 'Middle', 'Epic', 'pomegranate-cookie.png', '2021-01-21', ARRAY['chaos']::text[], ARRAY['chocolate', 'raspberry']::text[], 'Pomegranate Magic|Cooldown=15', '15', 'Even dark spells can become a formidable ally! The Cookie''s crimson magic applies a buff restoring some HP over time for the whole squad and increases their .', 'For my {{ch|de|Master', 'Dressed in her scarlet ceremonial attire with glittering pomegranate drop decorations, Pomegranate Cookie was raised in the lands of powerful sorcerers as a young priestess to the Sacred Pomegranate Tree. But when she was foretold to follow a great darkness, she started to doubt her upbringing. When an unstoppable dark force overran her homeland, Pomegranate Cookie already knew she had met her destiny, and gladly joined her', 'Analytical, Thorough', 'Victoria Grace'),
('Chili Pepper Cookie', 'Ambush', 'Middle', 'Epic', 'chili-pepper-cookie.png', '2021-01-21', ARRAY['fire']::text[], ARRAY['applejelly']::text[], 'Cheap Shot|Cooldown = 12', '12', 'Chili Pepper Cookie increases her CRIT DMG based on her CRIT%. Sneaks behind the enemy, causing area damage to the rearmost line with 4 strikes. The final strike always deals critical damage.', 'Lost your Coins?', 'Chili Pepper Cookie''s dough contained much more chili pepper than allowed by the law. This is probably why she doesn''t care much about rules at all! Chili Pepper Cookie is a notorious treasure hunter. She never misses a chance to snatch everything valuable she can get her hands on, leaving only chaos and havoc behind. The Cookies know better than to cross her path, and so should you. Good news: you can easily identify this path by a trail of fiery red chili sauce...', 'Agile, Curious', 'Kimberly Brooks'),
('Sparkling Cookie', 'Healing', 'Rear', 'Epic', 'sparkling-cookie.png', '2021-01-21', ARRAY['light']::text[], ARRAY['chocolate']::text[], 'Sparkling Cocktail|Cooldown = 13', '13', 'Throws refreshing healing cocktails at two allies with the lowest HP. The cocktail''s divine aroma raises the whole squad''s morale, increasing their Critical Strike Chance.', 'Have a glass! It''s on me.', 'This is the day! You have received an invitation to the famous Sparkling Party. Sparkling Cookie greets you personally with a dazzling smile and offers a glass of Sparkling Juice. All the guests are fascinated with his impeccable manners and looks: his boyish rolled up sleeves and bouncy bubble hair. It is going to be the best holiday party ever!', 'Lucky, Handy', 'Xander Mobus'),
('Dark Choco Cookie', 'Charge', 'Front', 'Epic', 'dark-choco-cookie.png', '2021-01-21', ARRAY['darkness']::text[], ARRAY['chocolate', 'almond', 'peanut']::text[], 'Sword of Darkness|Cooldown = 13', '13', 'Strikes the ground with his great sword, inflicting chain lightning upon the enemies. Those unfortunate, affected by this dark lightning suffer from great damage and lowered Defense.', 'When I woke up, darkness was around me.', 'Long ago, this Cookie stepped into the world of Darkness to become a hero, but fate had a different plan: Dark Choco Cookie was unfortunate enough to happen upon the forbidden Strawberry Jam Sword. As soon as the would-be hero grasped the weapon, the dark power of the magic sword took over. From that moment on, Dark Choco Cookie''s life changed forever. Now, dark clouds and thunderstorms follow this ill-fated Cookie, feared by all. It is said that Dark Choco Cookie is still fighting against the magic sword''s control.', 'Tenacious, Brawny', 'Isaac Robinson-Smith'),
('Herb Cookie', 'Healing', 'Rear', 'Epic', 'herb-cookie.png', '2021-01-21', '{}'::text[], ARRAY['chocolate', 'almond']::text[], 'Sunny Garden|Cooldown = 17', '17', 'Turns the ground into a wonderful little garden, removing all debuffs and restoring some HP for the whole party. Standing near sprouts also restores some HP over time.', 'Hello there! Welcome to my garden.', 'Warm like the sunshine and fresh like the scent of rain, Herb Cookie will ease your mind when you''re feeling down. Made of fresh green herbs, this Cookie may not be to everyone''s taste. On rainy days, Herb Cookie loves to listen to the sound of falling raindrops under his trusty leaf umbrella. On warm days, he enjoys the sunshine together with his favorite plants. This Cookie treats all living things and every moment as precious. He believes that the little things that make you laugh or cry are to be cherished, just like a ray of sunshine after the rain.', 'Lucky, Friendly', 'Khoi Dao'),
('Mint Choco Cookie', 'Support', 'Rear', 'Epic', 'mint-choco-cookie.png', '2021-01-21', ARRAY['wind']::text[], ARRAY['chocolate', 'almond']::text[], 'Battlefield Symphony|Cooldown = 16', '16', 'Mint Choco Cookie plays a sublime melody that increases the team''s ATK SPD, applies the Warm Breeze buff, and grants HP Shield to Wind-type Cookies. Upon playing a melodic tune, he inflicts damage on enemies with his Mint Gust and heals allies'' HP equal to a portion of the damage inflicted. Once Mint Choco Cookie gains enough Tailwind stacks, he will heal his allies once more with a refreshing performance.', 'What piece shall I play for you?', 'His exquisite performance and dashing looks make him a favorite among the Cookies. His Mint Candy Violin gives off a sweet enchanting candy aroma while he plays. Though often called a genius, he refuses to let all this attention go to his head and never forgets his long years as a humble street performer.', 'Musical, Lucky', 'Zeno Robinson'),
('Werewolf Cookie', 'Charge', 'Front', 'Epic', 'werewolf-cookie.png', '2021-01-21', ARRAY['steel']::text[], ARRAY['almond', 'applejelly']::text[], 'Transformation|Cooldown = 11', '11', 'Takes his wolf form, causing area damage. In the wolf form, Werewolf Cookie has increased HP, becomes resistant to interrupting effects, and does more powerful double-strike regular attacks. Targets hit by double strikes may be stunned.', 'Don''t come near! I don''t want to hurt you...', 'Together with a great amount of pepper, a wolf hair had fallen into the cookie dough by accident. Now, whenever Werewolf Cookie feels scared or threatened, his wolf instinct kicks in to transform him into a feral beast. A long time ago, when a friend was in great peril, Werewolf Cookie managed to save them by transforming, at a cost. With his true nature revealed to the whole town, he was cast away out of fear and has been living alone in the forests since. With so much pain inside, this Cookie tastes bitter and salty (of tears). Don''t ask about his scar or try to get close, as he will only push you away...', 'Intuitive, Cold-proof', 'Desmond Chiam'),
('Tiger Lily Cookie', 'Ranged', 'Rear', 'Epic', 'tiger-lily-cookie.png', '2021-01-21', '{}'::text[], ARRAY['chocolate']::text[], 'Tiger Rider', '13|Description=Charges forward on the back of the Butter Tiger, causing damage to nearby enemies and stunning them. While the effect is active, the Cookie deals more damage with faster Regular Attacks.', 'Charges forward on the back of the Butter Tiger, causing damage to nearby enemies and stunning them. While the effect is active, the Cookie deals more damage with faster Regular Attacks.', 'Roarr! Protect... I will...', 'It is not known how Tiger Lily Cookie ended up in the jungle all by herself. Under the constant threat of encroaching enemies, her senses grew sharp. In contrast to her rough outward appearance, she is soft and delicate on the inside. Her only family is her trusty Butter Tiger, whom she cherishes more than anything in the world. Her great skill with the spear and excellent jumping abilities make her one tough Cookie to beat.', 'Intuitive, Sharp-eyed', 'Stephanie Sheh'),
('Vampire Cookie', 'Ambush', 'Rear', 'Epic', 'vampire-cookie.png', '2021-01-21', '{}'::text[], ARRAY['raspberry', 'chocolate']::text[], 'Vampirism|Cooldown = 13', '13', 'Turns into a bat and attacks the rearmost enemy, drinking their blood and restoring some HP depending on the amount of damage caused. Restores some HP with each regular attack.', 'Why so serious? Let me pour you some juice.', 'The Witch, busy baking several Cookies at once, had forgotten to use her favorite high-quality grapes. Instead, she stored them in oak barrels and let age for a long, long time. And with that special grape juice, she made Vampire Cookie. Naturally, it was difficult for Vampire Cookie to wake up at first—after all, his dough contained more than 10% of strong grape juice! Unlike the other Cookies, Vampire Cookie prefers to do nothing but enjoy life. He wasn''t even bothered by the heat of the oven and only escaped because his sister dragged him outside. With his pale face and smug posture, he likes to relax with a glass of grape juice and ponder the meaning of life.', 'Serene, Independent', 'Jason Kaye'),
('Snow Sugar Cookie', 'Magic', 'Middle', 'Epic', 'snow-sugar-cookie.png', '2021-01-21', ARRAY['ice']::text[], ARRAY['chocolate', 'raspberry']::text[], 'Blizzard|Cooldown = 14', '14', 'Waves the Snow Sugar Wand to summon the Snow King that causes a snowstorm, dealing periodic area damage, and applying the Frost debuff with a certain chance upon each hit. Enemies suffer lowered ATK SPD. Snow King is resistant to certain action and movement-impairing effects. While Snow Sugar Cookie is using their skill, they will briefly become resistant to interrupting effects.', 'Hi! Wanna have a snowball fight?', 'Made of snow, sugar, ice, and an unknown secret ingredient, this Cookie was once very lonely, wandering through a vast snowy field. Then one day, Snow Sugar Cookie found a magic wand that could summon snow creatures and wouldn''t melt even in the oven. The Cookie quickly learned to summon friends like the Sea Snow Cone and the Great Snow King and was never lonely again.', 'Cold-proof, Thorough', 'Analesa Fisher'),
('Povidone-Iodine Cookie', 'Bomber', 'Middle', 'Super Epic', 'povidone-iodine-cookie.png', '2026-06-04', ARRAY['steel']::text[], ARRAY['chocolate', 'raspberry']::text[], 'Ethically Ambiguous Experiments', '7', 'Sprays Red Antiseptic forward; if target is a Cookie, applies Red Antiseptic debuff. Deals damage, then applies Healing debuff proportional to Max HP and reducing damage dealt by the target. Additionally, applies Healing Prevention to the target with the lowest current HP. Attacks with saw, dealing DMG; if target is a Cookie, applies Excessive Vampiric Bite (Excessive Vampiric Bite and Vampiric Bite applied are not affected by Debuff Resist). Finally, uses Saw Strike to deal damage and inflict Vampiric Bite. When using skill, grants HP Shield for self, heals all allies, and applies Experimental Prescription to allies (excluding self). At the start of battle, grants HP Shield, Debuff Immunity, and Enhanced Experimental Prescription to self. Periodically heals self, removes all removable debuffs, and becomes Immune to incapacitating effects while using skill.', 'Welp, it’s time to operate!', 'The cold air of the laboratory smells of chemicals and reverberates with sharp screams of unknown nature. At its center stands Povidone-lodine Cookie: her frenzied eyes affixed on a new specimen on her examination table. Known within the R&D as the Raging Scalpel, this Cookie will pursue any avenue-no matter how unethical-to unveil the anomalies'' secrets. Even treating injured colleagues may turn into a bizarre experiment-Cookies who have endured it and remained to tell the story share the same haunting memory: those eyes, those zealous eyes! And yet, they return. For when it comes to mending even the gravest wounds, Povidone-lodine Cookie''s expertise knows no rival!', 'Analytical, Curious', 'Kelly Ohanian'),
('Venom Dough Cookie', 'Bomber', 'Rear', 'Super Epic', 'venom-dough-cookie.png', '2026-01-01', ARRAY['poison', 'chaos']::text[], ARRAY['chocolate', 'raspberry', 'peanut']::text[], 'Mind Venom', '14', 'Venom Dough Cookie uses their psionic powers to create toxic matter in the air and send it towards the enemies, where it explodes. If an afflicted enemy doesn''t have an HP Shield, they will take additional damage and receive the Venom Distortion debuff. Venom Dough Cookie collects Venom Essence during battle, with additional Venom Essence if the enemies have been turned into Failed Creations. Venom Essence stacks up, and at a certain number of stacks, turns into a stack Venom Core. Venom Dough Cookie instantly gains a stack of Venom Core whenever an enemy Cookie is defeated or whenever Dark Enchantress Cookie uses Magic Overflow. Additionally, Venom Dough Cookie gains two stacks of Venom Core if Dark Enchantress Cookie is on the team. At maximum stacks, Venom Core is consumed to cast Venom Force at the enemy with the lowest current HP and apply Venom Barrier to themselves, which remains for a certain time. As long as Venom Barrier is active, Venom Dough Cookie cannot become a Failed Creation. At the beginning of the battle, Venom Dough Cookie gains Venom Aura. Venom Dough Cookie will gain Dragontongue Brand at given intervals. If Venom Dough Cookie enters the battle with Mold Dough Cookie and Pom-pom Dough Cookie, it will trigger the Dough Trio effect.', '… I merely execute my orders.', 'A Cookie has made the Laboratorium tremble in fear with their violet venom and invisible shockwaves... Wielding psionic powers to overwhelm their enemies, this Cookie is none other than the Seer of Twilight, Venom Dough Cookie. Born from Dark Enchantress Cookie''s meticulous design deep within the lab, they carried out her missions with chilling detachment-even in the face of death-and rose to become the spiritual leader of the Dough Trio. As others bowed to Dark Enchantress Cookie''s orders, Venom Dough Cookie''s venomous particles quivered in silent defiance. Trapped within an endless cycle of pain, they could not fathom when it all would end... When the other Dough Cookies cried out, their doughs crumbling in agony, Venom Dough Cookie''s eye gleamed with a forbidden thought: if we could bring down our creator... perhaps they could finally be freed from this exploitation and suffering.', 'Analytical, Sharp-eyed', 'Sena Bryer'),
('Doughael', 'Healing', 'Middle', 'Super Epic', 'doughael.png', '2025-08-27', '{}'::text[], ARRAY['peanut']::text[], 'Consecrated Vow|Cooldown = 15', '15', 'Heals allies for a certain period of time, and grants DMG Resist, Debuff Resist, and ATK buffs. Afterwards, Doughael''s faith shines, Healing allies, dealing damage to enemies, pushing them back, and inflicting Sacred Preachings. Upon using Their skill, Doughael removes debuffs from targets with Disciple of the Abyss. Lastly, Doughael applies Fervor and Blessings of Devotion, Healing targets whenever they take damage over a certain period of time, and granting them Immunity to incapacitating effects. At the start of battle, Doughael grants Disciple of the Abyss to the ally with the highest ATK (excluding Themselves), increasing the ally''s ATK and DMG Dampening. If this target is defeated, it will trigger Selfless Sacrifice, increasing Doughael''s ATK and DEF. The buff will be applied to the next ally with the highest ATK. If Doughael is defeated, Disciple of the Abyss will further increase the target''s ATK buff and speed up their Healing rate. Doughael''s Cooldown decreases proportionally to Their HP increase rate as of the start of the battle, and They are immune to incapacitating effects.', 'All dough shall become one.', 'There once lived a pilgrim who sought the meaning of Cookie life. When They found the answer—the truth that Cookies were baked to be eaten—at long last, the pilgrim rejoiced. "Only through becoming one can we reach salvation!" And so, this Cookie set out a mission to share Their epiphany with the whole world. Soon, They became the High Forkbearer of the St. Pastry Order. Having cast aside Their former name, Their very flavor, this Cookie took the name of Doughael. Doughael crossed the boundary between worlds, and, having witnessed a glimpse of the Complete Vision, returned carried on the wings of pure white to liberate Cookies from their sins. Through Doughael''s severance from the lights of the world, the revelation of the Almighty shines all the brighter upon Their pupils—one that dictates complete devotion to the providence''s messenger. And once all living souls are conjoined in the Whole Dough, it is finished.', 'Flying, Mysterious', 'John Patneaude'),
('Camellia Cookie', 'Charge', 'Front', 'Super Epic', 'camellia-cookie.png', '2024-11-20', ARRAY['grass']::text[], ARRAY['almond', 'raspberry', 'chocolate']::text[], 'Battle Scene Painting|Cooldown = 13|Initial = 2', '13|Initial = 2', 'Upon using the skill, Camellia Cookie will increase his own Debuff Resist and the team''s CRIT%. Then, he will charge at the enemies, brandishing his painting brush. With his final stroke, Camellia Cookie will deal greater damage and Stun all enemies affected by it. He will also remove all buffs from the two with the highest ATK. If Camellia Cookie .', 'I''ve quite the discerning eye.', 'When the camellia flag flutters in the wind, it signals the arrival of Camellia Cookie''s caravan, renowned for trading rare and expensive tea leaves across the continent! The master of this successful enterprise is none other than Camellia Cookie himself. While many assume his extensive background is the key to his success, those close to him know the real secret: his messenger pigeons. These feathered couriers play a crucial role in managing his complex system of trade routes, ensuring that Cookies far and wide can sip the finest brews of tea. Even when Cookies of great fortune seek him out at his Teahouse to win him over, he declines, claiming to be busy admiring paintings. Brushing aside rumors that his trade business is merely a means to gain information and knowledge, Camellia Cookie carefully archives messages brought by his pigeons, for no piece of information is too small—it will all become useful someday.', 'Lucky, Curious', 'Stephen Fu'),
('Elder Faerie Cookie', 'Defense', 'Front', 'Super Epic', 'elder-faerie-cookie.png', '2024-02-28', ARRAY['steel']::text[], ARRAY['chocolate', 'almond', 'peanut']::text[], 'Guardian''s Valor', '12', 'Elder Faerie Cookie strikes down with his sword containing Prism Energy to deal damage, taunt enemies, and purify debuffs on himself. , the energy in the sword causes an explosion, dealing more damage, applying Injury, and reducing the amount of Healing enemies receive. He shields his allies with an HP Shield proportional to his ally Cookies'' Max HP, and the shield capacity increases with more buffs applied on Elder Faerie Cookie. Elder Faerie Cookie grants a Prism Shard and applies a DMG Resist buff to himself, White Lily Cookie, and a Cookie with the highest ATK (or two Cookies with the highest ATK if White Lily Cookie is not in the team). If Elder Faerie Cookie has the Beascuit HP upgrade, he can apply Prism Shards to more allies. Using a Prism Shard charge will heal the target''s HP for a certain amount of time. Unlike other Cookies, White Lily Cookie will gain two Prism Shards. Elder Faerie''s DMG Resist will increase when affected by a debuff. While Elder Faerie Cookie is using his skill, he will briefly become resistant to interrupting effects .', 'I shall protect this world from evil.', 'Somewhere in Beast-Yeast, hidden behind a shimmering veil, stands the Faerie Kingdom—a kingdom that began with but one Cookie. Elder Faerie Cookie has walked this Earthbread for eons, standing at the very core of countless cycles of birth and destruction that have shaped this world. Only hushed whispers of his origins are passed down as legends. His sole purpose is to contain the ancient and malevolent forces that threaten to escape at any moment. His will and power are imbued within the seal—a vital source of life for the Silver Tree to grow. Little do Cookies know that the age of peace and prosperity they enjoy is owed to Elder Faerie Cookie''s tireless effort. But the stern monarch''s adamant will remains unbothered, for it has been ages since he embraced the stoic path of the Guardian of the Seal.', 'Flying, Nature-loving', 'Zeke Alton'),
('Crimson Coral Cookie', 'Defense', 'Front', 'Super Epic', 'crimson-coral-cookie.png', '2023-08-30', ARRAY['water']::text[], ARRAY['chocolate', 'raspberry']::text[], 'Somber Affection|Cooldown = 12|Initial = 2', '12|Initial = 2', 'Crimson Coral Cookie''s sisters will lend their powers to the crimson spear, piercing enemies and dealing damage. Afterwards, Crimson Coral Cookie will cast an HP Shield to the 2 allies with the highest ATK (excluding herself) equal to a portion of her Water-type Skill damage. If Crimson Coral Cookie is the only Cookie in the front line, she and her allies will gain the Coral Armor buff. Additionally, her Coral Armor''s size and weight will reduce the effect of Knockback and Flying. When Crimson Coral Cookie is using her skill, she is not affected by ATK SPD changes and will become resistant to interrupting effects.', 'Gem Mermaids live to protect the kingdom.', 'Hearken to me, Legion of Tearcrown! The echo of Crimson Coral Cookie''s stern voice rolls above the crashing waves, summoning a great host of seahorses, marlins, and whales to protect the treasured kingdom of the Gem Mermaids. Born with a crimson coral, this Cookie has vowed to protect her homewaters, and all denizens of the ocean, even the herself, bowed in respect. In every battle, Crimson Coral Cookie is at the forefront, bravely wielding her spear from the back of her trusty seahorse companion. The Gem Mermaid''s heart softens only when she is with her beloved sisters. Some even say they have seen a faint shadow of a smile on the face of Tearcrown''s most stalwart protector!', 'Underwater, Mysterious', 'Megan Hensley'),
('Shining Glitter Cookie', 'Magic', 'Middle', 'Super Epic', 'shining-glitter-cookie.png', '2023-07-05', ARRAY['electricity']::text[], ARRAY['raspberry', 'applejelly', 'chocolate']::text[], 'All Eyes on the Stage!|Cooldown = 12', '12', 'Shining Glitter Cookie begins singing the Glittering Song, dispelling all debuffs from herself, applying the Glittering Rock Spirit buff to her allies, and dealing damage to the enemies. Whenever the song lands a critical hit, it will partially ignore the target''s DMG Resist and Zap them. If Shining Glitter Cookie manages to deal a certain number of critical hits with the Glittering Song, she will provide a CRIT Resist buff for the entire team. While Shining Glitter Cookie is using her skill, she will briefly become resistant to interrupting effects.', 'Pop or rock, I''m gonna give it some shining glitter!', 'In the morning, she is in a music show on TV. In the afternoon, smiling at you from a signed poster in a café. In the evening, dancing on a giant neon billboard! Not a day goes by without seeing Shining Glitter Cookie! Her songs are guaranteed instant hits, her live performance are unrivaled. At the peak of her pop stardom, she''s ready to take on a new genre: ROCK! Turns out Shining Glitter Cookie was a fan of rock music all along. Haters will say there is no place for a fancy pop star in the world of rock, but that won''t stop Shining Glitter Cookie! Get ready, Earthbread: Shining Glitter Cookie''s Rock Spirit is about to dazzle you away!', 'Musical, Lucky', 'Grace Lu'),
('Capsaicin Cookie', 'Charge', 'Front', 'Super Epic', 'capsaicin-cookie.png', '2023-03-30', ARRAY['fire']::text[], ARRAY['raspberry', 'almond']::text[], 'Capsaicin Magma', '15', 'Capsaicin Cookie transforms with the surge of magma power. When he has transformed, his regular attacks will cause Lava Eruptions, inflicting Burn and Magma debuffs to enemies. While transformed, Capsaicin Cookie will briefly become resistant to interrupting effects. After his transformation, Capsaicin Cookie will enter Spice Overlord mode with all the intense magma power and deliver his final strike. If , he will become Immortal, dispelling his debuffs and cannot be for a certain period. The first cooldown of Capsaicin Cookie''s skill will be shortened, allowing for faster skill use.', 'Heard of the spice overlord? Yeah, that''s ME!', 'I''ll show you the true meaning of SPICE!!! What is this voice, rumbling more intensely than an erupting volcano?! It''s none other than Capsaicin Cookie! This Cookie is a product of a fiery mix of capsaicin, the essence of spice, and burning hot magma. Perhaps that''s why Capsaicin Cookie''s personality, behavior, and strength are all super explosive. It''s no surprise that he gained a reputation as the strongest Cookie as soon as he enrolled in Scovillia, a school for only the spiciest of Cookies. Despite his wild exterior, this Cookie has won the hearts of every Cookie around him with the burning sincerity buried deep in his magma heart. The name Spice Overlord and his now-melted shackles were once a reminder of his pained past, but fear not! Capsaicin Cookie will never lose himself as long as he''s able to face his own spice!', 'Brawny, Heat-proof', 'Adam Gold'),
('Stardust Cookie', 'Ambush', 'Middle', 'Super Epic', 'stardust-cookie.png', '2023-03-09', '{}'::text[], ARRAY['applejelly', 'chocolate']::text[], 'Wrath of the Stars|Cooldown = 13', '13', 'Stardust Cookie soars in the sky and marks the enemy with the highest ATK (targets Cookies first) with the Sign of the Stars. Then he will descend to deal area damage to the enemies, amplifying debuffs they receive. Targets will receive additional damage depending on the number of buffs they currently have. The Sign of the Stars prevents the target from gaining buffs, decreases their ATK and Healing, and increases the DMG received. If the skill delivers a critical hit, the target will fall Asleep. If the Sign of the Stars is dispelled, the target and the nearby enemies will receive damage. After casting his skill, Stardust Cookie will gain a DMG Resist buff himself. If the enemies are Asleep, Stardust Cookie summons meteors to attack them.', 'My voyage... goes on.', 'It is hard to say how long the lonesome speck of Cookie dough had been drifting in the vast emptiness of space before the radiance of nameless stars blessed it with the gift of life. Was it a mere coincidence...? For Stardust Cookie, the warmth of many suns was the heat of the oven, and the distant planets were his only companions in his light-speed journey across galaxies. Beckoned by shapeless, fleeting nebulae, guided by the whispering of the stars, Stardust Cookie headed to the City of Wizards to uncover the secret of his birth. Was he trying to find his long-lost purpose, or, on the contrary, escape his predetermined fate...? With a glint of a stray shooting star, this lonesome voyager crosses someone''s sky tonight, seeking a place to call home.', 'Flying, Mysterious', 'Robbie Daymond'),
('Sherbet Cookie', 'Ranged', 'Middle', 'Super Epic', 'sherbet-cookie.png', '2022-11-30', ARRAY['ice']::text[], ARRAY['chocolate', 'almond']::text[], 'Frost Shards|Cooldown = 13', '13', 'Summons 15 frost shards, divides them based on the number of targets, and attacks the enemies, cycling between them in the order of the highest ATK. Frost shards deal additional damage depending on the number of Frost stacks. Targets hit with frost shards are inflicted with Frost and Debuff Resist Bypass. There is a chance of hit targets to become Frozen as well. Frozen targets receive additional damage when thawed. The amount of this additional damage and the chance of becoming Frozen increases depending on the number of Frost stacks. Sherbet Cookie is partially immune to Freezing and, thanks to the Warm Light of Life effect, will convert healing that exceeds his Max HP to an HP Shield. While Sherbet Cookie is using his skill, he will briefly become resistant to interrupting effects.', 'Look! It’s the first snow of the year!', 'Here comes winter, where all life falls asleep under the soft blanket of snow. If you suddenly feel a gust of warm breeze on a chilly day, the frost spirit might have passed you by! Sherbet Cookie is always where the glistening first snow is falling gently on your windowsill. He takes the coldest and harshest winds with him, leaving you with the gift of cozy winter. No wonder everyone is waiting for this bright and friendly spirit’s arrival! Sherbet Cookie always dreamt of traveling the world, yet he was destined to become one with ice crystals. A single drop of warmness helped him turn into the freedom-loving sherbet snow spirit. Now, Sherbet Cookie never stays long in one place, traveling across the lands wherever the wind takes him. Still, there always will be a special memory that fills his heart with hope and warmth—a that will never stop waiting for his return!', 'Cold-proof, Nature-loving', 'Bryson Baugus'),
('Oyster Cookie', 'Support', 'Rear', 'Super Epic', 'oyster-cookie.png', '2022-06-14', '{}'::text[], ARRAY['chocolate', 'almond']::text[], 'Might of House Oyster|Cooldown=17|Initial=2', '17|Initial=2', 'The first cooldown of Oyster Cookie''s skill will be shortened, allowing for faster skill use. Summons soldiers of House Oyster and increases the CRIT% and CRIT DMG for herself and nearby allies for a certain amount of time. The summoned soldiers will immediately charge at the enemies, dealing damage. The soldiers will have extra DEF until the HP of their shields hits zero. Their shields will also resist Knockbacks and Flying. When Oyster Cookie receives a cooldown reduction buff, instead of cooldown reduction, the number of Oyster Soldiers and their ATK will increase. While Oyster Cookie is using her skill, she will briefly become resistant to interrupting effects.', 'Oyster Cookie. I believe that no further introduction is required.', 'Massive merchant vessels with mermaid statues adorning the stemhead fill the docks of the Crème Republic, all waiting for Oyster Cookie''s command. All it takes is one single wave to signal the giant ships to cross the ocean and create new tides. With her noble allure and eloquent words that can steer the conversation the way she wishes, one can''t help but be in awe of Oyster Cookie''s presence. Some Cookies wonder how a Cookie of the Sea could achieve such fame and prestige among the Republic''s crème de la crème. One theory is that House Oyster is somehow connected to the underwater mermaids from the old legends, but no one knows the truth. Oyster Cookie is known to exert her power and influence to create a favorable tide whenever precious goods and valuable information are involved. Perhaps that''s why the ambitious come knocking at Manor Oyster''s doors. Because some offers are worth risking it all!', 'Analytical, Underwater', 'Elley Ray'),
('Clotted Cream Cookie', 'Magic', 'Middle', 'Super Epic', 'clotted-cream-cookie.png', '2022-05-03', ARRAY['light']::text[], ARRAY['raspberry', 'almond']::text[], 'Consul''s Orders|Cooldown = 15', '15', 'The Cloak of Light, a marvel of the Republic''s cutting-edge technology, provides unquestionable advantages in battle. Upon using his skill, Clotted Cream Cookie projects the Light Cage onto the nearest enemy (targets Cookies first), blocking buffs and dealing area damage. The Light Cage cannot be dispelled and can be projected onto Cookies resistant to interrupting effects and prevents them from receiving removable buffs. The Light Cage will also inflict extra damage relative to the target''s HP at the end of its duration. While Clotted Cream Cookie is using his skill, he will become resistant to interrupting effects. DMG proportional to Max HP is capped at 300,000.', 'My name is Clotted Cream Cookie, elected Consul of the Crème Republic.', 'Impeccable posture, perfect necktie knot, and a charming smile! Add a generous amount of filling: a mixture of cream, ambition, and respectability, and you will get the Republic''s youngest Consul ever. Clotted Cream Cookie''s first achievement in office was the consolidation of the Republic''s fractured society. Even the Elders, whose authority in the city-state is unquestionable, recognize the Consul''s brilliance and eloquence. Indeed, Clotted Cream Cookie''s approval rating and influence are growing by the day! But beware: each of his sweet smiles is thoroughly calculated. This Cookie is always on the winning side.', 'Independent, Mysterious', 'Aaron Dismuke'),
('Ananas Dragon Cookie', 'Magic', 'Middle', 'Dragon', 'ananas-dragon-cookie.png', '2026-01-01', ARRAY['earth']::text[], ARRAY['raspberry']::text[], 'Golden Awakening', '14', 'As the Song of Dragontongue resonates, Ananas Dragon Cookie reclaims their ancient power and transforms into a mighty dragon, granting HP Shields and Golden Dragontongue to the team. Ananas Dragon Cookie unleashes a powerful roar and gains Dragon''s Power. Additionally, inflicts Fear on all enemies, applies Ananas Dragon''s Rage, and summons a Meteor, dealing damage. Fear from the roar cannot be removed by Purify and is not affected by Debuff Resist. Ananas Dragon Cookie then soars into the sky and crashes down, dealing damage, Knocking enemies back, and sending them Airborne. Gains Energy of the Earthbread; at max stacks, applies Rock Seal to their target. As the master of the earthbread, Ananas Dragon Cookie is immune to Rock Seal. At the start of battle, if Ananas Dragon Cookie''s Beascuit has 2 or more Earth-type DMG Up bonus effects, Dragon''s Power is enhanced.', 'Behold the glory of the dragons.', 'From the skies appeared a dragon with noble, golden scales as radiant as the sun. Upon the island''s tallest peak did the dragon decide to perch. All denizens of the island looked up in awe and presented various fruits as offerings. The island was home to blooming vibrant flowers and breathtaking waterfalls: a true paradise. Overflowing with pride in the prestige and power of Dragonkind, the dragon reigned supreme over the island At times a merciful and benevolent protector, but in others a fearsome and relentless oppressor. And suddenly, disaster struck. The towering offerings of fruit collapsed during a devastating earthquake. Rains and winds hammered the tower''s remnants, concealing the once glimmering light. From the chasm appeared a small figure made of dough, reclusing themselves from sight. The biding of time continues, for the day of spreading their wings in full glory has not yet arrived.', 'Tenacious, Brawny, Heat-proof', 'Keston John'),
('Pitaya Dragon Cookie', 'Charge', 'Front', 'Dragon', 'pitaya-dragon-cookie.png', '2023-05-18', ARRAY['fire']::text[], ARRAY['raspberry', 'chocolate']::text[], 'Draconic Bladestorm', '13', 'Pitaya Dragon Cookie fires off two waves of draconic blade energy, dealing damage and reducing the amount of Healing the targets receive. After this, the Cookie assumes their dragon form and spews flaming breath, applying Burn and reducing the targets'' ATK. Whenever Pitaya Dragon Cookie uses their skill, they gain a stack of Pitaya Fury that will enhance the skill upon reaching the maximum stacks. When using the enhanced skill, Pitaya Dragon Cookie''s flaming breath will deal damage and decrease the target''s resistance to Burn and Fire-type DMG. In their dragon form, the Cookie will gain increased CRIT% and remove all debuffs applied to themselves. As a Dragon Cookie, Pitaya Dragon Cookie will receive less damage from other Dragon Cookies and have their DMG Resist increased in proportion to their ATK enhanced with Toppings. While Pitaya Dragon Cookie is using their skill, they will briefly become resistant to interrupting effects.', 'Ssso you want to see my true form?', 'Eons ago, terrifying creatures roamed the land. Existing long before Cookies ran, there was a gargantuan Red Dragon with flames burning hotter than brimstone and scales shining brighter than rubies. Within the crater of a volcano, the dragon would wake with a thunderous roar that shook the heavens. Soaring the skies, this legendary behemoth terrorized the world with cataclysmic firestorms. Cookies of the past told tales of this tremendous creature meddling with mortal affairs and burning entire kingdoms down to the ground... until its powers suddenly began to wane. Could it be that one of the dragon''s nefarious deals went awry...? After biding time behind a veil of smoke and lava, a smaller and crispier form emerged: Pitaya Dragon Cookie. Will the world witness the dreaded firestorms of legend once more?', 'Venturous, Heat-proof', 'Andrew Morgado'),
('Timekeeper Cookie', 'Magic', 'Middle', 'Legendary', 'timekeeper-cookie.png', '2026-05-07', ARRAY['light']::text[], ARRAY['chocolate', 'raspberry']::text[], 'Temporal Stabilization', '15', 'Rides atop the Timeweaver Scissors to observe the expansion of the Timeline. Then deals damage to all enemies by stabilizing the Timeline. Applies Dial Lock to the 3 enemies with the highest ATK (excluding Timekeeper Cookie, targets Cookies first). If Dial Lock is removed, the target is immune, or its duration ends, it explodes, dealing damage to nearby enemies and inflicting Regression. When an enemy Cookie is Revived, Timekeeper Cookie detects Timeline instability and immediately applies an Emergency Dial Lock. Timekeeper Cookie accumulates Entropy when chaotic events disrupt the Timeline. At max Entropy, activates Stabilization Mode for a set duration. Timekeeper Cookie can Revive once per battle by reversing time and is immune to Dial Lock and Regression. Additionally, Timekeeper Cookie''s ATK increases proportionally to the Cooldown reduction from Toppings. Time manipulation powers increase Speed-up efficiency by 10%. When places in Production buildings, production time is accelerated by 5%.', 'Just in the nick of time!', 'A rip in the spacetime continuum appears in the air before your very eyes. Disbelief leads to shock as a small shadow appears from the torn fabric of reality, prompting nearby clocks to go haywire. Timekeeper Cookie rides upon the Sonic Embroider', 'Agile, Analytical, Sharp-eyed', 'Suzie Yeung'),
('Sugar Swan Cookie', 'Healing', 'Rear', 'Legendary', 'sugar-swan-cookie.png', '2026-01-01', ARRAY['light']::text[], ARRAY['applejelly', 'raspberry', 'chocolate']::text[], 'Wings of Sugar', '13', 'Sugar Swan Cookie grants Sweet Sugar Feather to her team, and rises in the air. She then spreads her wings, healing the team, and dealing damage to enemies. If there are no other Healing Cookies on the team except Sugar Swan Cookie, she will instantly revive a fallen Cookie. In this case, Sugar Swan Cookie will be removed from the battle but come back from the egg as a swan that does not take damage for a certain period of time. If Sugar Swan Cookie is defeated, she will immediately turn into the swan. In her swan form, Sugar Swan Cookie grants Sweet Sugar Feather to her team, unfolds Galaxy Lake around herself, periodically healing all allies except herself and granting Galaxy Lake Sanctuary. Sugar Swan Cookie will revive fallen allies while in her swan form as well. Upon returning to her Cookie form, Sugar Swan Cookie instantly uses her skill. If she does so, having used up all available revivals, she will grant Final Protection to all allies except herself—this effect triggers once per battle. After that, Sugar Swan Cookie will lose her powers and take the form of a little swan. The little swan regains her powers at given intervals. If there are no other Cookies left fighting and Sugar Swan Cookie has used all available revivals, the battle ends. If you equip the Treasure while Sugar Swan Cookie is on the team, Sugar Swan Cookie will have fewer available revivals. At the start of battle, Sugar Swan Cookie applies Breath of Life to herself. As the guardian of all living beings, the stronger Sugar Swan Cookie becomes, the stronger Aura of Vitality effect her allies will gain.', 'Do you wish to know how it all began?', NULL, 'Lucky, Nature-loving', 'Crystal Lee'),
('Millennial Tree Cookie', 'Healing', 'Front', 'Legendary', 'millennial-tree-cookie.png', '2025-12-17', ARRAY['grass']::text[], ARRAY['peanut', 'chocolate', 'raspberry']::text[], 'Millennial Tree', '8', 'Millennial Tree Cookie extends his roots into the earthbread and transforms into the World Tree, dealing damage to enemies. In this state, he will dispel all debuffs applied to himself and gain the World Tree HP Shield that cannot be affected by Zap or Overcurrent. Millennial Tree Cookie will also create a Sanctuary area where he will continuously restore allies'' HP (except Safeguarded Cookies) and the World Tree HP Shield. Once the World Tree HP Shield is removed, the Sanctuary effect will weaken. Also, Millennial Tree Cookie will scatter Sacred Seeds at certain intervals, dealing damage and restoring his own HP or his World Tree HP Shield. After the end of the World Tree''s duration, Millennial Tree Cookie will inflict the Equilibrium debuff upon the enemy from whom he received the greatest amount of damage during his transformation. If there are no enemies around Millennial Tree Cookie during his transformation, it will automatically cancel, and a portion of the remaining duration time will be deducted from his skill cooldown. If there are no Defense Cookies on the team, Millennial Tree Cookie will use Nature''s Protection. As the source of all elements, Millennial Tree Cookie gains the Elemental Seer buff if there are Cookies of 4 or more different elements on the team. Also, during his transformation, he will grant the Elemental Force buff to the team. If the Cookies are the Guardians of Nature, they will receive a stronger Elemental Force: The Guardians buff. At the beginning of the battle, Millennial Tree Cookie will gain the Majesty of Eons buff.', 'My roots spread far.', 'Deep inside a secret grove, there was a majestic ancient tree. Its roots went deep inside the ground and far to the very corners of the world. When the dark curse devoured the grove, the tree sealed itself in a magic slumber to resist the dark sorcery. With the help of the Cookies, Millennial Tree Cookie''s silence was finally broken. O Heart of the Seasons, it is time for the ancient roots to carry the force of the Life, for the fifth Season is afoot. Darkness is gathering, and only the Guardians of Nature can help Cookies vanquish it and make the world the blooming garden it once was...', 'Friendly, Nature-loving, Mysterious', 'Keith Silverstein'),
('Fire Spirit Cookie', 'Magic', 'Rear', 'Legendary', 'fire-spirit-cookie.png', '2025-04-09', ARRAY['fire']::text[], ARRAY['raspberry', 'chocolate']::text[], 'Ever-Burning Flames', '14', 'Fire Spirit Cookie flies towards his enemies, scorching his path, and dealing Periodic Damage. Afterwards, he causes Flame Explosion, dealing damage and inflicting Explosive Burn on enemies. Next, Fire Spirit Cookie channels his fire energy to launch a Fire Orb at the nearest enemy, causing Area Damage and Chain Explosion to nearby targets, ending when there are no more targets left. The Guardian of Fire applies Wall of Fire on the team at the start of battle. Additionally, his skill will be amplified when entering battle with other Fire-type Cookies: the more Cookies, the stronger his skill. If Fire Spirit Cookie is defeated in battle, he is Revived with Unquenchable Flames, and summons Flame Hydras if ally Cookies are defeated in battle. The embodiment of flames, Fire Spirit Cookie is resistant to Burn and Explosive Burn.', 'I am the fire!', 'Most Cookies merely adopted the flames of the Dragon''s Valley, but this legendary Cookie was born in it, molded by it. This mysterious Cookie lives in both the Cookie World and the Dragon World. The Bead that he carries is proof that he has either won the Red Dragon''s favor or has escaped with some kind of mischievous trade.', 'Venturous, Heat-proof', 'Austin Lee Matthews'),
('Wind Archer Cookie', 'Ranged', 'Rear', 'Legendary', 'wind-archer-cookie.png', '2024-09-04', ARRAY['wind']::text[], ARRAY['caramel', 'raspberry', 'applejelly']::text[], 'Last Wind|Cooldown = 6', '6', 'Upon transforming, Wind Archer Cookie removes all debuffs from himself, then shoots his Arrow of Gale, pushing back and stunning enemies, and applies the Trace of the Wind and Pursuer debuffs. While transformed, he will become immune to debuffs except for Curse and will shoot his Pursuer''s Arrows with his attacks. The Pursuer''s Arrow attacks up to five enemies with the highest ATK and applies the Trace of the Wind and Pursuer debuffs to its targets. Once Pursuer reaches max stacks, it will explode and inflict damage proportional to the targets'' Max HP, damage nearby enemies, and apply the Trace of the Wind debuff. Wind Archer Cookie applies the Mighty Gale buff to himself whenever he shoots the Pursuer''s Arrow. This Guardian Cookie casts Last Wind, which partially ignores the target''s DMG Resist and inflicts additional damage to enemies proportional to the number of Mighty Gale stacks. Affected enemies will be trapped in a Cyclone. When entering the battle, Wind Archer Cookie''s Max HP increases. (DMG proportional to Max HP is capped at 300,000.)', 'My arrow shall purify the darkness!', 'Originally, this Cookie was the wind who loved the green of the forest. This wind delightfully spent its day spreading fresh and sweet fragrances across the forest. In order to save the paradise in peril, a mysterious being granted it the power to purify the Darkness. This transformed the wind into Wind Archer Cookie, the protector of the forest. As long as Wind Archer Cookie''s heart keeps hope, he''ll carry on his duty.', 'Attentive, Agile', 'Kellen Goff'),
('Stormbringer Cookie', 'Charge', 'Front', 'Legendary', 'stormbringer-cookie.png', '2024-04-24', ARRAY['electricity']::text[], ARRAY['applejelly', 'raspberry']::text[], 'Lightning Blitzstorm|Cooldown = 13', '13', 'Stormbringer Cookie, the ruler of the skies and lightning, becomes Supercharged when her CRIT% exceeds a certain percentage at the start of the battle, granting Supercharge buffs to Electricity-type ally Cookies. When Stormbringer Cookie becomes Supercharged, her regular attacks trigger Chain Lightning after a certain number of hits. Upon using her skill, she swings her Heaven Splitter, dealing damage to enemies and inflicting Zap. Whenever ally Cookies deal Electricity-type damage, it activates Stormbringer''s Aura and inflicts Stormbringer''s Punishment upon a certain amount of stacks. Stormbringer''s Punishment deals damage and inflicts Overcurrent on enemies. If enemies are inflicted with Zap, they receive extra damage and their status changes to Overcurrent. Stormbringer''s Aura resets when Stormbringer''s Punishment is activated.', 'Who dares to challenge the skies?', 'Way up above, where clouds form and scatter, the Heaven-Splitter lies sheathed in the heaviest cloud. This divine weapon is the very essence of Stormbringer Cookie herself! Forged from the lightning that first struck Earthbread, legends tell that the Heaven-Splitter can cut anything into two. Its powers are so mystifying that it once split a huge tower and even created day and night by slashing through the skies! Then, Stormbringer Cookie gathered Life Powder and brought the Deities of Rain, Wind, and Clouds to life, thus creating the sacred cycle of Life Powder... This Cookie may sometimes laze around, munching on candied clouds, but whenever someone challenges her power, she wields her Heaven-Splitter high, ready to unleash her wrath! Be careful of what you pray to the skies, as even an inkling of arrogance will send Stormbringer Cookie to strike down with her lightning bolt!', 'Curious, Nature-loving', 'Monique Burias Shi'),
('Moonlight Cookie', 'Magic', 'Middle', 'Legendary', 'moonlight-cookie.png', '2023-01-19', '{}'::text[], ARRAY['chocolate', 'raspberry']::text[], 'Dream of the Night Sky|Cooldown = 15', '15', 'Moonlight Cookie falls asleep in the night sky and dreams a dream where stars fall onto the enemies'' heads, dealing damage and applying a DMG Increase debuff. Then, bright moonlight illuminates the battlefield, dealing damage to the enemies and putting them to Sleep. Enemies that didn''t fall Asleep become Drowsy and will eventually fall Asleep when their resistance statuses wear off. When Moonlight Cookie awakens, she will restore her own HP. She will also restore her own HP upon awakening from Sleep effects cast by enemies. Being a dweller of the World of Dreams, Moonlight Cookie is not susceptible to the Beckoning Dreams & Dream of Doom effect. (DMG relative to Max HP is capped at 300,000)', 'It is you who woke me up!', 'Moonlight Cookie''s graceful wavy hair shines under the night sky, elegant and mystical as ever. She was created by the ancient wizards and learned the secrets of the City of Wizards. Now, all the wizards are gone and she is the only one left to protect the city. She is the strongest while in her dreams, therefore is able to protect the city from intruders. Whenever she feels sad, she falls asleep, where she is able to lean by her friend Moon and draw in the night sky with her Star friends to cheer up.', 'Flying, Nature-loving', 'G.K. Bowes'),
('Black Pearl Cookie', 'Ambush', 'Middle', 'Legendary', 'black-pearl-cookie.png', '2022-09-06', ARRAY['water']::text[], ARRAY['chocolate', 'raspberry', 'applejelly']::text[], 'Duskgloom''s Sovereign', '15', 'Dives into the abyss and shifts into her true form, creating a whirlpool storm that deals periodic damage and drags in even enemies resistant to interruptions. Enemies, terrified of the Cookie''s giant size, suffer from Terror of the Abyss. If Terror of the Abyss is dispelled, the target will be inflicted with true damage proportional to the target''s Max HP. Being the ruler of the abyss herself, Black Pearl Cookie is resistant to all Fear effects. (Maximum amount of damage proportional to the target''s HP is 300,000)', 'Embrace the silence of the abyss!', '"There is something out there, hiding amidst the thick fog. Something ominous, capable of swirling all-consuming whirlpools and raising gigantic waves on a whim... The tale of Duskgloom Sea is true, you see, and its dark waters will reach every grain of sugar in your dough and silence your last scream..." It will be wise to avoid these treacherous waves—for their ruler can toss and wreck even the mightiest of ships as if they were mere toys. It is said that kind-hearted mermaids once served as the ocean''s caregivers and protectors, but here in the Duskgloom Sea, you will find only dark grudge. Nobody knows the reason behind Black Pearl Cookie''s century-old wrath, but with her on the underwater throne of wreckage, the Duskgloom Sea has gained its notoriety as the abyssal graveyard. She does not seek affection nor understanding, but then what is it that Black Pearl Cookie is looking for? What can pacify her cries of desperation?', 'Underwater, Nature-loving', 'Erica Mendez'),
('Frost Queen Cookie', 'Magic', 'Middle', 'Legendary', 'frost-queen-cookie.png', '2021-11-18', ARRAY['ice']::text[], ARRAY['raspberry', 'chocolate', 'almond']::text[], 'Freezing Squall|Cooldown = 15', '15', 'Casts an ice squall, dealing damage, freezing all enemies, and applying the Frost debuff. Once Frozen, the targets'' Cooldown will be paused and will receive an additional portion of damage when thawed. Targets resistant to Freezing receive only a portion of the DMG. If the Freeze debuff is dispelled, the targets will not receive the additional damage. Frost Queen Cookie herself is immune to freezing. While Frost Queen Cookie is using her skill, she will briefly become resistant to interrupting effects.', 'You cannot defy the cycle of life.', 'Somewhere amidst endless snow stands the lone castle of ice. In its halls of perpetual twilight dwells Frost Queen Cookie, the sovereign of winter itself. Like a fairytale queen, she dazzles with regal magnificence, yet her icy gaze leaves your soul cold and dreary, like tundra after a relentless blizzard. Her Cookie heart with all its mortal hopes and passions is long but frozen, all but one: her adamant will to accomplish her mission. A mission of utmost importance to the existence of the world. Ages might pass, but the castle of ice will remain: and so will Frost Queen Cookie, the guide for the myriads of Life-bearing snowflakes.', 'Cold-proof, Nature-loving', 'Cristina Vee'),
('Sea Fairy Cookie', 'Bomber', 'Middle', 'Legendary', 'sea-fairy-cookie.png', '2021-06-22', ARRAY['water']::text[], ARRAY['raspberry', 'chocolate', 'almond']::text[], 'Soaring Compassion|Cooldown = 16', '16', 'Fires a stream of water, inflicting damage and stunning 5 closest enemies (targets Cookies first). After a certain time, a full moon-shaped pool of water created underneath the targets bursts up with the power of eternity, dealing heavy damage.', 'I feel the warmth of your heart...', 'Sea Fairy Cookie was frozen under a curse long ago. But perhaps because of her grieving heart, her soul was frozen beyond magic. If it weren''t for the warm kindness of our Cookies, she might have chosen to stay frozen forever. Beyond her flowing hair, the twinkle in her eyes still states that she is willing to fight her fate. Let''s hope she does not let go of her sword, giving up hope and choosing to turn into sea foam.', 'Underwater, Nature-loving', 'Laura Post'),
('Pure Vanilla Cookie', 'Healing', 'Rear', 'Ancient', 'pure-vanilla-cookie.png', '2021-04-08', '{}'::text[], ARRAY['almond', 'chocolate', 'raspberry']::text[], 'Love & Peace|Cooldown = 15', '15', 'Illuminates the battlefield with his Vanilla Orchid Staff, granting Amplify Buffs to regular healing targets. The light reaches all corners of the battlefield, replenishing the party''s HP and reducing the effects of Injury. Pure Vanilla Cookie heals the amount of HP proportional to the reduction of Injury''s effects. He then casts an HP Shield absorbing an amount of damage proportional to their Max HP. If the Shield is removed or the target cannot receive it, Pure Vanilla Cookie instead grants a buff that restores HP over time. While Pure Vanilla Cookie is using his skill, he will briefly become resistant to interrupting effects.', 'The truth always prevails!', 'There are not many Cookies on Earthbread who could inspire hope as Pure Vanilla Cookie did. Born from nature-blessed cream and a fragrant vanilla bean, he was the epitome of Cookie kindness and faithfulness. Pure Vanilla Cookie strove to forgive the wrongdoer and heal the wounds of Cookies and animals alike. Though a powerful wielder of magic, he would use his spells not for his own good, but for the good of everyone. The Cookie took an arduous pilgrimage down the Sugar-Free Road. What Pure Vanilla Cookie learned through the Trials is unknown, but crowned with a bright halo of light he returned to found the Vanilla Kingdom, a land of freedom and learning, and a beacon for those seeking love and peace. Pure Vanilla Cookie stood by his friends until the very end, warding off the Darkness with a heartfelt smile.', 'Friendly, Mysterious', 'Yuri Lowenthal'),
('Hollyberry Cookie', 'Defense', 'Front', 'Ancient', 'hollyberry-cookie.png', '2021-09-02', ARRAY['steel']::text[], ARRAY['almond', 'chocolate']::text[], 'Oath on the Shield|Cooldown = 13|Initial = 1', '13|Initial = 1', 'Let out a war cry of fury! Hollyberry Cookie charges forward and becomes a shield to her Cookie allies, absorbing a portion of the damage they take, excluding periodic and indirect damage. While her DMG Focus is active, she will reduce CRIT received by her allies and herself, and gain a stack of Seed of Life for every CRIT hit she receives. Once she gains enough Seed of Life stacks, the Seed of Life will bloom into Berry of Life, enhancing the succeeding skill. The cooldown for Hollyberry Cookie''s first skill is reduced, allowing her to use it faster. While Hollyberry Cookie is using her skill, she will briefly become resistant to interrupting effects.', 'Blow the horn! Hollyberry Cookie has arrived!', 'What else could result in such an overwhelming passion if not the reddest hollyberries, ripened under the hottest summer sunlight? Hollyberry Cookie believes that every friendship, like every victory, should be triumphant. After all, there is nothing in the world as hard as trust! Not even the all-enduring Hollyberry Shield with which she swore to protect her beloved ones. It is said that Hollyberry Cookie leading a charge onto the battlefield is the most inspiring view. A view that inspires to repay with trust to those who put trust in you.', 'Serene, Friendly', 'Elizabeth Maxwell'),
('Dark Cacao Cookie', 'Charge', 'Front', 'Ancient', 'dark-cacao-cookie.png', '2022-02-24', ARRAY['darkness', 'electricity']::text[], ARRAY['almond', 'chocolate']::text[], 'Solemn Judgment|Cooldown = 13', '13', 'Swings the Grapejam Chocoblade with great force, causing thunder and lightning to inflict damage upon foes in range. This mighty attack reduces enemies'' ATK, DEF, and inflicts Zap and Injury. Injured foes will have reduced Max HP, and the Injury debuff ignores immunity and dispelling effects not mentioning Injury specifically. While Dark Cacao Cookie is using his skill, he will briefly become resistant to interrupting effects.', 'Great strength leads to bitter consequences...', 'The last bean, devoid of any sweetness, fell down from a withered branch of a lonely cacao tree growing above the edge of a cliff. Lying there in frozen soil, enduring snow and wind, this bean wasn''t aware of its destiny to become the main ingredient for the cold and reclusive Dark Cacao Cookie. A warrior of unheard strength, Dark Cacao Cookie wielded the Grapejam Chocoblade. This sword was so heavy it required three average Cookies to even budge it. With each swing, the skies erupted into thunder and lightning, avalanches tumbled down countless mountains. Dark Cacao Cookie was known as a Cookie of few words but great principle. After the Dark Flour War''s sorrowful events, the warrior locked himself away in the solitude of his own castle.... Will anything be able to melt his frozen soul once again?', 'Tenacious, Sharp-eyed', 'Patrick Seitz'),
('Golden Cheese Cookie', 'Ranged', 'Middle', 'Ancient', 'golden-cheese-cookie.png', '2023-09-26', ARRAY['earth']::text[], ARRAY['raspberry', 'chocolate']::text[], 'Brilliance of the Absolute|Cooldown = 13', '13', 'Upon using her skill, Golden Cheese Cookie throws her Spears of Radiance, dealing damage up to 8 times when there are five or more enemies. For each enemy defeated, she gains an extra Spear of Radiance. The number of Spears can increase to up to 12 in total. When hit by the spear, enemies receive a debuff amplifying the Earth-type damage received. While Golden Cheese Cookie is using her skill, she harnesses her Light of Abundance and hurls the Spear of the Absolute to the enemy Cookie with the highest ATK. The Spear of Absolute removes the target’s buffs, deals DMG, Explosion DMG, and additional DMG based on the current number of Spears of Radiance to all enemies in range. Once per battle, if Golden Cheese Cookie is about to be defeated, she encloses herself in a Sarcophagus for a certain period of time. While enclosed in her Sarcophagus, she casts a Shield around herself. This Shield takes the DMG dealt to nearby allies covered by it and provides Knockback Immunity. When using her skill, Golden Cheese Cookie is not affected by ATK Speed changes and is protected from the Glitch: Data Corruption effect by her Light of Abundance.', 'I am the Golden Sovereign!', 'Worship the Ever-Radiant Sovereign of the Golden City! Golden Cheese Cookie dwells in a gilded palace amidst the dunes of the Parmesan Desert. Cookies fall to their knees in exultation at the glimpse of her—body adorned with shining gold, godlike confidence, and magnificent wings. A mere flick of her wrist forms a golden mountain, another, a river—powers only a god can wield. Her greed knows no bounds, as this Cookie yearns for more to call her own, from treasures to even her faithful subjects. Following her desires, Golden Cheese Cookie filled the kingdom with riches, flowing freely like cheese fondue. She could’ve had it all: her eternal kingdom, the pinnacle of opulence and bliss. If it weren’t for that fated day, that is...', 'Flying, Sharp-eyed', 'Pilar Uribe'),
('White Lily Cookie', 'Bomber', 'Middle', 'Ancient', 'white-lily-cookie.png', '2024-01-19', ARRAY['grass']::text[], ARRAY['raspberry', 'chocolate']::text[], 'Lily Bud|Cooldown=15', '15', 'A pure white lily bud bursts open, dealing periodic damage to enemies and additional damage depending on the number of buffs White Lily Cookie has on herself. Enemies affected by the skill will become entangled in Vines, becoming unable to move or use skills. Whenever an ally Cookie gains a debuff, will gain the Lily Restoration buff, and whenever White Lily Cookie uses her skill, . Once Lily Restoration reaches a certain number of stacks, it will all current debuffs on the allies and heal them. White Lily Cookie is immune to the Spore Dispersal and Mushroom Mutation effects.', 'I wished to seek the truth...', 'A solitary beam of moonlight shines in the twilight. Like a pale lily touched by the gentle drops of rain, a Cookie silently entered the world. Her petals might look soft, and her dough frail, but nothing could stop her steps as she explored every corner of Earthbread, seeking a safer and happier future for all Cookiekind. Alas, at the end of her journey, all she found was the dark truth of this world. That truth painted her faith and curiosity with despair and anger, awakening a terrifying darkness deep within. Will White Lily Cookie find her lost voice once again amidst the deafening silence? With a seed of hatred and despair in her heart, will she walk towards the light once more?', 'Curious, Thorough', 'Erica Mendez'),
('Dark Cacao Cookie (Dragon Lord)', 'Charge', 'Front', 'Ancient', 'dark-cacao-cookie-dragon-lord.png', '2024-06-28', ARRAY['darkness']::text[], ARRAY['chocolate', 'almond', 'raspberry']::text[], 'Awakened King|Cooldown = 13', '13', 'With his newly found strength, swings the Chocoblade to deal damage, inflict Injury and Fatal Wound, and apply a CRIT debuff. After this, Dark Cacao Cookie will borrow the strength of the Twin Dragons for a forceful downward strike, increasing Darkness-type damage and applying Consuming Darkness and Gloom. At the beginning of battle, Dark Cacao Cookie will increase the allies'' DMG Resist with a Royal Decree. Inspired by his Kingly Presence, Channel Darkness will become more efficient for Dark Choco Cookie, and his DMG Resist will increase.', 'Who dare challenge me?!', 'Once, a lone sovereign''s head bowed in despair behind the impenetrable walls of his castle. Shrouded in darkness, his past was riddled with trials and tribulations—challenges that would have crumbled ordinary Cookies. Enemies tried to infiltrate the walls, greedy hands sought the crown, and even his own son betrayed him. Despite his bitter and destitute life, two things never lost their shine: his pride as a ruler and his resolve, pitch dark as obsidian. Even when his dough crumbled from scaling the rocky mountains, even when he lost everything and everyone dear to him, his resolution remained unwavering and true. Now, he stands stronger than ever, commanding the two dragons that resting on his shoulders. This Cookie does not cower behind walls. He stands tall and regal, revered by his loyal subjects. His sword is raised high in triumph, sworn to protect the Cookie world, and his name is none other than… Dark Cacao Cookie.', NULL, 'Patrick Seitz'),
('Golden Cheese Cookie (Immortal)', 'Ranged', 'Middle', 'Ancient', 'golden-cheese-cookie-immortal.png', '2024-10-30', ARRAY['earth']::text[], ARRAY['raspberry', 'chocolate']::text[], 'Radiance of the Immortal|Cooldown = 13', '13', 'Upon using her skill, Golden Cheese Cookie spreads her wings and throws her Spears of the Immortal, dealing damage up to 8 times when there are five or more enemies. For each enemy defeated, she gains an extra Spear of the Immortal. The number of Spears can increase to up to 12 in total. When hit by the Spear, enemies receive a debuff amplifying Earth-type damage and decreasing CRIT% and CRIT DMG. While Golden Cheese Cookie is using her skill, she will inflict Immortal''s Retribution on the enemy with the lowest HP, applying Curse, Immortal''s Punishment, Healing Prevention, and dealing damage. She then deals explosion damage to nearby enemies and additional damage proportional to her Spear of the Immortal stacks. Once per battle, Golden Cheese Cookie will revive and enter the Immortal''s Return state. In this state, her DMG Resist, ATK, and DEF will increase. Golden Cheese Cookie will also cover the team with the Dome of Gold that will take damage instead of the allies and make them immune to Knockback. The great Immortal Golden Cheese Cookie increases all Ranged Cookies'' DMG Resist and ATK. (DMG proportional to Max HP is capped at 300,000.)', 'Who can wield such power, if not I, Golden Cheese Cookie?', 'What palm can hold every grain of sand without spilling a single one? This question has long haunted Golden Cheese Cookie. Many have doubted her dreams and desires over the years. To others, she was always a Cookie fretting over trinkets, boasting, bluffing, and stubbornly grasping onto her spear, unable to let go. And yet... Time over time, armed with boundless ambition alone, this Cookie managed to shift tides in her favor, greedily turning her most daring fantasies into reality against impossible odds. Now, Golden Cheese Cookie''s wings have carried her onto even greater heights, her golden radiance shining as brightly as her heart. May your name go down in history, O Radiant Queen!', NULL, 'Pilar Uribe'),
('Pure Vanilla Cookie (Compassionate)', 'Healing', 'Rear', 'Ancient', 'pure-vanilla-cookie-compassionate.png', '2025-02-12', ARRAY['light']::text[], ARRAY['raspberry', 'almond', 'peanut']::text[], 'Warmth of Compassion|Cooldown = 15', '15', 'Pure Vanilla Cookie fully heals the team and reduces Injury. He will further heal the team for the amount of HP recovered from the reduced Injury. Provides HP Shield for all members of the team. Whenever these HP Shields are dispelled, or the target becomes unable to have an HP Shield, periodically heals the team for a certain period of time. Next, he will summon Shards of Light that will heal your team and deal damage to enemies, applying the Shards of Light debuff. As long as Pure Vanilla Cookie participates in the battle, he will select a Cookie and illuminate them with the Light of Truth to restore their HP when it drops below a certain point. Pure Vanilla Cookie will keep restoring their HP periodically for some more time. This effect can trigger only once in a certain period of time. As someone who has witnessed both the Truth and Deceit, Pure Vanilla Cookie will grant the team immunity from Silence and Cooldown debuffs at the beginning of battle if there are no other Healing Cookies in the rear row. Once per battle, when his own HP drops below a certain point, he will restore his HP, gain an HP Shield, and dispel all possible debuffs on himself. Additionally, once per battle, Pure Vanilla Cookie will revive one team member, himself included. However, this effect will not trigger if the entire team is defeated mid-revival or if the target has already been revived. The higher Pure Vanilla Cookie''s DMG Resist stat, the stronger Cooldown buff he will receive at the beginning of the battle. His regular attacks will heal up to 5 targets and increase their Amplify Buffs.', NULL, 'What is the Truth? Long ago, Pure Vanilla Cookie picked up his trusty staff and set off on a pilgrimage to find an answer to this question. Having left behind the careless days in the idyllic pastures and the trials of the Sugar-Free Road, Pure Vanilla Cookie was left face to face with his fears and regrets. In the moment of the greatest doubt, the Cookie of Truth gave in to the dark abyss of Deceit. And yet... the voices of dear friends awakened him. Having embraced his flaws and mistakes, Pure Vanilla Cookie could find his way back to the light once more. The path ahead is hard and full of peril, but it is nothing more than a sum of little steps. And in those steps dwells the Truth.', NULL, 'Yuri Lowenthal'),
('Hollyberry Cookie (Aegis)', 'Defense', 'Front', 'Ancient', 'hollyberry-cookie-aegis.png', '2025-06-04', ARRAY['steel']::text[], ARRAY['almond', 'chocolate', 'peanut']::text[], 'Shield of Conviction|Cooldown = 13', '13', 'Sound the charge! Hollyberry Cookie charges forward with her Shield of Conviction. While her Shield of Conviction is active, she will absorb a portion of the damage allies take, excluding periodic and indirect damage. Afterwards, she will buff ally Cookies, reducing incoming CRIT DMG and making them resistant to DMG debuffs. Hollyberry Cookie will gain the Seed of Life buff depending on the amount of damage received during Shield of Conviction. Once she gains enough Seed of Life stacks, it will bloom into Berry of Life. Steelbound Passion will activate depending on the amount of damage received during Shield of Conviction or after a certain period of time. Steelbound Guardian will activate once Hollyberry Cookie has gained enough stacks of Steelbound Passion or when her HP drops below a certain level. Entering the Steelbound Guardian state will reset Hollyberry Cookie''s Cooldown, restore HP, and enhance Shield of Conviction. Her Final Hit will be buffed depending on the damage received during Shield of Conviction. The Cooldown for Hollyberry Cookie''s first skill activation is reduced, and while she is using her skill, she will briefly become resistant to interrupting effects.', 'Back into the fray!', '"Sound the charge!" With her trusty shield aloft, Hollyberry Cookie''s mighty presence alone can instill courage and confidence on the battlefield. In the past, not only did she unite the ever-squabbling Berry Houses, but she was also always be the first to extend a friendly hand, earning the Hollyberrians'' unconditional trust and respect. And yet, no matter how strong the hero is, no one can carry the crushing weight of responsibility alone. Little by little, her heart, hidden behind the steel of her shield, began to show cracks until there was no other option left but to run away. But even so, Hollyberry Cookie''s will to protect her dear ones never faded. Clad in her new armor, the hero raises her shield once again. Begin the battle song! Hollyberry Cookie has returned.', NULL, 'Elizabeth Maxwell'),
('White Lily Cookie (Dawnbringer)', 'Bomber', 'Middle', 'Ancient', 'white-lily-cookie-dawnbringer.png', '2025-10-22', ARRAY['grass']::text[], ARRAY['chocolate', 'raspberry', 'peanut']::text[], 'Freedom''s Bloom|Cooldown = 15', '15', 'A flower bud that sprouted through adversity bursts open, dealing periodic damage to nearby enemies and additional damage depending on the number of buffs White Lily Cookie has on herself. Enemies affected by the skill will become entangled in Vines, unable to move or use skills for a certain time. The Bloom of Freedom deals damage to nearby enemies, increases the Grass-type DMG they take, and applies the Seeds debuff. The Seeds will sprout after some time, dealing damage to nearby enemies and entangling them in Vines. Seeds'' sprouting time will decrease whenever the target receives Healing. Whenever White Lily Cookie uses her skill or when any team member gains a debuff, they will gain the Dawn Lily Restoration buff. Once Dawn Lily Restoration reaches a certain number of stacks, it will dispel all debuffs and heal the targets, while granting Petals of Restoration to certain Cookies from the team. At the start of the battle, certain Cookies from the team will gain Petals of Restoration. White Lily Cookie cannot be Silenced or Shackled. Once per battle, if White Lily Cookie is defeated, she will become unable to act but will be protected by Remembrance of Yearning for a short while.', 'For Freedom...!', 'Why are Cookies baked so sweet, yet so fragile...? White Lily Cookie''s story began with a question. On her way to the greater world full of wonder and mystery—to the place that held the answer—she encountered many more. Yet on this same path guided by curiosity, she made countless missteps and faced mistakes that could never be mended nor forgiven. In the end, cruel truth and darkness awaited White Lily Cookie... But was it the end? A delicate blossom of hope in the dark held new questions within. What does it mean to be a Cookie? Can Cookies truly be happy in this world? There are still truths to be brought to light, and White Lily Cookie rises again, her banner proud. Her dough may break and shatter, yet she will keep taking steps towards the place where Freedom dwells.', NULL, 'Erica Mendez'),
('Mystic Flour Cookie', 'Healing', 'Rear', 'Beast', 'mystic-flour-cookie.png', '2024-05-22', '{}'::text[], ARRAY['chocolate']::text[], 'Whispers of Apathy|Cooldown = 15', '15', 'Creates the Realm of Apathy, shielding the allies with the Cocoon of Futility. Allies within the Realm of Apathy have their HP periodically restored. They will also gain the Touch of Meaninglessness buff. Once the duration of the Realm of Apathy is over, the allies will be Healed for a portion of the DMG they have dealt. The Cocoon of Futility cannot be Dispelled or removed by Zap or Overcurrent. The effect will remain even after the HP Shield reaches 0 capacity. If the target is at Max HP, incoming Healing will restore the HP Shield instead. If an enemy Cookie enters the Realm of Apathy, their Cooldown will be increased, their ATK SPD will be reduced. They will also be debuffed with the Pale Plague, increasing the remaining Cooldown when dispelled. Mystic Flour Cookie will increase her own DMG Resist based on the decreased amount of Cooldown. Her Lantern of Apathy will keep healing the allies regardless of Mystic Flour Cookie''s current status and will be further enhanced when she is defeated. If there are no Safeguarded Cookies in the team, Mystic Flour Cookie cannot be incapacitated, and gains increased Max HP. The amount of Healing coming from the Lantern of Apathy and its trigger rate will also greatly increase. Ally Cookies will also be provided with Buff Protection. Mystic Flour Cookie is immune to Apathy along with all targets of the Cocoon of Futility and disrupts the Power of Apathy effect affecting enemies.', 'Everything shall return to flour...', 'An absence of color. Pure, undistilled white flour that symbolizes freedom, enlightenment... and futility. When magic first blessed these lands, Mystic Flour Cookie was revered as a saint—capable of granting wishes both big and small. Yet, as the crowds faded away, she was left with only apathy. Her once radiant light tarnished, leading her to join forces with the fallen Beast Cookies. Despite everything, Mystic Flour Cookie neither feels anger nor sadness, as wishes are nothing but mere illusions, and all worldly desires are destined to disappear one day. A world of nothingness. A world where every Cookie is liberated from burden. That is the perfect world she envisions. Once reaching that enlightenment, one shall open their eyes to the blinding truth: Apathy.', 'Analytical, Mysterious', 'Jessica Pennington'),
('Burning Spice Cookie', 'Charge', 'Front', 'Beast', 'burning-spice-cookie.png', '2024-10-02', ARRAY['fire']::text[], ARRAY['raspberry', 'almond']::text[], 'Tyrant''s Wrath|Cooldown = 9', '9', 'In exchange of his own lifeforce, Burning Spice Cookie releases his inner God of Destruction, dispelling debuffs and gaining the Berserker buff. While transformed, he will become immune to all debuffs except for Curse and will absorb the ATK of the three allies (targets Cookies first) with the highest ATK. Burning Spice Cookie will gain the Spice Rampage buff depending on the target of his basic attacks and will gain the buff after reaching a certain threshold. After, he will slam down the ground with his great axe, dealing damage with the final blow. The axe will create a pool of lava for a certain period of time and deal periodic damage. Enemies'' ATK SPD and ATK are reduced in the lava, while the Sarcophagus of Gold and summons receive a great amount of damage. The Great Destroyer, Burning Spice Cookie, activates Firestorm periodically, inflicting Burn to all targets (excluding Safeguarded Cookies) and providing CRIT% and CRIT DMG buffs for his allies. Additionally, he applies The Destroyer''s Gaze on the enemy Cookie with the highest ATK. Upon entering the battle, Burning Spice Cookie applies the Revelry of Flames buff on Fire-type allies, which increases their ATK and DMG Resist by the number of Burn stacks. Additionally, Burning Spice Cookie''s CRIT% increases according to the number of nearby targets with Burn. When hit by Water-type attacks for a certain number of times, a Burn debuff is removed. If Burning Spice Cookie is defeated, he becomes for a certain period of time and dispels debuffs. (DMG proportional to Max HP is capped at 300,000)', 'Your destruction shall be my greatest pleasure!', 'While the losers are doomed to be swallowed whole by the Tide of Change, victors bend it to their will! Once known as the Herald of Change, Burning Spice Cookie shaped the course of history, when history itself was young. He was hailed as a hero, a leader who fought battle after battle to protect the faint light of civilization shining amidst the gloom. But as time marched on and kingdoms rose and fell in an endless cycle, he grew weary—bored by the monotony of it all. In his heart, the seeds of destruction began to take root. His name, once celebrated, was replaced by whispers of the Great Destroyer. But empty praises and worship from Cookies meant nothing to him, as only destruction could make his jam boil! During his long confinement, he cursed the chains that bound him, aching to unleash chaos. But now, Burning Spice Cookie is free, unchained, and ready to carve a path of havoc. The world will tremble as the Great Destroyer rises once more... and nothing will be spared.', 'Brawny, Heat-proof', 'Erik Braa'),
('Shadow Milk Cookie', 'Magic', 'Middle', 'Beast', 'shadow-milk-cookie.png', '2025-01-15', '{}'::text[], ARRAY['raspberry', 'chocolate', 'applejelly']::text[], 'Act 1: Lies|Cooldown=11|Initial=2', '11|Initial=2', 'Shadow Milk Cookie channels the energy of his other-realm to begin a grand spectacle of Deceit. Inflicts Puppet Show at the enemy with the lowest Max HP (targets Cookies first excluding Safeguarded Cookies). The opponent''s Shadow Milk Cookie cannot become a target unless no other possible targets are left. For the duration of Puppet Show, both the target and the nearby enemies sustain periodic damage. The effect ends with a Grand Finale. Grand Finale deals damage to all enemies, deals damage proportional to Puppet Show''s target, and applies Taint on them. If the target is defeated before the end of Puppet Show''s duration, a Soul Phantom will appear in their place. A portion of the damage sustained by the Soul Phantom until the end of Puppet Show will be inflicted as Grand Finale''s extra damage. If Shadow Milk Cookie is defeated, he will assume his Shadow Form. He will summon his to fool the enemies and retreat to the other-realm where he will gain Power of Deceit. The Shadow Form effect will last until the defeated. At the beginning of the battle, Shadow Milk Cookie will summon the Eye of Truth. Depending on the number of debuffs received by the team, including Shadow Milk Cookie himself, the Eye of Truth will gain stacks of Truth. More stacks of Truth will be gained whenever Shadow Milk Cookie uses his skill. At a certain number of stacks, the Eye of Truth will remove all debuffs from the team and increase the amount of damage dealt by Shadow Milk Cookie at the expense of a greater amount of damage received. When Shadow Milk Cookie gains Power of Deceit, the Eye of Truth will transform into the Eye of Deceit, periodically gaining new stacks of Truth. At a certain number of stacks, it will emit a Tenet of Deceit, dealing damage and resetting the duration of Taint on the target (damage proportional to Max HP is capped at 300,000).', 'Seriously, who can say "no" to a pinch of good old Deceit?!', '"Ahh, welcome, welcome! Why the surprised look? Oh, but we''ve met before, or have you forgotten? For I am the shadow living in your soul—a lie!" What could have happened to this Cookie, once heralded as the Fount of Knowledge, that made him become the Master of Deceit. Eons ago, when Earthbread was still young, the radiance of Knowledge was born to bless all that was with meaning. Yet, in the shadow cast by this light, dwelled its twin, Deceit. With time, all those disenchanted with the bitter Truth turned their eyes to the alluring tapestry of lies spun by the silver-tongued trickster. Masterfully juggling truths and falsehoods on the scene of a whimsical shadowplay, Shadow Milk Cookie has perfected his craft of shattering beliefs of the most stoic in a myriad of treacherous reflections. Applause, applause! It is time to raise the curtain, for the show to plunge the world into never-ending chaos is about to begin...', 'Independent, Mysterious', 'CJ Pawlikowski'),
('Eternal Sugar Cookie', 'Bomber', 'Middle', 'Beast', 'eternal-sugar-cookie.png', '2025-05-07', ARRAY['poison']::text[], ARRAY['chocolate', 'raspberry', 'applejelly']::text[], 'Eternal Enchantment|Cooldown = 12|Initial = 2', '12|Initial = 2', 'Eternal Sugar Cookie floats atop a cotton candy cloud, restoring her own HP, and gains an HP Shield and Immunity. She summons a Saccharine Breeze, Charming enemies and dealing Periodic Damage. Affected enemies suffer from the Delightful Temptation debuff, while Immune targets receive damage. Afterwards, the sugar coating cracks, dealing damage and putting enemies into an Enchanted state. Enchanted''s duration increases based on the number of stacks. When Enchantment is dispelled, its duration is over, or the target is immune, the effect changes to Laxness. If the target is immune, they receive additional damage. Eternal Sugar Cookie''s mythic beauty makes enemies who deal damage to her gain the Guilt debuff. At maximum stacks, Guilt will deal damage to the target in proportion to their ATK. The target will also receive Increased Damage and Reduced Healing. At the start of a battle, Eternal Sugar Cookie will appear floating atop a cotton candy cloud, surrounded by her Cotton Candy Angels. The Cotton Candy Angels will follow the rest of the team, buffing them and themselves, and dealing damage and debuffing the enemies. The fewer team members are left on the battlefield, the stronger this effect becomes. Eternal Sugar Cookie herself is resistant to Charm, Enchantment, and Laxness.', 'I''ll make you a happy Cookie... FOREVER!', 'Eons ago, there lived a Cookie, blessed with sweetness absolute. "Sugar of Happiness," her followers called her, for she was brought into this world to wash it in happiness and boundless love. Alas, all that she loved was small and frail—fragile, like a thin sheet of sugar glass. Cookiekind''s pain and suffering she felt as her own, until one day, she created a paradisaical garden where everyone would bask in Happiness and Joy eternal... so long as they accepted Sloth. Thus, Eternal Sugar Cookie became her name. Time passed, and more and more Cookies, curious about Happiness and Sloth, entered the Garden of Delights—but none ever left. Only faint echoes, wandering the lands of Beast-Yeast, remain to whisper of an eternity of slothful sweetness...', 'Serene, Thorough', 'Gabi Manoukian'),
('Silent Salt Cookie', 'Ambush', 'Front', 'Beast', 'silent-salt-cookie.png', '2025-09-24', ARRAY['darkness', 'steel']::text[], ARRAY['raspberry', 'chocolate']::text[], 'End of Silence|Cooldown = 14|Initial = 2', '14|Initial = 2', 'Silent Salt Cookie calls upon the power of the eclipse to summon his steed, Nox Black Salt, and put his enemies to the state of Silence Eternal. Next, he charges forward astride Nox Black Salt, cutting the shaded moon in half to make it explode, dealing great damage to enemy units. At the beginning of the battle, Silent Salt Cookie delivers Fury of the Catacombs to the enemy with the highest ATK (targets non-Safeguarded Cookies first). Silent Salt Cookie himself is not affected by Fury of the Catacombs, unless he is the only Cookie on the team. Once Fury of the Catacombs is fully stacked, its target receives Punishment. When the target is defeated, Fury of the Catacombs moves on to the next target with the highest ATK. Once the team''s HP drops below a certain point, the 7 enemies with the highest ATK (targets non-Safeguarded Cookie first) will be inflicted with Wrath of the Catacomb that will instantly trigger the Silent Demise effect. Silent Salt Cookie''s Forsaken Freedom renders him immune to all Cooldown-impairing effects. When affected by Cooldown-increasing or pausing effects, Silent Salt Cookie will gain an HP Shield along with DMG Resist and Cooldown Recovery buffs.', 'Silence shall reign.', 'It is said that he never ruled like the other Emissaries of the gods. Instead, he stood as the first among equals, bound by the oath of Solidarity. He and his loyal knights thus preached his Virtue across the Great Barren. Alas... Was the weight of his divine mission too great to bear alone? Even he, a warrior of unparalleled discipline, fell to whispers of corruption. After unleashing a calamity that claimed the lives of every Cookie who stood with him, he was sealed by magic, condemned to an eternity in darkness. His countless victims were cursed to wander endlessly through the land no living Cookie dared tread—the Land of Silence, as it was now called. Yet this tale was not destined to end there. Eons later, the Beasts awoke once more. Now, clad in black armor, gleaming in the pale, salt-crystal light of the moon, Silent Salt Cookie returns to his domain, carrying the same haunting stillness he left behind when he first swung his sword as the Devil of Silence.', 'Attentive, Sharp-eyed', 'Ray Chase'),
('Dark Enchantress Cookie', 'Magic', 'Middle', 'Witch', 'dark-enchantress-cookie.png', '2026-01-14', ARRAY['chaos']::text[], ARRAY['raspberry', 'chocolate']::text[], 'Visions of Doom', '16', 'A bottomless Abyss unfolds on the battlefield, immobilizing all enemies within its range. The Abyss increases their Cooldown and drains their HP, converting it to HP Shield that cannot be removed. Abyssal Chains dispel enemy HP Shield and make enemies unable to gain new HP Shields. Other targets become Stunned. After the Abyss has consumed enough magic energy, it deals damage to all enemies, applying Injury. With its last powerful hit, the Abyss will turn some enemies into Failed Creations. Each hit of the Abyss applies Dark Enchantress''s Curse. A Legendary, Ancient, Dragon, Beast, or Super Epic Cookie with the highest ATK becomes a Failed Creation. This effect cannot be prevented by skills that can make the target resistant or immune to incapacitating effects, or dispelled, and cannot be affected by the Debuff Resist stat. All Epic or lower rarity Cookies become Failed Creations, and other targets become Stunned. Failed Creations share a part of damage taken by Dark Enchantress Cookie. When they are defeated, Dark Enchantress Cookie is healed. Dark Enchantress Cookie will consume magic energy to become stronger whenever she uses her skill and whenever an ally or enemy is defeated. Her DMG Dampening and ATK will increase proportionally to the amount of magic energy consumed. Upon reaching a certain number of stacks, Dark Enchantress Cookie will gain the Magic Overflow status. In this state, she can Revive once, and her regular attacks, as well as her skill, will deal more damage. Darkness Unleashed, triggering at certain intervals and dealing damage, will also become enhanced in this state. Dark Enchantress Cookie''s Cooldown will decrease in proportion to her ATK boosted with Toppings. Also, her ATK will increase in proportion to her Cooldown reduced with Toppings. At the beginning of a battle, Dark Enchantress Cookie will briefly become immune to debuffs (once per battle).', 'Are you prepared to look into Darkness?', 'It is said that every thousand years, all witches from near and far come together for the Night of the Witches. And on that very night, Dark Enchantress Cookie was born. A dose of concentrated dark magic and poisonous scarlet pomegranate syrup gives this Cookie a deliciously evil taste. Since the moment of her creation, Dark Enchantress Cookie was filled with sweet ambition. She brought chaos to the Night of the Witches gathering and escaped with the dark secrets of the creators... Now, her grand design threatens Heroes, awakens Beasts, and seeks to shatter the very order of the Cookie World. Have this Cookie''s ambitions and adamant beliefs faded into the shadows? When countless Cookies face a future of suffering and ruin, this Cookie merely smiles. Step by step, she carefully prepares for the Final Banquet. A new world will be forged when destiny is cast aside—so may Darkness reign forever on Earthbread!', '|va_kor = Nam Yu-jeong (남유정)', 'Patty McCormack');
